--
-- Name: validate_one_decision_event(uuid); Type: FUNCTION; Schema: audit; Owner: -
--

CREATE FUNCTION audit.validate_one_decision_event(p_event_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_kind audit.decision_kind;
  v_total integer;
  v_expected integer;
BEGIN
  SELECT decision_kind INTO v_kind
  FROM audit.decision_event
  WHERE decision_event_id = p_event_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT
    (SELECT count(*) FROM audit.decision_event_assertion_review x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_assignment_review x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_claim_review x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_relation_review x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_rights_observation x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_rights_assessment x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_policy_evaluation x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_delivery_assessment x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_attribution_validation x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_takedown x
      WHERE x.decision_event_id = p_event_id) +
    (SELECT count(*) FROM audit.decision_event_visual_bridge_review x
      WHERE x.decision_event_id = p_event_id)
  INTO v_total;

  v_expected := CASE v_kind
    WHEN 'assertion_review' THEN
      (SELECT count(*) FROM audit.decision_event_assertion_review x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'assignment_review' THEN
      (SELECT count(*) FROM audit.decision_event_assignment_review x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'claim_review' THEN
      (SELECT count(*) FROM audit.decision_event_claim_review x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'relation_review' THEN
      (SELECT count(*) FROM audit.decision_event_relation_review x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'rights_observation' THEN
      (SELECT count(*) FROM audit.decision_event_rights_observation x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'rights_assessment' THEN
      (SELECT count(*) FROM audit.decision_event_rights_assessment x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'provider_policy_evaluation' THEN
      (SELECT count(*) FROM audit.decision_event_policy_evaluation x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'delivery_assessment' THEN
      (SELECT count(*) FROM audit.decision_event_delivery_assessment x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'attribution_validation' THEN
      (SELECT count(*) FROM audit.decision_event_attribution_validation x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'takedown' THEN
      (SELECT count(*) FROM audit.decision_event_takedown x
       WHERE x.decision_event_id = p_event_id)
    WHEN 'visual_bridge_review' THEN
      (SELECT count(*) FROM audit.decision_event_visual_bridge_review x
       WHERE x.decision_event_id = p_event_id)
  END;
  IF v_total <> 1 OR v_expected <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'AUDIT_DECISION_EVENT_EXACT_SUBTYPE_VIOLATION';
  END IF;
END
$$;


--
-- Name: enforce_entity_subtype(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.enforce_entity_subtype() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := COALESCE(to_jsonb(NEW), to_jsonb(OLD));
  v_entity_id uuid := COALESCE(
    (v_row ->> 'entity_id')::uuid,
    (v_row ->> 'archive_object_id')::uuid,
    (v_row ->> 'agent_id')::uuid,
    (v_row ->> 'place_id')::uuid,
    (v_row ->> 'concept_id')::uuid,
    (v_row ->> 'collection_id')::uuid,
    (v_row ->> 'temporal_extent_id')::uuid
  );
  v_kind core.entity_kind;
  v_count integer;
  v_matches boolean;
BEGIN
  SELECT e.entity_kind INTO v_kind
  FROM core.entity AS e WHERE e.entity_id = v_entity_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  SELECT
    (SELECT count(*) FROM core.archive_object a WHERE a.archive_object_id = v_entity_id)
    + (SELECT count(*) FROM core.agent a WHERE a.agent_id = v_entity_id)
    + (SELECT count(*) FROM core.place p WHERE p.place_id = v_entity_id)
    + (SELECT count(*) FROM core.concept c WHERE c.concept_id = v_entity_id)
    + (SELECT count(*) FROM core.collection c WHERE c.collection_id = v_entity_id)
    + (SELECT count(*) FROM core.temporal_extent t WHERE t.temporal_extent_id = v_entity_id)
  INTO v_count;

  v_matches := CASE v_kind
    WHEN 'archive_object' THEN EXISTS (SELECT 1 FROM core.archive_object a WHERE a.archive_object_id = v_entity_id)
    WHEN 'agent' THEN EXISTS (SELECT 1 FROM core.agent a WHERE a.agent_id = v_entity_id)
    WHEN 'place' THEN EXISTS (SELECT 1 FROM core.place p WHERE p.place_id = v_entity_id)
    WHEN 'concept' THEN EXISTS (SELECT 1 FROM core.concept c WHERE c.concept_id = v_entity_id)
    WHEN 'collection' THEN EXISTS (SELECT 1 FROM core.collection c WHERE c.collection_id = v_entity_id)
    WHEN 'temporal_extent' THEN EXISTS (SELECT 1 FROM core.temporal_extent t WHERE t.temporal_extent_id = v_entity_id)
    ELSE false
  END;

  IF v_count <> 1 OR NOT v_matches THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'ENTITY_SUBTYPE_EXACTLY_ONE_VIOLATION';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_legacy_identity_resolution(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.enforce_legacy_identity_resolution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := COALESCE(to_jsonb(NEW), to_jsonb(OLD));
  v_resolution_id uuid := COALESCE(
    (v_row ->> 'legacy_identity_resolution_id')::uuid,
    (SELECT s.legacy_identity_resolution_id
     FROM core.legacy_identity_split_successor s
     WHERE s.successor_archive_object_id = (v_row ->> 'successor_archive_object_id')::uuid
     LIMIT 1)
  );
  v_identity_id uuid;
  v_kind core.legacy_identity_kind;
  v_state core.identity_resolution_state;
  v_target_count integer;
  v_split_count integer;
  v_current_count integer;
BEGIN
  SELECT r.legacy_identity_id, i.identity_kind, r.resolution_state,
    num_nonnulls(r.target_archive_object_id, r.target_source_record_id,
      r.target_trace_node_id, r.target_folder_id)
      + CASE WHEN r.target_trace_edge_release_id IS NULL THEN 0 ELSE 1 END
  INTO v_identity_id, v_kind, v_state, v_target_count
  FROM core.legacy_identity_resolution r
  JOIN core.legacy_identity i ON i.legacy_identity_id = r.legacy_identity_id
  WHERE r.legacy_identity_resolution_id = v_resolution_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF (v_kind = 'archive_object'
      AND v_state NOT IN ('split','unresolved','withdrawn')
      AND NOT EXISTS (
      SELECT 1 FROM core.legacy_identity_resolution r
      WHERE r.legacy_identity_resolution_id = v_resolution_id
        AND r.target_archive_object_id IS NOT NULL))
    OR (v_kind = 'source_record'
      AND v_state NOT IN ('split','unresolved','withdrawn') AND NOT EXISTS (
      SELECT 1 FROM core.legacy_identity_resolution r
      WHERE r.legacy_identity_resolution_id = v_resolution_id
        AND r.target_source_record_id IS NOT NULL))
    OR (v_kind = 'trace_node'
      AND v_state NOT IN ('split','unresolved','withdrawn') AND NOT EXISTS (
      SELECT 1 FROM core.legacy_identity_resolution r
      WHERE r.legacy_identity_resolution_id = v_resolution_id
        AND r.target_trace_node_id IS NOT NULL))
    OR (v_kind = 'folder'
      AND v_state NOT IN ('split','unresolved','withdrawn') AND NOT EXISTS (
      SELECT 1 FROM core.legacy_identity_resolution r
      WHERE r.legacy_identity_resolution_id = v_resolution_id
        AND r.target_folder_id IS NOT NULL))
    OR (v_kind = 'trace_edge'
      AND v_state NOT IN ('split','unresolved','withdrawn')
      AND NOT EXISTS (
        SELECT 1 FROM core.legacy_identity_resolution r
        WHERE r.legacy_identity_resolution_id = v_resolution_id
          AND r.target_trace_edge_release_id IS NOT NULL
          AND r.effective_release_id = r.target_trace_edge_release_id
      )) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'LEGACY_IDENTITY_TYPED_TARGET_MISMATCH';
  END IF;

  IF EXISTS (
    SELECT 1 FROM core.legacy_identity_resolution r
    JOIN core.legacy_identity_resolution p
      ON p.legacy_identity_resolution_id = r.supersedes_resolution_id
    WHERE r.legacy_identity_resolution_id = v_resolution_id
      AND (r.legacy_identity_id IS DISTINCT FROM p.legacy_identity_id
        OR r.effective_from <= p.effective_from)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'LEGACY_IDENTITY_RESOLUTION_SUPERSESSION_MISMATCH';
  END IF;

  SELECT count(*) INTO v_current_count
  FROM core.legacy_identity_resolution r
  WHERE r.legacy_identity_id = v_identity_id
    AND NOT EXISTS (
      SELECT 1 FROM core.legacy_identity_resolution n
      WHERE n.supersedes_resolution_id = r.legacy_identity_resolution_id
    );
  IF v_current_count <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'LEGACY_IDENTITY_REQUIRES_ONE_CURRENT_RESOLUTION';
  END IF;

  SELECT count(*) INTO v_split_count
  FROM core.legacy_identity_split_successor s
  WHERE s.legacy_identity_resolution_id = v_resolution_id;
  IF (v_state = 'split' AND v_split_count < 2)
    OR (v_state <> 'split' AND v_split_count <> 0) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'LEGACY_IDENTITY_SPLIT_ARITY_MISMATCH';
  END IF;
  IF v_state NOT IN ('unresolved','withdrawn')
    AND EXISTS (
      SELECT 1 FROM core.legacy_identity_resolution r
      WHERE r.legacy_identity_resolution_id = v_resolution_id
        AND (r.decision_evidence_item_id IS NULL OR r.effective_release_id IS NULL)
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'LEGACY_IDENTITY_RESOLUTION_REQUIRES_EVIDENCE_AND_RELEASE';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: assignment_assertion_matches(uuid, uuid); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.assignment_assertion_matches(p_assignment_id uuid, p_assertion_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_kind provenance.assignment_kind; v_match boolean := false;
BEGIN
  SELECT assignment_kind INTO v_kind FROM provenance.canonical_assignment
  WHERE canonical_assignment_id=p_assignment_id;
  IF NOT EXISTS (
    SELECT 1 FROM provenance.assertion a
    JOIN provenance.assignment_predicate_compatibility c
      ON c.assertion_predicate_id=a.assertion_predicate_id
      AND c.assignment_kind=v_kind
    WHERE a.assertion_id=p_assertion_id AND a.status='accepted'
  ) THEN RETURN false; END IF;
  CASE v_kind
    WHEN 'entity_name' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_entity_name x
      JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.entity_id
      JOIN provenance.assertion_value_literal v ON v.assertion_id=p_assertion_id AND v.field_literal_id=x.field_literal_id
      WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_source_record' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_source_record x
      JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id
      JOIN provenance.assertion_value_source_record v ON v.assertion_id=p_assertion_id AND v.source_record_id=x.source_record_id
      WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_agent_credit' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_agent_credit x
      JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id
      JOIN provenance.assertion_value_entity v ON v.assertion_id=p_assertion_id AND v.entity_id=x.agent_id
      WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_medium' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_medium x JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id JOIN provenance.assertion_value_entity v ON v.assertion_id=p_assertion_id AND v.entity_id=x.medium_concept_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_type' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_type x JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id JOIN provenance.assertion_value_entity v ON v.assertion_id=p_assertion_id AND v.entity_id=x.type_concept_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_subject' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_subject x JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id JOIN provenance.assertion_value_entity v ON v.assertion_id=p_assertion_id AND v.entity_id=x.subject_concept_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_collection' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_collection x JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id JOIN provenance.assertion_value_entity v ON v.assertion_id=p_assertion_id AND v.entity_id=x.collection_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_temporal' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_temporal x JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id JOIN provenance.assertion_value_entity v ON v.assertion_id=p_assertion_id AND v.entity_id=x.temporal_extent_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_place' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_place x JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id JOIN provenance.assertion_value_entity v ON v.assertion_id=p_assertion_id AND v.entity_id=x.place_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'folder_membership' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_folder_membership x JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id JOIN provenance.assertion_value_folder v ON v.assertion_id=p_assertion_id AND v.folder_id=x.folder_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_tree_membership' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_tree_membership x JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id JOIN provenance.assertion_value_trace_node v ON v.assertion_id=p_assertion_id AND v.trace_node_id=x.trace_node_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'object_representation' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_object_representation x JOIN provenance.assertion_subject_entity s ON s.assertion_id=p_assertion_id AND s.entity_id=x.archive_object_id JOIN provenance.assertion_value_representation v ON v.assertion_id=p_assertion_id AND v.digital_representation_id=x.digital_representation_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
    WHEN 'identity_resolution' THEN SELECT EXISTS (
      SELECT 1 FROM provenance.assignment_identity_resolution x JOIN provenance.assertion_value_identity_resolution v ON v.assertion_id=p_assertion_id AND v.legacy_identity_resolution_id=x.legacy_identity_resolution_id WHERE x.canonical_assignment_id=p_assignment_id) INTO v_match;
  END CASE;
  RETURN COALESCE(v_match,false);
END
$$;


--
-- Name: enforce_accepted_assertion(); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.enforce_accepted_assertion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := COALESCE(to_jsonb(NEW), to_jsonb(OLD));
  v_id uuid := (v_row ->> 'assertion_id')::uuid;
BEGIN
  IF v_id IS NULL AND v_row ? 'assertion_review_decision_id' THEN
    SELECT d.assertion_id INTO v_id
    FROM provenance.assertion_review_decision d
    WHERE d.assertion_review_decision_id =
      (v_row ->> 'assertion_review_decision_id')::uuid;
  END IF;
  IF EXISTS (
    SELECT 1 FROM provenance.assertion a
    JOIN provenance.assertion_predicate p
      ON p.assertion_predicate_id=a.assertion_predicate_id
    JOIN provenance.predicate_evidence_profile ep
      ON ep.predicate_evidence_profile_id=p.predicate_evidence_profile_id
    WHERE a.assertion_id=v_id AND a.status='accepted'
      AND (NOT p.active OR p.subject_domain<>a.subject_kind
        OR p.value_range<>a.value_kind
        OR (ep.requires_supporting_evidence AND (
          SELECT count(*) FROM provenance.assertion_evidence ae
          WHERE ae.assertion_id=a.assertion_id
            AND ae.evidence_role='supports') < ep.minimum_support_count
        OR (ep.requires_review_decision AND NOT EXISTS (
          SELECT 1 FROM provenance.assertion_review_decision d
          WHERE d.assertion_id=a.assertion_id AND d.outcome='accept'
            AND NOT EXISTS (SELECT 1 FROM provenance.assertion_review_decision n
              WHERE n.supersedes_decision_id=d.assertion_review_decision_id)
            AND EXISTS (SELECT 1 FROM provenance.assertion_decision_evidence de
              WHERE de.assertion_review_decision_id=d.assertion_review_decision_id
                AND de.evidence_role='supports')))))
  ) THEN
    RAISE EXCEPTION USING ERRCODE='23514',
      MESSAGE='ACCEPTED_ASSERTION_PREDICATE_DOMAIN_RANGE_OR_EVIDENCE_VIOLATION';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_assertion_shape(); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.enforce_assertion_shape() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_id uuid := COALESCE(NEW.assertion_id, OLD.assertion_id);
  v_subject_kind provenance.assertion_subject_kind;
  v_value_kind provenance.assertion_value_kind;
  v_subject_count integer;
  v_value_count integer;
BEGIN
  SELECT a.subject_kind, a.value_kind INTO v_subject_kind, v_value_kind
  FROM provenance.assertion a WHERE a.assertion_id = v_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT
    (SELECT count(*) FROM provenance.assertion_subject_entity x WHERE x.assertion_id=v_id)
    + (SELECT count(*) FROM provenance.assertion_subject_source_record x WHERE x.assertion_id=v_id)
    + (SELECT count(*) FROM provenance.assertion_subject_trace_node x WHERE x.assertion_id=v_id)
    + (SELECT count(*) FROM provenance.assertion_subject_representation x WHERE x.assertion_id=v_id),
    (SELECT count(*) FROM provenance.assertion_value_literal x WHERE x.assertion_id=v_id)
    + (SELECT count(*) FROM provenance.assertion_value_entity x WHERE x.assertion_id=v_id)
    + (SELECT count(*) FROM provenance.assertion_value_source_record x WHERE x.assertion_id=v_id)
    + (SELECT count(*) FROM provenance.assertion_value_trace_node x WHERE x.assertion_id=v_id)
    + (SELECT count(*) FROM provenance.assertion_value_folder x WHERE x.assertion_id=v_id)
    + (SELECT count(*) FROM provenance.assertion_value_representation x WHERE x.assertion_id=v_id)
    + (SELECT count(*) FROM provenance.assertion_value_identity_resolution x WHERE x.assertion_id=v_id)
  INTO v_subject_count, v_value_count;
  IF v_subject_count <> 1 OR NOT (CASE v_subject_kind
    WHEN 'entity' THEN EXISTS (SELECT 1 FROM provenance.assertion_subject_entity x WHERE x.assertion_id=v_id)
    WHEN 'source_record' THEN EXISTS (SELECT 1 FROM provenance.assertion_subject_source_record x WHERE x.assertion_id=v_id)
    WHEN 'trace_node' THEN EXISTS (SELECT 1 FROM provenance.assertion_subject_trace_node x WHERE x.assertion_id=v_id)
    WHEN 'digital_representation' THEN EXISTS (SELECT 1 FROM provenance.assertion_subject_representation x WHERE x.assertion_id=v_id)
    ELSE false END) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='ASSERTION_SUBJECT_EXACTLY_ONE_VIOLATION';
  END IF;
  IF v_value_count <> 1 OR NOT (CASE v_value_kind
    WHEN 'literal' THEN EXISTS (SELECT 1 FROM provenance.assertion_value_literal x WHERE x.assertion_id=v_id)
    WHEN 'entity' THEN EXISTS (SELECT 1 FROM provenance.assertion_value_entity x WHERE x.assertion_id=v_id)
    WHEN 'source_record' THEN EXISTS (SELECT 1 FROM provenance.assertion_value_source_record x WHERE x.assertion_id=v_id)
    WHEN 'trace_node' THEN EXISTS (SELECT 1 FROM provenance.assertion_value_trace_node x WHERE x.assertion_id=v_id)
    WHEN 'folder' THEN EXISTS (SELECT 1 FROM provenance.assertion_value_folder x WHERE x.assertion_id=v_id)
    WHEN 'digital_representation' THEN EXISTS (SELECT 1 FROM provenance.assertion_value_representation x WHERE x.assertion_id=v_id)
    WHEN 'legacy_identity_resolution' THEN EXISTS (SELECT 1 FROM provenance.assertion_value_identity_resolution x WHERE x.assertion_id=v_id)
    ELSE false END) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='ASSERTION_VALUE_EXACTLY_ONE_VIOLATION';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_assignment_shape_and_support(); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.enforce_assignment_shape_and_support() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := COALESCE(to_jsonb(NEW), to_jsonb(OLD));
  v_id uuid := (v_row ->> 'canonical_assignment_id')::uuid;
BEGIN
  IF v_id IS NULL AND v_row ? 'assignment_review_decision_id' THEN
    SELECT d.canonical_assignment_id INTO v_id
    FROM provenance.assignment_review_decision d
    WHERE d.assignment_review_decision_id =
      (v_row ->> 'assignment_review_decision_id')::uuid;
  END IF;
  PERFORM provenance.validate_one_assignment(v_id);
  RETURN NULL;
END
$$;


--
-- Name: enforce_assignments_for_assertion(); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.enforce_assignments_for_assertion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT DISTINCT aa.canonical_assignment_id
    FROM provenance.assignment_assertion aa
    WHERE aa.assertion_id IN (NEW.assertion_id, OLD.assertion_id)
  LOOP
    PERFORM provenance.validate_one_assignment(r.canonical_assignment_id);
  END LOOP;
  RETURN NULL;
END
$$;


--
-- Name: enforce_one_current_review_decision(); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.enforce_one_current_review_decision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := to_jsonb(NEW);
  v_parent_id uuid;
  v_current_count integer;
BEGIN
  IF TG_TABLE_NAME = 'assertion_review_decision' THEN
    v_parent_id := (v_row ->> 'assertion_id')::uuid;
    SELECT count(*) INTO v_current_count
    FROM provenance.assertion_review_decision d
    WHERE d.assertion_id = v_parent_id
      AND NOT EXISTS (
        SELECT 1 FROM provenance.assertion_review_decision newer
        WHERE newer.supersedes_decision_id = d.assertion_review_decision_id);
    IF v_row ->> 'supersedes_decision_id' IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM provenance.assertion_review_decision prior
      WHERE prior.assertion_review_decision_id =
          (v_row ->> 'supersedes_decision_id')::uuid
        AND prior.assertion_id = v_parent_id
        AND (
          prior.decided_at < (v_row ->> 'decided_at')::timestamptz
          OR (prior.decided_at = (v_row ->> 'decided_at')::timestamptz
            AND prior.assertion_review_decision_id <
              (v_row ->> 'assertion_review_decision_id')::uuid)
        )
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'ASSERTION_DECISION_SUPERSESSION_ORDER_MISMATCH';
    END IF;
  ELSE
    v_parent_id := (v_row ->> 'canonical_assignment_id')::uuid;
    SELECT count(*) INTO v_current_count
    FROM provenance.assignment_review_decision d
    WHERE d.canonical_assignment_id = v_parent_id
      AND NOT EXISTS (
        SELECT 1 FROM provenance.assignment_review_decision newer
        WHERE newer.supersedes_decision_id = d.assignment_review_decision_id);
    IF v_row ->> 'supersedes_decision_id' IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM provenance.assignment_review_decision prior
      WHERE prior.assignment_review_decision_id =
          (v_row ->> 'supersedes_decision_id')::uuid
        AND prior.canonical_assignment_id = v_parent_id
        AND (
          prior.decided_at < (v_row ->> 'decided_at')::timestamptz
          OR (prior.decided_at = (v_row ->> 'decided_at')::timestamptz
            AND prior.assignment_review_decision_id <
              (v_row ->> 'assignment_review_decision_id')::uuid)
        )
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'ASSIGNMENT_DECISION_SUPERSESSION_ORDER_MISMATCH';
    END IF;
  END IF;
  IF v_current_count <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'PROVENANCE_REVIEW_REQUIRES_ONE_CURRENT_DECISION';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_predicate_registry_fanout(); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.enforce_predicate_registry_fanout() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r record;
BEGIN
  FOR r IN SELECT assertion_id FROM provenance.assertion
    WHERE assertion_predicate_id=NEW.assertion_predicate_id
  LOOP
    IF EXISTS (SELECT 1 FROM provenance.assertion a
      WHERE a.assertion_id=r.assertion_id AND a.status='accepted'
      AND (NOT NEW.active OR NEW.subject_domain<>a.subject_kind
          OR NEW.value_range<>a.value_kind
          OR OLD.registry_version IS DISTINCT FROM NEW.registry_version
          OR OLD.predicate_evidence_profile_id IS DISTINCT FROM
            NEW.predicate_evidence_profile_id)) THEN
      RAISE EXCEPTION USING ERRCODE='23514',
        MESSAGE='PREDICATE_REGISTRY_CHANGE_INVALIDATES_ACCEPTED_ASSERTION';
    END IF;
  END LOOP;
  RETURN NULL;
END
$$;


--
-- Name: enforce_provenance_supersession_parent(); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.enforce_provenance_supersession_parent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := pg_catalog.to_jsonb(NEW);
BEGIN
  IF TG_TABLE_NAME = 'source_version'
    AND v_row->>'supersedes_source_version_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM provenance.source_version prior
      WHERE prior.source_version_id = (v_row->>'supersedes_source_version_id')::uuid
        AND prior.source_document_id = (v_row->>'source_document_id')::uuid
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'SOURCE_VERSION_SUPERSESSION_PARENT_MISMATCH';
  ELSIF TG_TABLE_NAME = 'evidence_item'
    AND v_row->>'supersedes_evidence_item_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM provenance.evidence_item prior
      JOIN provenance.source_version oldv ON oldv.source_version_id = prior.source_version_id
      JOIN provenance.source_version newv ON newv.source_version_id = (v_row->>'source_version_id')::uuid
      WHERE prior.evidence_item_id = (v_row->>'supersedes_evidence_item_id')::uuid
        AND oldv.source_document_id = newv.source_document_id
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'EVIDENCE_SUPERSESSION_SOURCE_MISMATCH';
  ELSIF TG_TABLE_NAME = 'assertion'
    AND v_row->>'supersedes_assertion_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM provenance.assertion prior
      WHERE prior.assertion_id = (v_row->>'supersedes_assertion_id')::uuid
        AND prior.assertion_predicate_id = (v_row->>'assertion_predicate_id')::uuid
        AND prior.subject_kind::text = v_row->>'subject_kind'
        AND prior.value_kind::text = v_row->>'value_kind'
        AND prior.status = 'superseded'
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ASSERTION_SUPERSESSION_IDENTITY_MISMATCH';
  ELSIF TG_TABLE_NAME = 'canonical_assignment'
    AND v_row->>'supersedes_assignment_id' IS NOT NULL
    AND (v_row->>'canonical_assignment_id')::uuid =
      (v_row->>'supersedes_assignment_id')::uuid THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ASSIGNMENT_SUPERSESSION_CYCLE';
  ELSIF TG_TABLE_NAME = 'canonical_assignment'
    AND v_row->>'supersedes_assignment_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM provenance.canonical_assignment prior
      WHERE prior.canonical_assignment_id = (v_row->>'supersedes_assignment_id')::uuid
        AND prior.assignment_kind::text = v_row->>'assignment_kind'
        AND prior.status = 'superseded'
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ASSIGNMENT_SUPERSESSION_KIND_MISMATCH';
  ELSIF TG_TABLE_NAME = 'canonical_assignment'
    AND v_row->>'supersedes_assignment_id' IS NOT NULL
    AND v_row->>'assignment_kind' = 'folder_membership'
    AND NOT EXISTS (
      SELECT 1
      FROM provenance.assignment_folder_membership prior_membership
      JOIN provenance.assignment_folder_membership new_membership
        ON new_membership.canonical_assignment_id =
          (v_row->>'canonical_assignment_id')::uuid
      WHERE prior_membership.canonical_assignment_id =
          (v_row->>'supersedes_assignment_id')::uuid
        AND prior_membership.archive_object_id = new_membership.archive_object_id
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ASSIGNMENT_SUPERSESSION_OBJECT_MISMATCH';
  ELSIF TG_TABLE_NAME = 'assignment_review_decision'
    AND v_row->>'supersedes_decision_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM provenance.assignment_review_decision prior
      WHERE prior.assignment_review_decision_id = (v_row->>'supersedes_decision_id')::uuid
        AND prior.canonical_assignment_id = (v_row->>'canonical_assignment_id')::uuid
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ASSIGNMENT_DECISION_SUPERSESSION_PARENT_MISMATCH';
  ELSIF TG_TABLE_NAME = 'assertion_review_decision'
    AND v_row->>'supersedes_decision_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM provenance.assertion_review_decision prior
      WHERE prior.assertion_review_decision_id = (v_row->>'supersedes_decision_id')::uuid
        AND prior.assertion_id = (v_row->>'assertion_id')::uuid
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ASSERTION_DECISION_SUPERSESSION_PARENT_MISMATCH';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: record_assertion_review_decision(uuid, uuid, workflow.review_outcome, text, uuid, uuid[], provenance.evidence_role[]); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.record_assertion_review_decision(p_decision_id uuid, p_assertion_id uuid, p_outcome workflow.review_outcome, p_rationale text, p_supersedes_decision_id uuid, p_evidence_item_ids uuid[], p_evidence_roles provenance.evidence_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_index integer;
BEGIN
  PERFORM rights.require_reviewer();
  IF COALESCE(cardinality(p_evidence_item_ids), 0) = 0
    OR cardinality(p_evidence_item_ids) IS DISTINCT FROM cardinality(p_evidence_roles) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'ASSERTION_REVIEW_EVIDENCE_SET_INVALID';
  END IF;
  IF p_supersedes_decision_id IS NULL THEN
    PERFORM 1
    FROM workflow.review_case c
    JOIN workflow.review_case_assertion x USING (review_case_id)
    WHERE x.assertion_id = p_assertion_id
      AND c.queue_state IN ('claimed', 'in_review')
      AND c.claimed_by = session_user::text
    FOR UPDATE OF c;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'ASSERTION_REVIEW_CASE_NOT_CLAIMED';
    END IF;
  ELSIF NOT EXISTS (
    SELECT 1 FROM provenance.assertion_review_decision prior
    WHERE prior.assertion_review_decision_id = p_supersedes_decision_id
      AND prior.assertion_id = p_assertion_id
      AND NOT EXISTS (
        SELECT 1 FROM provenance.assertion_review_decision newer
        WHERE newer.supersedes_decision_id = prior.assertion_review_decision_id)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '55000',
      MESSAGE = 'ASSERTION_REVIEW_SUPERSEDES_NONCURRENT_DECISION';
  END IF;
  INSERT INTO provenance.assertion_review_decision VALUES (
    p_decision_id, p_assertion_id, p_outcome, session_user::text,
    p_rationale, p_supersedes_decision_id, clock_timestamp());
  FOR v_index IN 1..cardinality(p_evidence_item_ids) LOOP
    INSERT INTO provenance.assertion_decision_evidence VALUES (
      p_decision_id, p_evidence_item_ids[v_index], p_evidence_roles[v_index]);
  END LOOP;
  UPDATE provenance.assertion
  SET status = CASE p_outcome
      WHEN 'accept' THEN 'accepted'::provenance.assertion_status
      WHEN 'reject' THEN 'rejected'::provenance.assertion_status
      WHEN 'supersede' THEN 'superseded'::provenance.assertion_status
      ELSE 'proposed'::provenance.assertion_status END
  WHERE assertion_id = p_assertion_id
    AND ((p_supersedes_decision_id IS NULL AND status = 'proposed')
      OR (p_supersedes_decision_id IS NOT NULL AND status <> 'superseded'));
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'ASSERTION_NOT_REVIEWABLE';
  END IF;
  UPDATE workflow.review_case c
  SET queue_state = 'resolved', claimed_by = NULL, claimed_at = NULL,
    resolved_at = clock_timestamp()
  FROM workflow.review_case_assertion x
  WHERE x.review_case_id = c.review_case_id
    AND x.assertion_id = p_assertion_id;
  PERFORM audit.record_decision_event('assertion_review', p_decision_id);
END
$$;


--
-- Name: record_assignment_review_decision(uuid, uuid, workflow.review_outcome, text, uuid, uuid[], provenance.evidence_role[]); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.record_assignment_review_decision(p_decision_id uuid, p_assignment_id uuid, p_outcome workflow.review_outcome, p_rationale text, p_supersedes_decision_id uuid, p_evidence_item_ids uuid[], p_evidence_roles provenance.evidence_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_index integer;
BEGIN
  PERFORM rights.require_reviewer();
  IF COALESCE(cardinality(p_evidence_item_ids), 0) = 0
    OR cardinality(p_evidence_item_ids) IS DISTINCT FROM cardinality(p_evidence_roles) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'ASSIGNMENT_REVIEW_EVIDENCE_SET_INVALID';
  END IF;
  IF p_supersedes_decision_id IS NULL THEN
    PERFORM 1
    FROM workflow.review_case c
    JOIN workflow.review_case_assignment x USING (review_case_id)
    WHERE x.canonical_assignment_id = p_assignment_id
      AND c.queue_state IN ('claimed', 'in_review')
      AND c.claimed_by = session_user::text
    FOR UPDATE OF c;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'ASSIGNMENT_REVIEW_CASE_NOT_CLAIMED';
    END IF;
  ELSIF NOT EXISTS (
    SELECT 1 FROM provenance.assignment_review_decision prior
    WHERE prior.assignment_review_decision_id = p_supersedes_decision_id
      AND prior.canonical_assignment_id = p_assignment_id
      AND NOT EXISTS (
        SELECT 1 FROM provenance.assignment_review_decision newer
        WHERE newer.supersedes_decision_id = prior.assignment_review_decision_id)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '55000',
      MESSAGE = 'ASSIGNMENT_REVIEW_SUPERSEDES_NONCURRENT_DECISION';
  END IF;
  INSERT INTO provenance.assignment_review_decision VALUES (
    p_decision_id, p_assignment_id, p_outcome, session_user::text,
    p_rationale, p_supersedes_decision_id, clock_timestamp());
  FOR v_index IN 1..cardinality(p_evidence_item_ids) LOOP
    INSERT INTO provenance.assignment_decision_evidence VALUES (
      p_decision_id, p_evidence_item_ids[v_index], p_evidence_roles[v_index]);
  END LOOP;
  UPDATE provenance.canonical_assignment
  SET status = CASE p_outcome
      WHEN 'accept' THEN 'accepted'::provenance.assertion_status
      WHEN 'reject' THEN 'rejected'::provenance.assertion_status
      WHEN 'supersede' THEN 'superseded'::provenance.assertion_status
      ELSE 'proposed'::provenance.assertion_status END
  WHERE canonical_assignment_id = p_assignment_id
    AND ((p_supersedes_decision_id IS NULL AND status = 'proposed')
      OR (p_supersedes_decision_id IS NOT NULL AND status <> 'superseded'));
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'ASSIGNMENT_NOT_REVIEWABLE';
  END IF;
  UPDATE workflow.review_case c
  SET queue_state = 'resolved', claimed_by = NULL, claimed_at = NULL,
    resolved_at = clock_timestamp()
  FROM workflow.review_case_assignment x
  WHERE x.review_case_id = c.review_case_id
    AND x.canonical_assignment_id = p_assignment_id;
  PERFORM audit.record_decision_event('assignment_review', p_decision_id);
END
$$;


--
-- Name: record_proposed_entity_name_assignment(uuid, uuid, uuid, uuid[], provenance.evidence_role[], uuid, text); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.record_proposed_entity_name_assignment(p_assignment_id uuid, p_entity_id uuid, p_field_literal_id uuid, p_assertion_ids uuid[], p_support_roles provenance.evidence_role[], p_review_case_id uuid, p_reason_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_index integer;
BEGIN
  PERFORM raw.require_ingest_writer();
  IF cardinality(p_assertion_ids) IS DISTINCT FROM cardinality(p_support_roles) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'PROPOSED_ASSIGNMENT_ASSERTION_SET_INVALID';
  END IF;
  INSERT INTO provenance.canonical_assignment VALUES (
    p_assignment_id, 'entity_name', 'proposed', NULL, clock_timestamp());
  INSERT INTO provenance.assignment_entity_name VALUES (
    p_assignment_id, p_entity_id, p_field_literal_id);
  IF COALESCE(cardinality(p_assertion_ids), 0) > 0 THEN
    FOR v_index IN 1..cardinality(p_assertion_ids) LOOP
      INSERT INTO provenance.assignment_assertion VALUES (
        p_assignment_id, p_assertion_ids[v_index], p_support_roles[v_index]);
    END LOOP;
  END IF;
  INSERT INTO workflow.review_case (
    review_case_id, case_kind, queue_state, priority, reason_code,
    claimed_by, claimed_at, created_at, resolved_at
  ) VALUES (
    p_review_case_id, 'canonical_assignment', 'queued', 0,
    p_reason_code, NULL, NULL, clock_timestamp(), NULL);
  INSERT INTO workflow.review_case_assignment VALUES (
    p_review_case_id, p_assignment_id);
END
$$;


--
-- Name: record_proposed_literal_assertion(uuid, uuid, uuid, uuid, text, text, text, uuid, text, uuid[], provenance.evidence_role[], uuid, text); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.record_proposed_literal_assertion(p_assertion_id uuid, p_predicate_id uuid, p_subject_entity_id uuid, p_field_literal_id uuid, p_normalized_text text, p_language_tag text, p_datatype_uri text, p_claimant_agent_id uuid, p_source_wording text, p_evidence_item_ids uuid[], p_evidence_roles provenance.evidence_role[], p_review_case_id uuid, p_reason_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_index integer;
BEGIN
  PERFORM raw.require_ingest_writer();
  IF cardinality(p_evidence_item_ids) IS DISTINCT FROM cardinality(p_evidence_roles) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'PROPOSED_ASSERTION_EVIDENCE_SET_INVALID';
  END IF;
  INSERT INTO provenance.assertion (
    assertion_id, assertion_predicate_id, subject_kind, value_kind,
    status, claimant_agent_id, source_wording, supersedes_assertion_id,
    created_at
  ) VALUES (
    p_assertion_id, p_predicate_id, 'entity', 'literal', 'proposed',
    p_claimant_agent_id, p_source_wording, NULL, clock_timestamp());
  INSERT INTO provenance.assertion_subject_entity VALUES (
    p_assertion_id, p_subject_entity_id);
  INSERT INTO provenance.assertion_value_literal VALUES (
    p_assertion_id, p_field_literal_id, p_normalized_text,
    p_language_tag, p_datatype_uri);
  IF COALESCE(cardinality(p_evidence_item_ids), 0) > 0 THEN
    FOR v_index IN 1..cardinality(p_evidence_item_ids) LOOP
      INSERT INTO provenance.assertion_evidence VALUES (
        p_assertion_id, p_evidence_item_ids[v_index], p_evidence_roles[v_index]);
    END LOOP;
  END IF;
  INSERT INTO workflow.review_case (
    review_case_id, case_kind, queue_state, priority, reason_code,
    claimed_by, claimed_at, created_at, resolved_at
  ) VALUES (
    p_review_case_id, 'assertion', 'queued', 0, p_reason_code,
    NULL, NULL, clock_timestamp(), NULL);
  INSERT INTO workflow.review_case_assertion VALUES (
    p_review_case_id, p_assertion_id);
END
$$;


--
-- Name: validate_one_assignment(uuid); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.validate_one_assignment(p_assignment_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_status provenance.assertion_status;
BEGIN
  PERFORM provenance.validate_one_assignment_shape_v1(p_assignment_id);
  SELECT status INTO v_status FROM provenance.canonical_assignment
  WHERE canonical_assignment_id=p_assignment_id;
  IF v_status='accepted'
    AND NOT EXISTS (
      SELECT 1 FROM provenance.assignment_assertion aa
      WHERE aa.canonical_assignment_id=p_assignment_id
        AND aa.support_role='supports'
        AND provenance.assignment_assertion_matches(
          p_assignment_id, aa.assertion_id))
    AND NOT EXISTS (
      SELECT 1 FROM provenance.assignment_review_decision d
      WHERE d.canonical_assignment_id=p_assignment_id AND d.outcome='accept'
        AND NOT EXISTS (SELECT 1 FROM provenance.assignment_review_decision n
          WHERE n.supersedes_decision_id=d.assignment_review_decision_id)
        AND EXISTS (SELECT 1 FROM provenance.assignment_decision_evidence e
          WHERE e.assignment_review_decision_id=d.assignment_review_decision_id
            AND e.evidence_role='supports')) THEN
    RAISE EXCEPTION USING ERRCODE='23514',
      MESSAGE='ACCEPTED_ASSIGNMENT_SUPPORT_NOT_TARGET_COMPATIBLE';
  END IF;
END
$$;


--
-- Name: validate_one_assignment_shape_v1(uuid); Type: FUNCTION; Schema: provenance; Owner: -
--

CREATE FUNCTION provenance.validate_one_assignment_shape_v1(p_assignment_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_kind provenance.assignment_kind;
  v_status provenance.assertion_status;
  v_count integer;
BEGIN
  SELECT a.assignment_kind, a.status INTO v_kind, v_status
  FROM provenance.canonical_assignment a
  WHERE a.canonical_assignment_id = p_assignment_id;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT
      (SELECT count(*) FROM provenance.assignment_entity_name x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_source_record x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_agent_credit x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_medium x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_type x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_subject x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_collection x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_temporal x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_place x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_folder_membership x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_tree_membership x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_object_representation x WHERE x.canonical_assignment_id = p_assignment_id)
    + (SELECT count(*) FROM provenance.assignment_identity_resolution x WHERE x.canonical_assignment_id = p_assignment_id)
  INTO v_count;

  IF v_count <> 1 OR NOT (CASE v_kind
    WHEN 'entity_name' THEN EXISTS (SELECT 1 FROM provenance.assignment_entity_name x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_source_record' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_source_record x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_agent_credit' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_agent_credit x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_medium' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_medium x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_type' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_type x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_subject' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_subject x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_collection' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_collection x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_temporal' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_temporal x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_place' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_place x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'folder_membership' THEN EXISTS (SELECT 1 FROM provenance.assignment_folder_membership x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_tree_membership' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_tree_membership x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'object_representation' THEN EXISTS (SELECT 1 FROM provenance.assignment_object_representation x WHERE x.canonical_assignment_id = p_assignment_id)
    WHEN 'identity_resolution' THEN EXISTS (SELECT 1 FROM provenance.assignment_identity_resolution x WHERE x.canonical_assignment_id = p_assignment_id)
    ELSE false
  END) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'CANONICAL_ASSIGNMENT_EXACTLY_ONE_TYPED_SUBTYPE_VIOLATION';
  END IF;

  IF v_status = 'accepted' AND NOT (
    EXISTS (
      SELECT 1
      FROM provenance.assignment_assertion aa
      JOIN provenance.assertion a ON a.assertion_id = aa.assertion_id
      WHERE aa.canonical_assignment_id = p_assignment_id
        AND aa.support_role = 'supports' AND a.status = 'accepted'
    ) OR EXISTS (
      SELECT 1
      FROM provenance.assignment_review_decision d
      WHERE d.canonical_assignment_id = p_assignment_id
        AND d.outcome = 'accept'
        AND NOT EXISTS (
          SELECT 1 FROM provenance.assignment_review_decision newer
          WHERE newer.supersedes_decision_id = d.assignment_review_decision_id
        )
        AND EXISTS (
          SELECT 1 FROM provenance.assignment_decision_evidence de
          WHERE de.assignment_review_decision_id = d.assignment_review_decision_id
            AND de.evidence_role = 'supports'
        )
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'ACCEPTED_ASSIGNMENT_REQUIRES_ACCEPTED_ASSERTION_OR_EVIDENCE_BOUND_DECISION';
  END IF;
END
$$;


--
-- Name: enforce_archive_object_surface_reciprocal(); Type: FUNCTION; Schema: raw; Owner: -
--

CREATE FUNCTION raw.enforce_archive_object_surface_reciprocal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_id uuid := COALESCE(NEW.archive_object_id, OLD.archive_object_id);
BEGIN
  IF EXISTS (
    SELECT 1 FROM core.archive_object o
    LEFT JOIN raw.legacy_surface_ledger l
      ON l.legacy_surface_ledger_id = o.created_from_surface_ledger_id
    WHERE o.archive_object_id = v_id
      AND o.created_from_surface_ledger_id IS NOT NULL
      AND (l.archive_object_id IS DISTINCT FROM o.archive_object_id
        OR l.import_disposition = 'candidate')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'ARCHIVE_OBJECT_SURFACE_LEDGER_RECIPROCAL_MISMATCH';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_legacy_surface_lineage(); Type: FUNCTION; Schema: raw; Owner: -
--

CREATE FUNCTION raw.enforce_legacy_surface_lineage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_id uuid := COALESCE(NEW.legacy_surface_ledger_id, OLD.legacy_surface_ledger_id);
BEGIN
  IF EXISTS (
    SELECT 1
    FROM raw.legacy_surface_ledger l
    JOIN raw.migration_batch b ON b.migration_batch_id = l.migration_batch_id
    JOIN raw.source_record r ON r.source_record_id = l.source_record_id
    WHERE l.legacy_surface_ledger_id = v_id
      AND (
        l.canonical_input_asset_id IS DISTINCT FROM b.canonical_input_asset_id
        OR r.source_asset_id IS DISTINCT FROM b.canonical_input_asset_id
        OR l.source_fingerprint IS DISTINCT FROM r.raw_fingerprint
        OR (l.import_disposition <> 'candidate' AND NOT EXISTS (
          SELECT 1 FROM core.archive_object o
          WHERE o.archive_object_id = l.archive_object_id
            AND o.created_from_surface_ledger_id = l.legacy_surface_ledger_id
        ))
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'LEGACY_SURFACE_LINEAGE_OR_RECIPROCAL_OBJECT_MISMATCH';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_migration_batch_authority(); Type: FUNCTION; Schema: raw; Owner: -
--

CREATE FUNCTION raw.enforce_migration_batch_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM raw.source_asset a
    WHERE a.source_asset_id = NEW.canonical_input_asset_id
      AND a.authority = 'canonical_migration_input'
      AND a.sha256 = NEW.input_sha256
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'MIGRATION_BATCH_REQUIRES_EXACT_CANONICAL_INPUT_ASSET';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: register_field_literal(uuid, uuid, text, integer, text, bytea, bigint, bigint); Type: FUNCTION; Schema: raw; Owner: -
--

CREATE FUNCTION raw.register_field_literal(p_field_literal_id uuid, p_source_record_id uuid, p_json_pointer text, p_occurrence_ordinal integer, p_raw_text text, p_raw_bytes bytea, p_byte_start bigint, p_byte_end bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM raw.require_ingest_writer();
  PERFORM 1
  FROM raw.source_record r
  JOIN raw.source_asset a ON a.source_asset_id = r.source_asset_id
  WHERE r.source_record_id = p_source_record_id
    AND a.authority = 'governed_source'
  FOR SHARE OF r, a;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'RUNTIME_FIELD_LITERAL_REQUIRES_GOVERNED_SOURCE_PARENT';
  END IF;
  INSERT INTO raw.field_literal VALUES (
    p_field_literal_id, p_source_record_id, p_json_pointer,
    p_occurrence_ordinal, p_raw_text, p_raw_bytes,
    p_byte_start, p_byte_end);
END
$$;


--
-- Name: register_source_asset(uuid, raw.asset_authority, text, core.sha256_hex, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: raw; Owner: -
--

CREATE FUNCTION raw.register_source_asset(p_source_asset_id uuid, p_authority raw.asset_authority, p_logical_name text, p_sha256 core.sha256_hex, p_raw_bytes bytea, p_media_type text, p_received_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM raw.require_ingest_writer();
  IF p_authority <> 'governed_source' THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'RUNTIME_INGESTOR_CANNOT_DECLARE_FROZEN_ASSET_AUTHORITY';
  END IF;
  INSERT INTO raw.source_asset (
    source_asset_id, authority, logical_name, sha256, byte_length,
    raw_bytes, media_type, received_at
  ) VALUES (
    p_source_asset_id, p_authority, p_logical_name, p_sha256,
    octet_length(p_raw_bytes), p_raw_bytes, p_media_type, p_received_at
  );
END
$$;


--
-- Name: register_source_record(uuid, uuid, bigint, text, bytea, core.sha256_hex, jsonb, text); Type: FUNCTION; Schema: raw; Owner: -
--

CREATE FUNCTION raw.register_source_record(p_source_record_id uuid, p_source_asset_id uuid, p_record_ordinal bigint, p_legacy_source_record_id text, p_raw_value bytea, p_raw_fingerprint core.sha256_hex, p_parsed_projection jsonb, p_parse_error_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM raw.require_ingest_writer();
  PERFORM 1 FROM raw.source_asset a
  WHERE a.source_asset_id = p_source_asset_id
    AND a.authority = 'governed_source'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'RUNTIME_SOURCE_RECORD_REQUIRES_GOVERNED_SOURCE_PARENT';
  END IF;
  INSERT INTO raw.source_record (
    source_record_id, source_asset_id, record_ordinal,
    legacy_source_record_id, raw_value, raw_fingerprint,
    parsed_projection, parse_error_code
  ) VALUES (
    p_source_record_id, p_source_asset_id, p_record_ordinal,
    p_legacy_source_record_id, p_raw_value, p_raw_fingerprint,
    p_parsed_projection, p_parse_error_code
  );
END
$$;


--
-- Name: require_ingest_writer(); Type: FUNCTION; Schema: raw; Owner: -
--

CREATE FUNCTION raw.require_ingest_writer() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF session_user::text <> 'gda_v49_phase2a_ingest_writer' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'INGEST_WRITER_REQUIRED';
  END IF;
END
$$;


