--

CREATE FUNCTION release.add_research_asset_to_draft(p_release_id uuid, p_relative_path text, p_resource_kind core.release_token, p_media_type text, p_content_encoding text, p_schema_id text, p_byte_length bigint, p_record_count bigint, p_sha256 core.sha256_hex, p_deterministic_sort_key text, p_partition_description text, p_uncompressed_sha256 core.sha256_hex) RETURNS void
