CREATE FUNCTION release.add_research_count_snapshot_to_draft(p_release_id uuid, p_metric_code core.release_token, p_scope_definition text, p_unit_definition text, p_query_sha256 core.sha256_hex, p_exact_count bigint) RETURNS void
