CREATE FUNCTION release.add_research_membership_projection_to_draft(p_release_id uuid, p_corpus_version_id uuid, p_archive_object_id uuid, p_semantic_relation_id uuid, p_membership_role text, p_publication_layer release.publication_layer, p_metric_code text, p_count_eligibility release.count_eligibility, p_eligibility_reason_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
