--
-- Name: canonical_decimal_text(numeric); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.canonical_decimal_text(p_value numeric) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_text text := trim_scale(p_value)::text;
BEGIN
  IF v_text IN ('NaN', 'Infinity', '-Infinity')
    OR v_text ~ '[eE]' THEN
    RAISE EXCEPTION USING ERRCODE = '22023',
      MESSAGE = 'MANIFEST_DECIMAL_MUST_BE_FINITE_PLAIN_NOTATION';
  END IF;
  IF v_text = '-0' THEN
    RETURN '0';
  END IF;
  RETURN v_text;
END
$$;


--
-- Name: analysis_run_manifest_json(jsonb); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.analysis_run_manifest_json(p_row jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    RETURN ((p_row - ARRAY['score_value'::text, 'uncertainty_lower'::text, 'uncertainty_upper'::text, 'threshold_value'::text]) || jsonb_build_object('score_value', release.canonical_decimal_text(((p_row ->> 'score_value'::text))::numeric), 'uncertainty_lower', release.canonical_decimal_text(((p_row ->> 'uncertainty_lower'::text))::numeric), 'uncertainty_upper', release.canonical_decimal_text(((p_row ->> 'uncertainty_upper'::text))::numeric), 'threshold_value', release.canonical_decimal_text(((p_row ->> 'threshold_value'::text))::numeric)));


--
-- Name: jcs_text(jsonb); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.jcs_text(p_value jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_type text := jsonb_typeof(p_value);
  v_result text;
  v_key text;
  v_item jsonb;
  v_first boolean := true;
  v_number numeric;
BEGIN
  CASE v_type
    WHEN 'null' THEN RETURN 'null';
    WHEN 'boolean' THEN RETURN p_value::text;
    WHEN 'string' THEN RETURN to_jsonb(p_value #>> '{}')::text;
    WHEN 'number' THEN
      v_number := (p_value::text)::numeric;
      IF v_number <> trunc(v_number)
        OR abs(v_number) > 9007199254740991::numeric THEN
        RAISE EXCEPTION USING ERRCODE = '22023',
          MESSAGE = 'JCS_MANIFEST_NUMBER_OUTSIDE_SAFE_INTEGER_DOMAIN';
      END IF;
      RETURN trunc(v_number)::text;
    WHEN 'array' THEN
      v_result := '[';
      FOR v_item IN SELECT value FROM jsonb_array_elements(p_value)
      LOOP
        IF NOT v_first THEN v_result := v_result || ','; END IF;
        v_result := v_result || release.jcs_text(v_item);
        v_first := false;
      END LOOP;
      RETURN v_result || ']';
    WHEN 'object' THEN
      v_result := '{';
      FOR v_key, v_item IN
        SELECT key, value FROM jsonb_each(p_value) ORDER BY key COLLATE "C"
      LOOP
        IF NOT v_first THEN v_result := v_result || ','; END IF;
        v_result := v_result || to_jsonb(v_key)::text || ':'
          || release.jcs_text(v_item);
        v_first := false;
      END LOOP;
      RETURN v_result || '}';
    ELSE
      RAISE EXCEPTION USING ERRCODE = '22023',
        MESSAGE = 'JCS_MANIFEST_UNSUPPORTED_JSON_TYPE';
  END CASE;
END
$$;


--
-- Name: jcs_bytes(jsonb); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.jcs_bytes(p_value jsonb) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    RETURN convert_to(release.jcs_text(p_value), 'UTF8'::name);


--
-- Name: canonical_jsonb_sha256(jsonb); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.canonical_jsonb_sha256(p_value jsonb) RETURNS core.sha256_hex
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    RETURN (encode(sha256(release.jcs_bytes(p_value)), 'hex'::text))::core.sha256_hex;


