--
-- Name: analysis_run; Type: TABLE; Schema: research; Owner: -
--

CREATE TABLE research.analysis_run (
    analysis_run_id uuid NOT NULL,
    method_version core.release_token NOT NULL,
    parameters_sha256 core.sha256_hex NOT NULL,
    input_release_id uuid NOT NULL,
    input_manifest_sha256 core.sha256_hex NOT NULL,
    output_sha256 core.sha256_hex NOT NULL,
    executed_at timestamp with time zone NOT NULL,
    software_sha256 core.sha256_hex NOT NULL,
    input_corpus_version_id uuid NOT NULL,
    input_corpus_policy_sha256 core.sha256_hex NOT NULL,
    score_value numeric NOT NULL,
    score_unit text NOT NULL,
    uncertainty_lower numeric,
    uncertainty_upper numeric,
    threshold_value numeric NOT NULL,
    threshold_unit text NOT NULL,
    CONSTRAINT analysis_run_score_unit_check CHECK ((btrim(score_unit) <> ''::text)),
    CONSTRAINT analysis_run_threshold_unit_check CHECK ((btrim(threshold_unit) <> ''::text)),
    CONSTRAINT analysis_run_uncertainty_order CHECK (((uncertainty_lower IS NULL) OR (uncertainty_upper IS NULL) OR (uncertainty_lower <= uncertainty_upper)))
);


