--
-- Name: append_visual_health_sidecar(uuid, uuid, uuid, uuid, uuid, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.append_visual_health_sidecar(p_sidecar_id uuid, p_registry_id uuid, p_entry_id uuid, p_locator_id uuid, p_health_observation_id uuid, p_audit_event_id uuid, p_audit_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_health rights.endpoint_health_observation%ROWTYPE;
  v_role rights.locator_role;
BEGIN
  PERFORM raw.require_ingest_writer();
  IF NOT EXISTS (
    SELECT 1 FROM release.visual_registry_release r
    WHERE r.visual_registry_release_id = p_registry_id AND r.release_state = 'sealed'
  ) THEN RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'SIDECAR_REQUIRES_SEALED_VISUAL_REGISTRY'; END IF;
  SELECT h.* INTO v_health FROM rights.endpoint_health_observation h
  WHERE h.endpoint_health_observation_id = p_health_observation_id
    AND h.visual_locator_id = p_locator_id;
  SELECT l.locator_role INTO v_role FROM release.visual_registry_public_locator l
  WHERE l.visual_registry_release_id = p_registry_id
    AND l.visual_registry_entry_id = p_entry_id
    AND l.visual_locator_id = p_locator_id;
  IF v_health.endpoint_health_observation_id IS NULL OR v_role IS NULL
    OR v_health.checked_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'HEALTH_SIDECAR_SOURCE_MISMATCH';
  END IF;
  INSERT INTO release.visual_health_sidecar_event (
    visual_health_sidecar_event_id, visual_registry_release_id,
    visual_registry_entry_id, visual_locator_id,
    endpoint_health_observation_id, locator_role, health_state,
    observed_at, valid_until, observation_sha256
  ) VALUES (
    p_sidecar_id, p_registry_id, p_entry_id, p_locator_id,
    p_health_observation_id, v_role, v_health.health_state,
    v_health.checked_at, v_health.valid_until,
    rights.compute_health_observation_sha(p_health_observation_id)
  );
  INSERT INTO audit.sidecar_event VALUES (
    p_audit_event_id, p_sidecar_id, NULL, p_audit_sha256,
    session_user::text, clock_timestamp());
END
$$;


--
-- Name: append_visual_takedown_sidecar(uuid, uuid, uuid, uuid, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.append_visual_takedown_sidecar(p_sidecar_id uuid, p_registry_id uuid, p_entry_id uuid, p_override_id uuid, p_audit_event_id uuid, p_audit_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_entry release.visual_registry_entry%ROWTYPE;
  v_override rights.takedown_override%ROWTYPE;
  v_event rights.takedown_event%ROWTYPE;
BEGIN
  PERFORM rights.require_reviewer();
  SELECT * INTO v_entry FROM release.visual_registry_entry e
  WHERE e.visual_registry_release_id = p_registry_id
    AND e.visual_registry_entry_id = p_entry_id;
  SELECT o.* INTO v_override FROM rights.takedown_override o
  WHERE o.takedown_override_id = p_override_id;
  SELECT e.* INTO v_event FROM rights.takedown_scope s
  JOIN rights.takedown_event e ON e.takedown_event_id = s.takedown_event_id
  WHERE s.takedown_scope_id = v_override.takedown_scope_id;
  IF v_entry.visual_registry_entry_id IS NULL
    OR NOT EXISTS (
      SELECT 1 FROM release.visual_registry_release r
      WHERE r.visual_registry_release_id = p_registry_id AND r.release_state = 'sealed')
    OR NOT rights.scope_matches_bridge(
      v_override.takedown_scope_id, v_entry.object_visual_reference_id) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TAKEDOWN_SIDECAR_SCOPE_MISMATCH';
  END IF;
  INSERT INTO release.visual_takedown_sidecar_event (
    visual_takedown_sidecar_event_id, visual_registry_release_id,
    visual_registry_entry_id, takedown_override_id, restrictive_mode,
    overlay_sha256, effective_from, effective_until, recorded_at
  ) VALUES (
    p_sidecar_id, p_registry_id, p_entry_id, p_override_id,
    v_override.restrictive_mode, v_override.overlay_sha256,
    v_event.effective_from, v_event.effective_until, clock_timestamp()
  );
  INSERT INTO audit.sidecar_event VALUES (
    p_audit_event_id, NULL, p_sidecar_id, p_audit_sha256,
    session_user::text, clock_timestamp());
END
$$;


--
-- Name: assert_legacy_resolution_projection_complete(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.assert_legacy_resolution_projection_complete(p_release_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM release.research_legacy_identity_resolution r
    WHERE r.research_release_id = p_release_id
      AND (
        (r.resolution_state = 'split' AND (
          (SELECT count(*)
           FROM release.research_legacy_identity_split_successor c
           WHERE c.research_release_id = r.research_release_id
             AND c.legacy_identity_resolution_id =
               r.legacy_identity_resolution_id) < 2
          OR EXISTS (
            SELECT s.successor_ordinal + 1,
              s.successor_archive_object_id
            FROM core.legacy_identity_split_successor s
            WHERE s.legacy_identity_resolution_id =
              r.legacy_identity_resolution_id
            EXCEPT
            SELECT c.successor_ordinal, c.successor_archive_object_id
            FROM release.research_legacy_identity_split_successor c
            WHERE c.research_release_id = r.research_release_id
              AND c.legacy_identity_resolution_id =
                r.legacy_identity_resolution_id
          )
          OR EXISTS (
            SELECT c.successor_ordinal, c.successor_archive_object_id
            FROM release.research_legacy_identity_split_successor c
            WHERE c.research_release_id = r.research_release_id
              AND c.legacy_identity_resolution_id =
                r.legacy_identity_resolution_id
            EXCEPT
            SELECT s.successor_ordinal + 1,
              s.successor_archive_object_id
            FROM core.legacy_identity_split_successor s
            WHERE s.legacy_identity_resolution_id =
              r.legacy_identity_resolution_id
          )
        ))
        OR (r.resolution_state <> 'split' AND EXISTS (
          SELECT 1
          FROM release.research_legacy_identity_split_successor c
          WHERE c.research_release_id = r.research_release_id
            AND c.legacy_identity_resolution_id =
              r.legacy_identity_resolution_id
        ))
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE='23514',
      MESSAGE='RESEARCH_LEGACY_SPLIT_PROJECTION_INCOMPLETE';
  END IF;
END
$$;


--
-- Name: assert_required_receipts_complete(release.boundary_kind, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.assert_required_receipts_complete(p_boundary release.boundary_kind, p_release_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_profile_id uuid; v_missing integer;
BEGIN
  IF p_boundary = 'research' THEN
    SELECT validation_profile_id INTO v_profile_id
    FROM release.research_release WHERE research_release_id = p_release_id;
    SELECT count(*) INTO v_missing
    FROM release.validation_profile_requirement req
    WHERE req.validation_profile_id = v_profile_id
      AND NOT EXISTS (
        SELECT 1 FROM release.research_validation_receipt r
        WHERE r.research_release_id = p_release_id
          AND r.receipt_kind = req.receipt_kind
          AND r.validation_result = 'pass'
          AND r.candidate_fingerprint = (
            SELECT candidate_fingerprint FROM release.research_release
            WHERE research_release_id = p_release_id));
  ELSE
    SELECT validation_profile_id INTO v_profile_id
    FROM release.visual_registry_release
    WHERE visual_registry_release_id = p_release_id;
    SELECT count(*) INTO v_missing
    FROM release.validation_profile_requirement req
    WHERE req.validation_profile_id = v_profile_id
      AND NOT EXISTS (
        SELECT 1 FROM release.visual_validation_receipt r
        WHERE r.visual_registry_release_id = p_release_id
          AND r.receipt_kind = req.receipt_kind
          AND r.validation_result = 'pass'
          AND r.candidate_fingerprint = (
            SELECT candidate_fingerprint FROM release.visual_registry_release
            WHERE visual_registry_release_id = p_release_id));
  END IF;
  IF v_missing <> 0 THEN
    RAISE EXCEPTION USING ERRCODE = '55000',
      MESSAGE = 'REQUIRED_VALIDATION_RECEIPT_SET_INCOMPLETE';
  END IF;
END
$$;


--
-- Name: assert_validation_profile_complete(uuid, release.boundary_kind); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.assert_validation_profile_complete(p_profile_id uuid, p_boundary release.boundary_kind) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_missing integer;
  v_extra integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM release.validation_profile p
    WHERE p.validation_profile_id = p_profile_id
      AND p.boundary_kind = p_boundary
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'VALIDATION_PROFILE_BOUNDARY_MISMATCH';
  END IF;

  IF p_boundary = 'research' THEN
    SELECT count(*) INTO v_missing
    FROM unnest(ARRAY[
      'research_frozen_asset_authority',
      'research_migration_query_identity',
      'research_population_and_count_parity',
      'research_corpus_missingness_concentration',
      'research_fk_orphan_integrity',
      'research_predicate_relation_epistemic_registry',
      'research_claim_projection_eligibility',
      'research_unknown_relation_isolation',
      'research_projection_fingerprint',
      'research_deterministic_asset_inventory',
      'research_role_grant_security'
    ]::release.validation_receipt_kind[]) expected(kind)
    WHERE NOT EXISTS (
      SELECT 1 FROM release.validation_profile_requirement r
      WHERE r.validation_profile_id = p_profile_id
        AND r.receipt_kind = expected.kind);
    SELECT count(*) INTO v_extra
    FROM release.validation_profile_requirement r
    WHERE r.validation_profile_id = p_profile_id
      AND r.receipt_kind::text !~ '^research_';
  ELSE
    SELECT count(*) INTO v_missing
    FROM unnest(ARRAY[
      'visual_legacy_disposition',
      'visual_reference_bridge_provider_locator_identity',
      'visual_rights_policy_delivery_health_takedown',
      'visual_attribution_review_due',
      'visual_held_pixel_non_disclosure',
      'visual_research_compatibility',
      'visual_projection_fingerprint',
      'visual_deterministic_asset_inventory',
      'visual_role_grant_security'
    ]::release.validation_receipt_kind[]) expected(kind)
    WHERE NOT EXISTS (
      SELECT 1 FROM release.validation_profile_requirement r
      WHERE r.validation_profile_id = p_profile_id
        AND r.receipt_kind = expected.kind);
    SELECT count(*) INTO v_extra
    FROM release.validation_profile_requirement r
    WHERE r.validation_profile_id = p_profile_id
      AND r.receipt_kind::text !~ '^visual_';
  END IF;
  IF v_missing <> 0 OR v_extra <> 0 THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'VALIDATION_PROFILE_REQUIRED_SET_INCOMPLETE';
  END IF;
END
$$;


--
-- Name: research_launch_build_receipt_v3; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.research_launch_build_receipt_v3 (
    research_release_id uuid NOT NULL,
    builder_version core.release_token NOT NULL,
    migration_batch_id uuid NOT NULL,
    public_corpus_version_id uuid NOT NULL,
    candidate_asset_id uuid NOT NULL,
    candidate_asset_sha256 core.sha256_hex NOT NULL,
