    projection_content_sha256 core.sha256_hex NOT NULL,
    build_receipt_sha256 core.sha256_hex NOT NULL,
    candidate_fingerprint core.sha256_hex NOT NULL,
    built_at timestamp with time zone NOT NULL
);


--
-- Name: research_launch_component_manifest_v3; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.research_launch_component_manifest_v3 (
    research_release_id uuid NOT NULL,
    component_code text NOT NULL,
    row_count bigint NOT NULL,
    content_sha256 core.sha256_hex NOT NULL,
    CONSTRAINT research_launch_component_manifest_v3_component_code_check CHECK ((component_code = ANY (ARRAY['releaseObjects'::text, 'surfacePresentation'::text, 'surfaceCredits'::text, 'surfaceCitations'::text, 'folderTypes'::text, 'folders'::text, 'folderMemberships'::text, 'searchDocuments'::text, 'corpusSummary'::text, 'traceAvailability'::text]))),
    CONSTRAINT research_launch_component_manifest_v3_row_count_check CHECK ((row_count >= 0))
);


--
-- Name: compute_research_launch_candidate_fingerprint_v3(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.compute_research_launch_candidate_fingerprint_v3(p_release_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN release.canonical_jsonb_sha256(jsonb_build_object('format', 'gda-v49-research-candidate-physical-v3', 'releaseId', p_release_id, 'source', (SELECT jsonb_build_object('candidateAssetId', research_launch_build_receipt_v3.candidate_asset_id, 'candidateAssetSha256', research_launch_build_receipt_v3.candidate_asset_sha256, 'migrationBatchId', research_launch_build_receipt_v3.migration_batch_id, 'publicCorpusVersionId', research_launch_build_receipt_v3.public_corpus_version_id, 'mappingSpecificationSha256', research_launch_build_receipt_v3.mapping_specification_sha256, 'projectionQueryPackSha256', research_launch_build_receipt_v3.projection_query_pack_sha256, 'selectionPolicySha256', research_launch_build_receipt_v3.selection_policy_sha256, 'registryCorpusPolicySha256', research_launch_build_receipt_v3.registry_corpus_policy_sha256, 'sourceSnapshotSha256', research_launch_build_receipt_v3.source_snapshot_sha256, 'componentManifestSha256', research_launch_build_receipt_v3.projection_component_manifest_sha256, 'contentSha256', research_launch_build_receipt_v3.projection_content_sha256) AS jsonb_build_object FROM release.research_launch_build_receipt_v3 WHERE (research_launch_build_receipt_v3.research_release_id = compute_research_launch_candidate_fingerprint_v3.p_release_id)), 'components', COALESCE((SELECT jsonb_agg(jsonb_build_array(research_launch_component_manifest_v3.component_code, research_launch_component_manifest_v3.row_count, research_launch_component_manifest_v3.content_sha256) ORDER BY research_launch_component_manifest_v3.component_code) AS jsonb_agg FROM release.research_launch_component_manifest_v3 WHERE (research_launch_component_manifest_v3.research_release_id = compute_research_launch_candidate_fingerprint_v3.p_release_id)), '[]'::jsonb)));


--
-- Name: research_launch_component_manifest_sha_v3(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_component_manifest_sha_v3(p_release_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN release.canonical_jsonb_sha256(jsonb_build_object('format', 'gda-v49-research-component-manifest-jcs-v3', 'components', COALESCE((SELECT jsonb_agg(jsonb_build_array(research_launch_component_manifest_v3.component_code, research_launch_component_manifest_v3.row_count, research_launch_component_manifest_v3.content_sha256) ORDER BY research_launch_component_manifest_v3.component_code) AS jsonb_agg FROM release.research_launch_component_manifest_v3 WHERE (research_launch_component_manifest_v3.research_release_id = research_launch_component_manifest_sha_v3.p_release_id)), '[]'::jsonb)));


--
-- Name: research_folder_membership_projection_v3; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.research_folder_membership_projection_v3 (
    research_release_id uuid NOT NULL,
    folder_id uuid NOT NULL,
    archive_object_id uuid NOT NULL,
    source_assignment_id uuid NOT NULL,
    membership_role text NOT NULL,
    member_ordinal integer NOT NULL,
    source_assignment_status provenance.assertion_status NOT NULL,
    source_assignment_snapshot_sha256 core.sha256_hex NOT NULL,
    effective_decision_id uuid NOT NULL,
    effective_decision_snapshot_sha256 core.sha256_hex NOT NULL,
    CONSTRAINT research_folder_membership_proje_source_assignment_status_check CHECK ((source_assignment_status = 'accepted'::provenance.assertion_status)),
    CONSTRAINT research_folder_membership_projection_v3_member_ordinal_check CHECK ((member_ordinal >= 0)),
    CONSTRAINT research_folder_membership_projection_v3_membership_role_check CHECK ((membership_role ~ '^[a-z][a-z0-9_]*$'::text))
);


--
-- Name: research_trace_availability_projection_v3; Type: TABLE; Schema: release; Owner: -
