    trace_eligible_object_count bigint NOT NULL,
    trace_relation_count bigint NOT NULL,
    availability_reason text NOT NULL,
    CONSTRAINT research_trace_availability_p_trace_eligible_object_count_check CHECK ((trace_eligible_object_count >= 0)),
    CONSTRAINT research_trace_availability_projecti_trace_relation_count_check CHECK ((trace_relation_count >= 0)),
    CONSTRAINT research_trace_availability_projectio_availability_reason_check CHECK ((btrim(availability_reason) <> ''::text))
);


--
-- Name: build_research_launch_manifest_bytes_v3(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.build_research_launch_manifest_bytes_v3(p_release_id uuid) RETURNS bytea
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN convert_to((jsonb_build_object('format', 'gda-v49-research-release-manifest-jcs-v3', 'archiveSnapshotSha256', (SELECT research_launch_build_receipt_v3.source_snapshot_sha256 FROM release.research_launch_build_receipt_v3 WHERE (research_launch_build_receipt_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id)), 'folderTypeCount', (SELECT research_launch_component_manifest_v3.row_count FROM release.research_launch_component_manifest_v3 WHERE ((research_launch_component_manifest_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id) AND (research_launch_component_manifest_v3.component_code = 'folderTypes'::text))), 'folderCount', (SELECT research_launch_component_manifest_v3.row_count FROM release.research_launch_component_manifest_v3 WHERE ((research_launch_component_manifest_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id) AND (research_launch_component_manifest_v3.component_code = 'folders'::text))), 'folderObjectMembershipCount', (SELECT research_launch_component_manifest_v3.row_count FROM release.research_launch_component_manifest_v3 WHERE ((research_launch_component_manifest_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id) AND (research_launch_component_manifest_v3.component_code = 'folderMemberships'::text))), 'publicFolderSurfaceCount', (SELECT count(DISTINCT research_folder_membership_projection_v3.archive_object_id) AS count FROM release.research_folder_membership_projection_v3 WHERE (research_folder_membership_projection_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id)), 'surfacePresentationCount', (SELECT research_launch_component_manifest_v3.row_count FROM release.research_launch_component_manifest_v3 WHERE ((research_launch_component_manifest_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id) AND (research_launch_component_manifest_v3.component_code = 'surfacePresentation'::text))), 'searchDocumentCount', (SELECT research_launch_component_manifest_v3.row_count FROM release.research_launch_component_manifest_v3 WHERE ((research_launch_component_manifest_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id) AND (research_launch_component_manifest_v3.component_code = 'searchDocuments'::text))), 'traceEligibleObjectCount', (SELECT research_trace_availability_projection_v3.trace_eligible_object_count FROM release.research_trace_availability_projection_v3 WHERE (research_trace_availability_projection_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id)), 'builderVersion', (SELECT research_launch_build_receipt_v3.builder_version FROM release.research_launch_build_receipt_v3 WHERE (research_launch_build_receipt_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id)), 'projectionQueryPackSha256', (SELECT research_launch_build_receipt_v3.projection_query_pack_sha256 FROM release.research_launch_build_receipt_v3 WHERE (research_launch_build_receipt_v3.research_release_id = build_research_launch_manifest_bytes_v3.p_release_id)), 'componentManifestSha256', release.research_launch_component_manifest_sha_v3(p_release_id), 'candidateFingerprint', release.compute_research_launch_candidate_fingerprint_v3(p_release_id)))::text, 'UTF8'::name);


--
-- Name: build_research_launch_manifest_bytes_v4(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.build_research_launch_manifest_bytes_v4(p_release_id uuid) RETURNS bytea
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT convert_to(jsonb_build_object(
    'format','gda-v49-research-release-manifest-jcs-v4',
    'archiveSnapshotSha256',(SELECT source_snapshot_sha256 FROM release.research_launch_build_receipt_v3 WHERE research_release_id=p_release_id),
    'folderTypeCount',(SELECT row_count FROM release.research_launch_component_manifest_v3 WHERE research_release_id=p_release_id AND component_code='folderTypes'),
    'folderCount',(SELECT row_count FROM release.research_launch_component_manifest_v3 WHERE research_release_id=p_release_id AND component_code='folders'),
    'folderObjectMembershipCount',(SELECT row_count FROM release.research_launch_component_manifest_v3 WHERE research_release_id=p_release_id AND component_code='folderMemberships'),
    'publicFolderSurfaceCount',(SELECT count(DISTINCT archive_object_id) FROM release.research_folder_membership_projection_v3 WHERE research_release_id=p_release_id),
    'surfacePresentationCount',(SELECT row_count FROM release.research_launch_component_manifest_v3 WHERE research_release_id=p_release_id AND component_code='surfacePresentation'),
    'searchDocumentCount',(SELECT row_count FROM release.research_launch_component_manifest_v3 WHERE research_release_id=p_release_id AND component_code='searchDocuments'),
    'traceEligibleObjectCount',(SELECT trace_eligible_object_count FROM release.research_trace_availability_projection_v3 WHERE research_release_id=p_release_id),
    'builderVersion',(SELECT builder_version FROM release.research_launch_build_receipt_v3 WHERE research_release_id=p_release_id),
    'projectionQueryPackSha256',(SELECT projection_query_pack_sha256 FROM release.research_launch_build_receipt_v3 WHERE research_release_id=p_release_id),
    'componentManifestSha256',release.research_launch_component_manifest_sha_v4(p_release_id),
    'candidateFingerprint',release.compute_research_launch_candidate_fingerprint_v4(p_release_id)
  )::text,'UTF8')
$$;


