--
-- Name: build_research_manifest_bytes(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.build_research_manifest_bytes(p_release_id uuid) RETURNS bytea
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN release.jcs_bytes((SELECT jsonb_build_object('assets', COALESCE((SELECT jsonb_agg(jsonb_build_object('byteLength', a.byte_length, 'mediaType', a.media_type, 'path', a.relative_path, 'recordCount', a.record_count, 'sha256', a.sha256) ORDER BY a.deterministic_sort_key, a.relative_path) AS jsonb_agg FROM release.research_asset a WHERE (a.research_release_id = r.research_release_id)), '[]'::jsonb), 'candidateFingerprint', r.candidate_fingerprint, 'counts', COALESCE((SELECT jsonb_agg(jsonb_build_object('count', c.exact_count, 'metric', c.metric_code, 'querySha256', c.query_sha256) ORDER BY c.metric_code) AS jsonb_agg FROM release.research_count_snapshot c WHERE (c.research_release_id = r.research_release_id)), '[]'::jsonb), 'format', 'gda-v49-research-release-manifest-jcs-v2', 'modelVersion', r.model_version, 'projectionSet', (SELECT jsonb_build_object('databaseSnapshotIdentity', p.database_snapshot_identity, 'migrationSetSha256', p.migration_set_sha256, 'queryPackSha256', p.projection_query_pack_sha256) AS jsonb_build_object FROM release.research_projection_set p WHERE (p.research_release_id = r.research_release_id)), 'receipts', COALESCE((SELECT jsonb_agg(jsonb_build_object('byteLength', x.byte_length, 'kind', x.receipt_kind, 'receiptSha256', x.receipt_sha256, 'result', x.validation_result, 'verifierVersion', x.verifier_version) ORDER BY x.receipt_kind) AS jsonb_agg FROM release.research_validation_receipt x WHERE (x.research_release_id = r.research_release_id)), '[]'::jsonb), 'registrySnapshot', (SELECT (to_jsonb(x.*) - 'research_release_id'::text) FROM release.research_registry_snapshot x WHERE (x.research_release_id = r.research_release_id)), 'researchReleaseId', r.release_token, 'researchReleaseUuid', (r.research_release_id)::text, 'schemaVersion', r.schema_version, 'sourceLineage', COALESCE((SELECT jsonb_agg(jsonb_build_object('authority', x.asset_authority, 'role', x.source_role, 'sha256', x.asset_sha256, 'sourceGitCommit', x.source_git_commit) ORDER BY x.source_role) AS jsonb_agg FROM release.research_source_lineage x WHERE (x.research_release_id = r.research_release_id)), '[]'::jsonb), 'validationProfileSha256', (SELECT p.profile_sha256 FROM release.validation_profile p WHERE (p.validation_profile_id = r.validation_profile_id))) AS jsonb_build_object FROM release.research_release r WHERE (r.research_release_id = build_research_manifest_bytes.p_release_id)));


