--
-- Name: build_validation_receipt_bytes(release.boundary_kind, uuid, release.validation_receipt_kind, core.release_token, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.build_validation_receipt_bytes(p_boundary release.boundary_kind, p_release_id uuid, p_kind release.validation_receipt_kind, p_verifier_version core.release_token, p_evidence_sha256 core.sha256_hex) RETURNS bytea
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    RETURN release.jcs_bytes(jsonb_build_object('boundary', (p_boundary)::text, 'candidateFingerprint', CASE p_boundary WHEN 'research'::release.boundary_kind THEN (SELECT research_release.candidate_fingerprint FROM release.research_release WHERE (research_release.research_release_id = build_validation_receipt_bytes.p_release_id)) ELSE (SELECT visual_registry_release.candidate_fingerprint FROM release.visual_registry_release WHERE (visual_registry_release.visual_registry_release_id = build_validation_receipt_bytes.p_release_id)) END, 'evidenceSha256', p_evidence_sha256, 'receiptKind', (p_kind)::text, 'releaseId', (p_release_id)::text, 'result', 'pass', 'verifierVersion', (p_verifier_version)::text));


