--
-- Name: build_visual_manifest_bytes(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.build_visual_manifest_bytes(p_registry_id uuid) RETURNS bytea
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN release.jcs_bytes((SELECT jsonb_build_object('assets', COALESCE((SELECT jsonb_agg(jsonb_build_object('byteLength', a.byte_length, 'mediaType', a.media_type, 'path', a.relative_path, 'recordCount', a.record_count, 'sha256', a.sha256) ORDER BY a.deterministic_sort_key, a.relative_path) AS jsonb_agg FROM release.visual_registry_asset a WHERE (a.visual_registry_release_id = r.visual_registry_release_id)), '[]'::jsonb), 'candidateFingerprint', r.candidate_fingerprint, 'compatibleResearchManifestSha256', r.compatible_research_manifest_sha256, 'compatibleResearchReleaseId', (r.compatible_research_release_id)::text, 'format', 'gda-v49-visual-registry-manifest-jcs-v2', 'legacyDisposition', (SELECT (to_jsonb(x.*) - 'visual_registry_release_id'::text) FROM release.visual_registry_legacy_disposition_snapshot x WHERE (x.visual_registry_release_id = r.visual_registry_release_id)), 'modelVersion', r.model_version, 'policyInput', (SELECT (to_jsonb(x.*) - 'visual_registry_release_id'::text) FROM release.visual_registry_policy_input x WHERE (x.visual_registry_release_id = r.visual_registry_release_id)), 'receipts', COALESCE((SELECT jsonb_agg(jsonb_build_object('byteLength', x.byte_length, 'kind', x.receipt_kind, 'receiptSha256', x.receipt_sha256, 'result', x.validation_result, 'verifierVersion', x.verifier_version) ORDER BY x.receipt_kind) AS jsonb_agg FROM release.visual_validation_receipt x WHERE (x.visual_registry_release_id = r.visual_registry_release_id)), '[]'::jsonb), 'schemaVersion', r.schema_version, 'validationProfileSha256', (SELECT p.profile_sha256 FROM release.validation_profile p WHERE (p.validation_profile_id = r.validation_profile_id)), 'visualRegistryUuid', (r.visual_registry_release_id)::text, 'visualRegistryVersion', r.registry_version) AS jsonb_build_object FROM release.visual_registry_release r WHERE (r.visual_registry_release_id = build_visual_manifest_bytes.p_registry_id)));


--
-- Name: close_research_candidate(uuid, core.sha256_hex, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.close_research_candidate(p_release_id uuid, p_expected_fingerprint core.sha256_hex, p_event_id uuid, p_event_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_computed core.sha256_hex;v_now timestamptz:=clock_timestamp();
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  PERFORM 1 FROM release.research_release WHERE research_release_id=p_release_id AND release_state='draft' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='RESEARCH_RELEASE_NOT_DRAFT';END IF;
  v_computed:=release.compute_research_candidate_fingerprint(p_release_id);
  IF p_expected_fingerprint IS DISTINCT FROM v_computed THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='RESEARCH_EXPECTED_FINGERPRINT_MISMATCH';END IF;
  UPDATE release.research_release SET release_state='candidate',candidate_fingerprint=v_computed,candidate_at=v_now WHERE research_release_id=p_release_id;
  PERFORM release.validate_research_projection(p_release_id);
  INSERT INTO audit.research_release_event VALUES(p_event_id,p_release_id,'draft','candidate',session_user::text,v_now,p_event_sha256);
END
$$;


--
-- Name: close_visual_candidate(uuid, core.sha256_hex, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.close_visual_candidate(p_registry_id uuid, p_expected_fingerprint core.sha256_hex, p_event_id uuid, p_event_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_computed core.sha256_hex;v_now timestamptz:=clock_timestamp();
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  PERFORM pg_advisory_xact_lock(hashtext('gda_v49_visual_seal_takedown'));
  PERFORM 1 FROM release.visual_registry_release WHERE visual_registry_release_id=p_registry_id AND release_state='draft' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='VISUAL_REGISTRY_NOT_DRAFT';END IF;
  v_computed:=release.compute_visual_candidate_fingerprint(p_registry_id);
  IF p_expected_fingerprint IS DISTINCT FROM v_computed THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='VISUAL_EXPECTED_FINGERPRINT_MISMATCH';END IF;
  UPDATE release.visual_registry_release SET release_state='candidate',candidate_fingerprint=v_computed,candidate_at=v_now WHERE visual_registry_release_id=p_registry_id;
  PERFORM release.validate_visual_projection(p_registry_id);
  INSERT INTO audit.visual_release_event VALUES(p_event_id,p_registry_id,'draft','candidate',session_user::text,v_now,p_event_sha256);
END
$$;


