--
-- Name: compute_research_candidate_fingerprint_v1(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.compute_research_candidate_fingerprint_v1(p_release_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN (encode(sha256(convert_to((jsonb_build_object('format', 'gda-v49-research-candidate-jsonb-v1', 'releaseId', p_release_id, 'objects', COALESCE((SELECT jsonb_agg(jsonb_build_array(o.archive_object_id, o.object_urn, o.legacy_surface_id, o.title, o.publication_layer, o.acceptance_state, o.workflow_state) ORDER BY o.archive_object_id) AS jsonb_agg FROM release.research_release_object o WHERE (o.research_release_id = compute_research_candidate_fingerprint_v1.p_release_id)), '[]'::jsonb), 'corpus', COALESCE((SELECT jsonb_agg(jsonb_build_array(c.corpus_version_id, c.archive_object_id, c.disposition, c.reason_code) ORDER BY c.corpus_version_id, c.archive_object_id) AS jsonb_agg FROM release.research_release_corpus_member c WHERE (c.research_release_id = compute_research_candidate_fingerprint_v1.p_release_id)), '[]'::jsonb), 'claims', COALESCE((SELECT jsonb_agg(jsonb_build_array(c.claim_id, c.claim_revision_id, c.claim_urn, c.epistemic_code, c.wording) ORDER BY c.claim_id) AS jsonb_agg FROM release.research_release_claim c WHERE (c.research_release_id = compute_research_candidate_fingerprint_v1.p_release_id)), '[]'::jsonb), 'relations', COALESCE((SELECT jsonb_agg(jsonb_build_array(r.semantic_relation_id, r.relation_urn, r.relation_code, r.subject_entity_id, r.object_entity_id, r.acceptance_basis, r.supporting_claim_revision_id, r.supporting_decision_id, r.epistemic_code) ORDER BY r.semantic_relation_id) AS jsonb_agg FROM release.research_release_relation r WHERE (r.research_release_id = compute_research_candidate_fingerprint_v1.p_release_id)), '[]'::jsonb), 'nodes', COALESCE((SELECT jsonb_agg(jsonb_build_array(n.corpus_version_id, n.trace_node_id, n.archive_object_id, n.canonical_key, n.label) ORDER BY n.corpus_version_id, n.trace_node_id) AS jsonb_agg FROM release.trace_projection_node n WHERE (n.research_release_id = compute_research_candidate_fingerprint_v1.p_release_id)), '[]'::jsonb), 'edges', COALESCE((SELECT jsonb_agg(jsonb_build_array(e.corpus_version_id, e.subject_trace_node_id, e.semantic_relation_id, e.object_trace_node_id, e.projection_role, e.generation_key) ORDER BY e.corpus_version_id, e.subject_trace_node_id, e.semantic_relation_id, e.object_trace_node_id, e.projection_role) AS jsonb_agg FROM release.trace_projection_edge e WHERE (e.research_release_id = compute_research_candidate_fingerprint_v1.p_release_id)), '[]'::jsonb), 'memberships', COALESCE((SELECT jsonb_agg(jsonb_build_array(m.corpus_version_id, m.archive_object_id, m.semantic_relation_id, m.membership_role, m.publication_layer, m.metric_code, m.count_eligibility, m.eligibility_reason_code) ORDER BY m.corpus_version_id, m.archive_object_id, m.semantic_relation_id, m.membership_role, m.metric_code) AS jsonb_agg FROM release.object_relation_membership_projection m WHERE (m.research_release_id = compute_research_candidate_fingerprint_v1.p_release_id)), '[]'::jsonb), 'metrics', COALESCE((SELECT jsonb_agg(jsonb_build_array(m.archive_object_id, m.metric_code, m.count_eligibility, m.reason_code) ORDER BY m.archive_object_id, m.metric_code) AS jsonb_agg FROM release.research_object_metric_eligibility m WHERE (m.research_release_id = compute_research_candidate_fingerprint_v1.p_release_id)), '[]'::jsonb)))::text, 'UTF8'::name)), 'hex'::text))::core.sha256_hex;


