--
-- Name: compute_research_candidate_fingerprint(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.compute_research_candidate_fingerprint(p_release_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN (encode(sha256(release.jcs_bytes(jsonb_build_object('format', 'gda-v49-research-candidate-physical-v2', 'legacyCoreFingerprint', release.compute_research_candidate_fingerprint_v1(p_release_id), 'release', (SELECT (to_jsonb(r.*) - ARRAY['release_state'::text, 'candidate_fingerprint'::text, 'manifest_sha256'::text, 'candidate_at'::text, 'validated_at'::text, 'sealed_at'::text]) FROM release.research_release r WHERE (r.research_release_id = compute_research_candidate_fingerprint.p_release_id)), 'sourceLineage', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.source_role) AS jsonb_agg FROM release.research_source_lineage x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'projectionSet', (SELECT to_jsonb(x.*) AS to_jsonb FROM release.research_projection_set x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), 'registrySnapshot', (SELECT to_jsonb(x.*) AS to_jsonb FROM release.research_registry_snapshot x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), 'corpusSnapshots', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.corpus_version_id) AS jsonb_agg FROM release.research_corpus_snapshot x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'countSnapshots', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.metric_code) AS jsonb_agg FROM release.research_count_snapshot x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'objects', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.archive_object_id) AS jsonb_agg FROM release.research_release_object x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'corpusMembers', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.corpus_version_id, x.archive_object_id) AS jsonb_agg FROM release.research_release_corpus_member x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'claims', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.claim_id) AS jsonb_agg FROM release.research_release_claim x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'claimEvidence', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.claim_revision_id, x.evidence_item_id, x.evidence_role) AS jsonb_agg FROM release.research_release_claim_evidence x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'analysisRuns', COALESCE((SELECT jsonb_agg(release.analysis_run_manifest_json(to_jsonb(x.*)) ORDER BY x.analysis_run_id) AS jsonb_agg FROM release.research_release_analysis_run x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'relations', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.semantic_relation_id) AS jsonb_agg FROM release.research_release_relation x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'relationEvidence', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.semantic_relation_id, x.evidence_item_id, x.evidence_role, x.evidence_basis) AS jsonb_agg FROM release.research_release_relation_evidence x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'traceNodes', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.corpus_version_id, x.trace_node_id) AS jsonb_agg FROM release.trace_projection_node x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'traceTrees', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.corpus_version_id, x.trace_tree_id) AS jsonb_agg FROM release.trace_tree_projection x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'traceBranches', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.corpus_version_id, x.trace_tree_id, x.trace_branch_id) AS jsonb_agg FROM release.trace_branch_projection x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'traceNodePlacements', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.corpus_version_id, x.trace_node_id, x.trace_tree_id, x.trace_branch_id, x.placement_role) AS jsonb_agg FROM release.trace_node_tree_placement x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'traceEdges', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.corpus_version_id, x.subject_trace_node_id, x.semantic_relation_id, x.object_trace_node_id, x.projection_role) AS jsonb_agg FROM release.trace_projection_edge x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'traceEdgePlacements', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.corpus_version_id, x.subject_trace_node_id, x.semantic_relation_id, x.object_trace_node_id, x.projection_role, x.trace_tree_id, x.trace_branch_id) AS jsonb_agg FROM release.trace_edge_tree_placement x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'memberships', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.corpus_version_id, x.archive_object_id, x.semantic_relation_id, x.membership_role, x.metric_code) AS jsonb_agg FROM release.object_relation_membership_projection x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'metrics', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.archive_object_id, x.metric_code) AS jsonb_agg FROM release.research_object_metric_eligibility x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'legacyResolutions', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.legacy_identity_id) AS jsonb_agg FROM release.research_legacy_identity_resolution x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'legacySplitSuccessors', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.legacy_identity_resolution_id, x.successor_ordinal) AS jsonb_agg FROM release.research_legacy_identity_split_successor x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'folders', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.folder_id) AS jsonb_agg FROM release.research_folder_projection x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'assets', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.deterministic_sort_key, x.relative_path) AS jsonb_agg FROM release.research_asset x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb), 'assetDependencies', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.asset_path, x.dependency_path) AS jsonb_agg FROM release.research_asset_dependency x WHERE (x.research_release_id = compute_research_candidate_fingerprint.p_release_id)), '[]'::jsonb)))), 'hex'::text))::core.sha256_hex;


--
-- Name: compute_research_launch_candidate_fingerprint_v4(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.compute_research_launch_candidate_fingerprint_v4(p_release_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT release.canonical_jsonb_sha256(jsonb_build_object(
    'format','gda-v49-research-candidate-physical-v4','releaseId',p_release_id,
    'source',(SELECT jsonb_build_object('candidateAssetId',candidate_asset_id,
      'candidateAssetSha256',candidate_asset_sha256,'migrationBatchId',migration_batch_id,
      'publicCorpusVersionId',public_corpus_version_id,
      'mappingSpecificationSha256',mapping_specification_sha256,
      'projectionQueryPackSha256',projection_query_pack_sha256,
      'selectionPolicySha256',selection_policy_sha256,
      'registryCorpusPolicySha256',registry_corpus_policy_sha256,
      'sourceSnapshotSha256',source_snapshot_sha256,
      'componentManifestSha256',projection_component_manifest_sha256,
      'contentSha256',projection_content_sha256)
      FROM release.research_launch_build_receipt_v3 WHERE research_release_id=p_release_id),
    'components',coalesce((SELECT jsonb_agg(jsonb_build_array(component_code,row_count,content_sha256)
      ORDER BY component_code) FROM release.research_launch_component_manifest_v3
      WHERE research_release_id=p_release_id),'[]'::jsonb)))
$$;


