    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN (encode(sha256(convert_to((jsonb_build_object('format', 'gda-v49-visual-candidate-jsonb-v1', 'registryId', p_registry_id, 'providers', COALESCE((SELECT jsonb_agg(jsonb_build_array(p.provider_id, p.provider_code, p.display_name, p.provider_snapshot_sha256) ORDER BY p.provider_id) AS jsonb_agg FROM release.visual_registry_provider_snapshot p WHERE (p.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'providerObjects', COALESCE((SELECT jsonb_agg(jsonb_build_array(p.provider_object_id, p.provider_id, p.provider_record_key, p.provider_object_snapshot_sha256) ORDER BY p.provider_object_id) AS jsonb_agg FROM release.visual_registry_provider_object_snapshot p WHERE (p.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'references', COALESCE((SELECT jsonb_agg(jsonb_build_array(r.external_visual_reference_id, r.visual_reference_urn, r.provider_object_id, r.reference_fingerprint, r.reference_snapshot_sha256) ORDER BY r.external_visual_reference_id) AS jsonb_agg FROM release.visual_registry_reference_snapshot r WHERE (r.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'bridges', COALESCE((SELECT jsonb_agg(jsonb_build_array(b.object_visual_reference_id, b.archive_object_id, b.external_visual_reference_id, b.reference_role, b.bridge_snapshot_sha256) ORDER BY b.object_visual_reference_id) AS jsonb_agg FROM release.visual_registry_bridge_snapshot b WHERE (b.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'rights', COALESCE((SELECT jsonb_agg(jsonb_build_array(s.rights_assessment_id, s.assessed_state, ((EXTRACT(epoch FROM s.assessed_at) * (1000000)::numeric))::bigint, s.assessment_snapshot_sha256) ORDER BY s.rights_assessment_id) AS jsonb_agg FROM release.visual_registry_rights_assessment_snapshot s WHERE (s.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'rightsObservations', COALESCE((SELECT jsonb_agg(jsonb_build_array(s.rights_assessment_id, s.rights_observation_id, s.evidence_role, s.evidence_state, s.evidence_item_id, ((EXTRACT(epoch FROM s.observed_at) * (1000000)::numeric))::bigint, s.observation_snapshot_sha256) ORDER BY s.rights_assessment_id, s.rights_observation_id, s.evidence_role) AS jsonb_agg FROM release.visual_registry_rights_observation_snapshot s WHERE (s.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'policyVersions', COALESCE((SELECT jsonb_agg(jsonb_build_array(s.provider_policy_version_id, s.provider_id, s.version_token, s.policy_sha256, s.policy_state, s.source_evidence_item_id, ((EXTRACT(epoch FROM s.effective_from) * (1000000)::numeric))::bigint, CASE WHEN (s.effective_until IS NULL) THEN NULL::bigint ELSE ((EXTRACT(epoch FROM s.effective_until) * (1000000)::numeric))::bigint END, ((EXTRACT(epoch FROM s.review_due) * (1000000)::numeric))::bigint) ORDER BY s.provider_policy_version_id) AS jsonb_agg FROM release.visual_registry_policy_version_snapshot s WHERE (s.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'policyEvaluations', COALESCE((SELECT jsonb_agg(jsonb_build_array(s.provider_policy_evaluation_id, s.object_visual_reference_id, s.evaluated_state, ((EXTRACT(epoch FROM s.evaluated_at) * (1000000)::numeric))::bigint, s.evaluation_snapshot_sha256) ORDER BY s.provider_policy_evaluation_id) AS jsonb_agg FROM release.visual_registry_policy_evaluation_snapshot s WHERE (s.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'policyLinks', COALESCE((SELECT jsonb_agg(jsonb_build_array(s.provider_policy_evaluation_id, s.provider_policy_version_id) ORDER BY s.provider_policy_evaluation_id, s.provider_policy_version_id) AS jsonb_agg FROM release.visual_registry_policy_evaluation_version_snapshot s WHERE (s.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'deliveries', COALESCE((SELECT jsonb_agg(jsonb_build_array(s.delivery_assessment_id, s.object_visual_reference_id, s.attribution_bundle_id, s.base_delivery_mode, s.reason_code, ((EXTRACT(epoch FROM s.assessed_at) * (1000000)::numeric))::bigint, s.rights_outcome_sha256, s.policy_outcome_sha256, s.attribution_bundle_sha256, s.delivery_snapshot_sha256) ORDER BY s.delivery_assessment_id) AS jsonb_agg FROM release.visual_registry_delivery_snapshot s WHERE (s.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'deliveryRights', COALESCE((SELECT jsonb_agg(jsonb_build_array(s.delivery_assessment_id, s.rights_assessment_id, s.evidence_role) ORDER BY s.delivery_assessment_id, s.rights_assessment_id, s.evidence_role) AS jsonb_agg FROM release.visual_registry_delivery_rights_snapshot s WHERE (s.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'deliveryPolicies', COALESCE((SELECT jsonb_agg(jsonb_build_array(s.delivery_assessment_id, s.provider_policy_evaluation_id) ORDER BY s.delivery_assessment_id, s.provider_policy_evaluation_id) AS jsonb_agg FROM release.visual_registry_delivery_policy_snapshot s WHERE (s.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'entries', COALESCE((SELECT jsonb_agg(jsonb_build_array(e.visual_registry_entry_id, e.object_visual_reference_id, e.archive_object_id, e.external_visual_reference_id, e.reference_role, e.delivery_assessment_id, e.object_urn, e.visual_reference_urn, e.provider_code, e.rights_outcome_sha256, e.policy_outcome_sha256, e.attribution_bundle_sha256, e.base_delivery_mode, e.reason_code) ORDER BY e.visual_registry_entry_id) AS jsonb_agg FROM release.visual_registry_entry e WHERE (e.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'attributionValues', COALESCE((SELECT jsonb_agg(jsonb_build_array(a.visual_registry_entry_id, a.value_kind, a.value_ordinal, a.language_tag, a.value_text) ORDER BY a.visual_registry_entry_id, a.value_kind, a.value_ordinal) AS jsonb_agg FROM release.visual_registry_attribution_value a WHERE (a.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'locators', COALESCE((SELECT jsonb_agg(jsonb_build_array(l.visual_registry_entry_id, l.visual_locator_id, l.locator_role, l.locator_ordinal, l.public_locator, l.locator_sha256, l.endpoint_health_observation_id, l.health_state, l.health_method_version, ((EXTRACT(epoch FROM l.health_observed_at) * (1000000)::numeric))::bigint, ((EXTRACT(epoch FROM l.health_valid_until) * (1000000)::numeric))::bigint, l.health_observation_sha256) ORDER BY l.visual_registry_entry_id, l.locator_role, l.locator_ordinal) AS jsonb_agg FROM release.visual_registry_public_locator l WHERE (l.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb), 'takedowns', COALESCE((SELECT jsonb_agg(jsonb_build_array(t.visual_registry_entry_id, t.takedown_override_id, t.restrictive_mode, t.overlay_sha256, ((EXTRACT(epoch FROM t.effective_from) * (1000000)::numeric))::bigint, CASE WHEN (t.effective_until IS NULL) THEN NULL::bigint ELSE ((EXTRACT(epoch FROM t.effective_until) * (1000000)::numeric))::bigint END, ((EXTRACT(epoch FROM t.evaluated_at) * (1000000)::numeric))::bigint) ORDER BY t.visual_registry_entry_id, t.takedown_override_id) AS jsonb_agg FROM release.visual_registry_takedown_snapshot t WHERE (t.visual_registry_release_id = compute_visual_candidate_fingerprint_v1.p_registry_id)), '[]'::jsonb)))::text, 'UTF8'::name)), 'hex'::text))::core.sha256_hex;


