--
-- Name: compute_visual_candidate_fingerprint(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.compute_visual_candidate_fingerprint(p_registry_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN (encode(sha256(release.jcs_bytes(jsonb_build_object('format', 'gda-v49-visual-candidate-physical-v2', 'legacyCoreFingerprint', release.compute_visual_candidate_fingerprint_v1(p_registry_id), 'release', (SELECT (to_jsonb(r.*) - ARRAY['release_state'::text, 'candidate_fingerprint'::text, 'manifest_sha256'::text, 'candidate_at'::text, 'validated_at'::text, 'sealed_at'::text]) FROM release.visual_registry_release r WHERE (r.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), 'policyInput', (SELECT to_jsonb(x.*) AS to_jsonb FROM release.visual_registry_policy_input x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), 'legacyDisposition', (SELECT to_jsonb(x.*) AS to_jsonb FROM release.visual_registry_legacy_disposition_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), 'providers', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.provider_id) AS jsonb_agg FROM release.visual_registry_provider_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'providerObjects', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.provider_object_id) AS jsonb_agg FROM release.visual_registry_provider_object_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'references', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.external_visual_reference_id) AS jsonb_agg FROM release.visual_registry_reference_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'bridges', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.object_visual_reference_id) AS jsonb_agg FROM release.visual_registry_bridge_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'rightsAssessments', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.rights_assessment_id) AS jsonb_agg FROM release.visual_registry_rights_assessment_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'rightsObservations', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.rights_assessment_id, x.rights_observation_id, x.evidence_role) AS jsonb_agg FROM release.visual_registry_rights_observation_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'policyVersions', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.provider_policy_version_id) AS jsonb_agg FROM release.visual_registry_policy_version_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'policyEvaluations', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.provider_policy_evaluation_id) AS jsonb_agg FROM release.visual_registry_policy_evaluation_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'policyLinks', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.provider_policy_evaluation_id, x.provider_policy_version_id) AS jsonb_agg FROM release.visual_registry_policy_evaluation_version_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'deliveries', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.delivery_assessment_id) AS jsonb_agg FROM release.visual_registry_delivery_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'deliveryRights', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.delivery_assessment_id, x.rights_assessment_id, x.evidence_role) AS jsonb_agg FROM release.visual_registry_delivery_rights_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'deliveryPolicies', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.delivery_assessment_id, x.provider_policy_evaluation_id) AS jsonb_agg FROM release.visual_registry_delivery_policy_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'entries', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.visual_registry_entry_id) AS jsonb_agg FROM release.visual_registry_entry x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'attribution', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.visual_registry_entry_id, x.value_kind, x.value_ordinal) AS jsonb_agg FROM release.visual_registry_attribution_value x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'locators', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.visual_registry_entry_id, x.locator_role, x.locator_ordinal) AS jsonb_agg FROM release.visual_registry_public_locator x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'takedowns', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.visual_registry_entry_id, x.takedown_override_id) AS jsonb_agg FROM release.visual_registry_takedown_snapshot x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'assets', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.deterministic_sort_key, x.relative_path) AS jsonb_agg FROM release.visual_registry_asset x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb), 'assetDependencies', COALESCE((SELECT jsonb_agg(to_jsonb(x.*) ORDER BY x.asset_path, x.dependency_path) AS jsonb_agg FROM release.visual_registry_asset_dependency x WHERE (x.visual_registry_release_id = compute_visual_candidate_fingerprint.p_registry_id)), '[]'::jsonb)))), 'hex'::text))::core.sha256_hex;


--
-- Name: compute_visual_validation_receipt_sha(uuid, core.release_token); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.compute_visual_validation_receipt_sha(p_registry_id uuid, p_verifier_version core.release_token) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN release.canonical_jsonb_sha256(jsonb_build_object('format', 'gda-v49-visual-validation-receipt-v1', 'registryId', p_registry_id, 'verifierVersion', p_verifier_version, 'candidateFingerprint', release.compute_visual_candidate_fingerprint_v1(p_registry_id), 'entryCount', (SELECT count(*) AS count FROM release.visual_registry_entry x WHERE (x.visual_registry_release_id = compute_visual_validation_receipt_sha.p_registry_id)), 'locatorCount', (SELECT count(*) AS count FROM release.visual_registry_public_locator x WHERE (x.visual_registry_release_id = compute_visual_validation_receipt_sha.p_registry_id)), 'takedownCount', (SELECT count(*) AS count FROM release.visual_registry_takedown_snapshot x WHERE (x.visual_registry_release_id = compute_visual_validation_receipt_sha.p_registry_id)), 'result', 'pass'));


--
-- Name: visual_seal_event; Type: TABLE; Schema: audit; Owner: -
--

CREATE TABLE audit.visual_seal_event (
    visual_seal_event_id uuid NOT NULL,
    visual_registry_release_id uuid NOT NULL,
    manifest_sha256 core.sha256_hex NOT NULL,
    actor text NOT NULL,
    sealed_at timestamp with time zone NOT NULL,
    seal_transaction_id bigint NOT NULL,
    candidate_fingerprint core.sha256_hex NOT NULL,
    seal_function_version core.release_token NOT NULL,
    CONSTRAINT visual_seal_event_actor_check CHECK ((btrim(actor) <> ''::text))
);


--
-- Name: compute_visual_verification_sidecar_sha(uuid, core.sha256_hex, core.release_token); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.compute_visual_verification_sidecar_sha(p_registry_id uuid, p_manifest_sha256 core.sha256_hex, p_verifier_version core.release_token) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN release.canonical_jsonb_sha256(jsonb_build_object('candidateFingerprint', (SELECT visual_registry_release.candidate_fingerprint FROM release.visual_registry_release WHERE (visual_registry_release.visual_registry_release_id = compute_visual_verification_sidecar_sha.p_registry_id)), 'format', 'gda-v49-visual-verification-sidecar-v2', 'manifestSha256', p_manifest_sha256, 'registryId', (p_registry_id)::text, 'sealFunctionVersion', (SELECT visual_seal_event.seal_function_version FROM audit.visual_seal_event WHERE (visual_seal_event.visual_registry_release_id = compute_visual_verification_sidecar_sha.p_registry_id)), 'sealTransactionId', (SELECT visual_seal_event.seal_transaction_id FROM audit.visual_seal_event WHERE (visual_seal_event.visual_registry_release_id = compute_visual_verification_sidecar_sha.p_registry_id)), 'verifierVersion', p_verifier_version));


--
-- Name: copy_legacy_identity_resolution_to_draft(uuid, uuid, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.copy_legacy_identity_resolution_to_draft(p_release_id uuid, p_legacy_identity_resolution_id uuid, p_target_trace_node_corpus_version_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  PERFORM release.require_research_draft(p_release_id);

  IF EXISTS (
    SELECT 1
    FROM core.legacy_identity_split_successor s
    WHERE s.legacy_identity_resolution_id =
        p_legacy_identity_resolution_id
      AND NOT EXISTS (
        SELECT 1
        FROM release.research_release_object o
        WHERE o.research_release_id = p_release_id
          AND o.archive_object_id = s.successor_archive_object_id
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'LEGACY_SPLIT_SUCCESSOR_NOT_IN_RELEASE_OBJECT_SET';
  END IF;

  INSERT INTO release.research_legacy_identity_resolution (
    research_release_id, legacy_identity_id,
    legacy_identity_resolution_id, identity_kind, namespace, legacy_id,
    resolution_state, target_archive_object_id, target_source_record_id,
    target_trace_node_id, target_folder_id,
    target_trace_edge_corpus_version_id,
    target_trace_edge_subject_node_id, target_trace_edge_relation_id,
    target_trace_edge_object_node_id, target_trace_edge_projection_role,
    reason_code, effective_from, target_trace_node_corpus_version_id
  )
  SELECT p_release_id, i.legacy_identity_id,
    r.legacy_identity_resolution_id, i.identity_kind, i.namespace,
    i.legacy_id, r.resolution_state, r.target_archive_object_id,
    r.target_source_record_id, r.target_trace_node_id,
    r.target_folder_id, r.target_trace_edge_corpus_version_id,
    r.target_trace_edge_subject_node_id, r.target_trace_edge_relation_id,
    r.target_trace_edge_object_node_id,
    r.target_trace_edge_projection_role, r.reason_code,
    r.effective_from, p_target_trace_node_corpus_version_id
  FROM core.legacy_identity_resolution r
  JOIN core.legacy_identity i ON i.legacy_identity_id = r.legacy_identity_id
  WHERE r.legacy_identity_resolution_id = p_legacy_identity_resolution_id
    AND r.effective_release_id = p_release_id
    AND ((r.target_trace_node_id IS NULL
          AND p_target_trace_node_corpus_version_id IS NULL)
      OR (r.target_trace_node_id IS NOT NULL
          AND p_target_trace_node_corpus_version_id IS NOT NULL));
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'LEGACY_RESOLUTION_NOT_EFFECTIVE_FOR_RELEASE';
  END IF;

  INSERT INTO release.research_legacy_identity_split_successor (
    research_release_id, legacy_identity_resolution_id,
    successor_ordinal, successor_archive_object_id, successor_object_urn
  )
  SELECT p_release_id, s.legacy_identity_resolution_id,
    s.successor_ordinal + 1, s.successor_archive_object_id, o.object_urn
  FROM core.legacy_identity_split_successor s
  JOIN release.research_release_object o
    ON o.research_release_id = p_release_id
   AND o.archive_object_id = s.successor_archive_object_id
  WHERE s.legacy_identity_resolution_id = p_legacy_identity_resolution_id;
END
$$;


--
-- Name: copy_research_corpus_snapshot_to_draft(uuid, uuid, uuid, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.copy_research_corpus_snapshot_to_draft(p_release_id uuid, p_corpus_version_id uuid, p_missingness_snapshot_id uuid, p_coverage_snapshot_id uuid, p_concentration_receipt_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  PERFORM release.require_research_draft(p_release_id);
  INSERT INTO release.research_corpus_snapshot (
    research_release_id, corpus_version_id, corpus_token,
    corpus_version_token, selection_policy_sha256, population_frame,
    missingness_snapshot_sha256, coverage_snapshot_sha256,
    concentration_receipt_sha256
  )
  SELECT p_release_id, cv.corpus_version_id, c.corpus_token,
    cv.version_token, cv.policy_sha256, cv.population_frame,
    m.input_sha256, v.input_sha256, p_concentration_receipt_sha256
  FROM research.corpus_version cv
  JOIN research.corpus c ON c.corpus_id = cv.corpus_id
  JOIN research.missingness_snapshot m
    ON m.missingness_snapshot_id = p_missingness_snapshot_id
   AND m.corpus_version_id = cv.corpus_version_id
  JOIN research.coverage_snapshot v
    ON v.coverage_snapshot_id = p_coverage_snapshot_id
   AND v.corpus_version_id = cv.corpus_version_id
  WHERE cv.corpus_version_id = p_corpus_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'CORPUS_MISSINGNESS_COVERAGE_COPY_MISMATCH';
  END IF;
END
$$;


--
-- Name: copy_research_folder_to_draft(uuid, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.copy_research_folder_to_draft(p_release_id uuid, p_folder_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  PERFORM release.require_research_draft(p_release_id);
  INSERT INTO release.research_folder_projection
  SELECT p_release_id, f.folder_id, f.folder_token, f.label
  FROM research.folder f WHERE f.folder_id = p_folder_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'FOLDER_NOT_FOUND';
  END IF;
END
$$;


--
-- Name: copy_trace_branch_to_draft(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.copy_trace_branch_to_draft(p_release_id uuid, p_corpus_version_id uuid, p_trace_tree_id uuid, p_trace_branch_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  PERFORM release.require_research_draft(p_release_id);
  INSERT INTO release.trace_branch_projection
  SELECT p_release_id, p_corpus_version_id, b.trace_tree_id,
    b.trace_branch_id, b.branch_token, b.label
  FROM research.trace_branch b
  WHERE b.trace_tree_id = p_trace_tree_id
    AND b.trace_branch_id = p_trace_branch_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'TRACE_BRANCH_NOT_FOUND';
  END IF;
END
$$;


--
-- Name: copy_trace_node_placement_to_draft(uuid, uuid, uuid, uuid, uuid, core.release_token); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.copy_trace_node_placement_to_draft(p_release_id uuid, p_corpus_version_id uuid, p_trace_node_id uuid, p_trace_tree_id uuid, p_trace_branch_id uuid, p_placement_role core.release_token) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  PERFORM release.require_research_draft(p_release_id);
  INSERT INTO release.trace_node_tree_placement
  SELECT p_release_id, p_corpus_version_id, m.trace_node_id,
    m.trace_tree_id, m.trace_branch_id, m.placement_role,
    m.evidence_item_id
  FROM research.trace_node_tree_membership m
  WHERE m.trace_node_id = p_trace_node_id
    AND m.trace_tree_id = p_trace_tree_id
    AND m.trace_branch_id = p_trace_branch_id
    AND m.placement_role = p_placement_role;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TRACE_NODE_PLACEMENT_SOURCE_MISMATCH';
  END IF;
END
$$;


--
-- Name: copy_trace_tree_to_draft(uuid, uuid, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.copy_trace_tree_to_draft(p_release_id uuid, p_corpus_version_id uuid, p_trace_tree_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  PERFORM release.require_research_draft(p_release_id);
  INSERT INTO release.trace_tree_projection
  SELECT p_release_id, p_corpus_version_id, t.trace_tree_id,
    t.tree_token, t.label, t.evidence_item_id
  FROM research.trace_tree t
  WHERE t.trace_tree_id = p_trace_tree_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'TRACE_TREE_NOT_FOUND';
  END IF;
END
$$;


--
-- Name: copy_visual_entry_to_draft(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.copy_visual_entry_to_draft(p_registry_id uuid, p_entry_id uuid, p_object_visual_reference_id uuid, p_delivery_assessment_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
  v_registry release.visual_registry_release%ROWTYPE;
  v_bridge rights.object_visual_reference%ROWTYPE;
  v_reference rights.external_visual_reference%ROWTYPE;
  v_object core.archive_object%ROWTYPE;
  v_delivery rights.delivery_assessment%ROWTYPE;
  v_provider_object rights.provider_object%ROWTYPE;
  v_provider rights.provider%ROWTYPE;
  v_bridge_decision rights.object_visual_reference_review_decision%ROWTYPE;
  v_machine_reason rights.delivery_reason_code;
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  PERFORM release.require_visual_draft(p_registry_id);
  SELECT * INTO STRICT v_registry
  FROM release.visual_registry_release r
  WHERE r.visual_registry_release_id = p_registry_id
  FOR SHARE;
  SELECT * INTO STRICT v_bridge
  FROM rights.object_visual_reference b
  WHERE b.object_visual_reference_id = p_object_visual_reference_id
    AND b.acceptance_state = 'accepted';
  SELECT * INTO STRICT v_bridge_decision
  FROM rights.object_visual_reference_review_decision d
  WHERE d.object_visual_reference_id = p_object_visual_reference_id
    AND d.outcome = 'accept'
    AND d.evidence_item_id = v_bridge.evidence_item_id
    AND NOT EXISTS (
      SELECT 1
      FROM rights.object_visual_reference_review_decision newer
      WHERE newer.supersedes_decision_id =
        d.object_visual_reference_review_decision_id
    );
  SELECT * INTO STRICT v_reference
  FROM rights.external_visual_reference r
  WHERE r.external_visual_reference_id = v_bridge.external_visual_reference_id;
  SELECT * INTO STRICT v_object
  FROM core.archive_object o
  WHERE o.archive_object_id = v_bridge.archive_object_id;
  SELECT * INTO STRICT v_delivery
  FROM rights.delivery_assessment d
  WHERE d.delivery_assessment_id = p_delivery_assessment_id
    AND d.object_visual_reference_id = p_object_visual_reference_id
    AND NOT EXISTS (
      SELECT 1 FROM rights.delivery_assessment newer
      WHERE newer.supersedes_delivery_assessment_id = d.delivery_assessment_id);
  v_machine_reason := rights.machine_reason_for_rule(v_delivery.reason_code);
  IF v_delivery.machine_reason_code IS DISTINCT FROM v_machine_reason THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'DELIVERY_RULE_MACHINE_REASON_MISMATCH';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM release.research_release_object ro
    WHERE ro.research_release_id = v_registry.compatible_research_release_id
      AND ro.archive_object_id = v_bridge.archive_object_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'VISUAL_OBJECT_NOT_IN_COMPATIBLE_RESEARCH_RELEASE';
  END IF;

  IF v_reference.provider_object_id IS NOT NULL THEN
    SELECT * INTO STRICT v_provider_object
    FROM rights.provider_object po
    WHERE po.provider_object_id = v_reference.provider_object_id;
    SELECT * INTO STRICT v_provider
    FROM rights.provider p
    WHERE p.provider_id = v_provider_object.provider_id;
    INSERT INTO release.visual_registry_provider_snapshot (
      visual_registry_release_id, provider_id, provider_code,
      display_name, provider_snapshot_sha256
    ) VALUES (
      p_registry_id, v_provider.provider_id, v_provider.provider_code,
      v_provider.display_name,
      release.canonical_jsonb_sha256(jsonb_build_array(
        v_provider.provider_id, v_provider.provider_code,
        v_provider.display_name))
    ) ON CONFLICT DO NOTHING;
    INSERT INTO release.visual_registry_provider_object_snapshot (
      visual_registry_release_id, provider_object_id, provider_id,
      provider_record_key, provider_object_snapshot_sha256
    ) VALUES (
      p_registry_id, v_provider_object.provider_object_id,
      v_provider_object.provider_id, v_provider_object.provider_record_key,
      release.canonical_jsonb_sha256(jsonb_build_array(
        v_provider_object.provider_object_id, v_provider_object.provider_id,
        v_provider_object.provider_record_key))
    ) ON CONFLICT DO NOTHING;
  END IF;

  INSERT INTO release.visual_registry_reference_snapshot (
    visual_registry_release_id, external_visual_reference_id,
    visual_reference_urn, provider_object_id, reference_fingerprint,
    reference_snapshot_sha256
  ) VALUES (
    p_registry_id, v_reference.external_visual_reference_id,
    v_reference.visual_reference_urn, v_reference.provider_object_id,
    v_reference.reference_fingerprint,
    release.canonical_jsonb_sha256(jsonb_build_array(
      v_reference.external_visual_reference_id,
      v_reference.visual_reference_urn, v_reference.provider_object_id,
      v_reference.reference_fingerprint))
  ) ON CONFLICT DO NOTHING;

  INSERT INTO release.visual_registry_bridge_snapshot (
    visual_registry_release_id, compatible_research_release_id,
    compatible_research_manifest_sha256, object_visual_reference_id,
    archive_object_id, external_visual_reference_id, reference_role,
    bridge_snapshot_sha256, acceptance_state, evidence_item_id,
    bridge_review_decision_id, evidence_snapshot_sha256,
    decision_snapshot_sha256
  ) VALUES (
    p_registry_id, v_registry.compatible_research_release_id,
    v_registry.compatible_research_manifest_sha256,
    v_bridge.object_visual_reference_id, v_bridge.archive_object_id,
    v_bridge.external_visual_reference_id, v_bridge.reference_role,
    rights.object_visual_reference_snapshot_sha(
      v_bridge.object_visual_reference_id,
      v_registry.compatible_research_release_id,
      v_registry.compatible_research_manifest_sha256),
    v_bridge.acceptance_state, v_bridge.evidence_item_id,
    v_bridge_decision.object_visual_reference_review_decision_id,
    rights.object_visual_reference_evidence_sha(v_bridge.evidence_item_id),
    rights.object_visual_reference_decision_sha(
      v_bridge_decision.object_visual_reference_review_decision_id)
  ) ON CONFLICT DO NOTHING;

  INSERT INTO release.visual_registry_rights_assessment_snapshot (
    visual_registry_release_id, rights_assessment_id,
    assessed_state, assessed_at, assessment_snapshot_sha256
  )
  SELECT p_registry_id, a.rights_assessment_id, a.assessed_state,
    a.assessed_at, rights.compute_rights_assessment_sha(a.rights_assessment_id)
  FROM rights.delivery_rights_assessment x
  JOIN rights.rights_assessment a
    ON a.rights_assessment_id = x.rights_assessment_id
  WHERE x.delivery_assessment_id = p_delivery_assessment_id
  ON CONFLICT DO NOTHING;

  INSERT INTO release.visual_registry_rights_observation_snapshot (
    visual_registry_release_id, rights_assessment_id,
    rights_observation_id, evidence_role, evidence_state,
    evidence_item_id, observed_at, observation_snapshot_sha256
  )
  SELECT p_registry_id, x.rights_assessment_id, o.rights_observation_id,
    x.evidence_role, o.evidence_state, o.evidence_item_id, o.observed_at,
    rights.compute_rights_observation_sha(o.rights_observation_id)
  FROM rights.delivery_rights_assessment d
  JOIN rights.rights_assessment_observation x
    ON x.rights_assessment_id = d.rights_assessment_id
  JOIN rights.rights_observation o
    ON o.rights_observation_id = x.rights_observation_id
  WHERE d.delivery_assessment_id = p_delivery_assessment_id
  ON CONFLICT DO NOTHING;

  INSERT INTO release.visual_registry_policy_evaluation_snapshot (
    visual_registry_release_id, provider_policy_evaluation_id,
    object_visual_reference_id, evaluated_state, evaluated_at,
    evaluation_snapshot_sha256
  )
  SELECT p_registry_id, e.provider_policy_evaluation_id,
    e.object_visual_reference_id, e.evaluated_state, e.evaluated_at,
    rights.compute_provider_policy_evaluation_sha(
      e.provider_policy_evaluation_id)
  FROM rights.delivery_policy_evaluation x
  JOIN rights.provider_policy_evaluation e
    ON e.provider_policy_evaluation_id = x.provider_policy_evaluation_id
  WHERE x.delivery_assessment_id = p_delivery_assessment_id
  ON CONFLICT DO NOTHING;

  INSERT INTO release.visual_registry_policy_version_snapshot (
    visual_registry_release_id, provider_policy_version_id,
    provider_id, version_token, policy_sha256, policy_state,
    source_evidence_item_id, effective_from, effective_until,
    review_due, policy_scope_id
  )
  SELECT p_registry_id, p.provider_policy_version_id, p.provider_id,
    p.version_token, p.policy_sha256, p.policy_state,
    p.source_evidence_item_id, p.effective_from, p.effective_until,
    p.review_due, p.policy_scope_id
  FROM rights.delivery_policy_evaluation d
  JOIN rights.provider_policy_evaluation_version x
    ON x.provider_policy_evaluation_id = d.provider_policy_evaluation_id
  JOIN rights.provider_policy_version p
    ON p.provider_policy_version_id = x.provider_policy_version_id
  WHERE d.delivery_assessment_id = p_delivery_assessment_id
  ON CONFLICT DO NOTHING;

  INSERT INTO release.visual_registry_policy_evaluation_version_snapshot (
    visual_registry_release_id, provider_policy_evaluation_id,
    provider_policy_version_id
  )
  SELECT p_registry_id, d.provider_policy_evaluation_id,
    x.provider_policy_version_id
  FROM rights.delivery_policy_evaluation d
  JOIN rights.provider_policy_evaluation_version x
    ON x.provider_policy_evaluation_id = d.provider_policy_evaluation_id
  WHERE d.delivery_assessment_id = p_delivery_assessment_id
  ON CONFLICT DO NOTHING;

  INSERT INTO release.visual_registry_delivery_snapshot (
    visual_registry_release_id, delivery_assessment_id,
    object_visual_reference_id, attribution_bundle_id,
    base_delivery_mode, reason_code, assessed_at,
    rights_outcome_sha256, policy_outcome_sha256,
    attribution_bundle_sha256, delivery_snapshot_sha256,
    machine_reason_code
  ) VALUES (
    p_registry_id, v_delivery.delivery_assessment_id,
    v_delivery.object_visual_reference_id, v_delivery.attribution_bundle_id,
    v_delivery.delivery_mode, v_delivery.reason_code, v_delivery.assessed_at,
    rights.compute_delivery_rights_sha(v_delivery.delivery_assessment_id),
    rights.compute_delivery_policy_sha(v_delivery.delivery_assessment_id),
    CASE WHEN v_delivery.attribution_bundle_id IS NULL THEN NULL ELSE
      rights.compute_attribution_bundle_sha(
        v_delivery.attribution_bundle_id) END,
    rights.compute_delivery_snapshot_sha(v_delivery.delivery_assessment_id),
    v_machine_reason
  );

  INSERT INTO release.visual_registry_delivery_rights_snapshot
  SELECT p_registry_id, p_delivery_assessment_id,
    x.rights_assessment_id, x.evidence_role
  FROM rights.delivery_rights_assessment x
  WHERE x.delivery_assessment_id = p_delivery_assessment_id;
  INSERT INTO release.visual_registry_delivery_policy_snapshot
  SELECT p_registry_id, p_delivery_assessment_id,
    x.provider_policy_evaluation_id
  FROM rights.delivery_policy_evaluation x
  WHERE x.delivery_assessment_id = p_delivery_assessment_id;

  INSERT INTO release.visual_registry_entry (
    visual_registry_release_id, visual_registry_entry_id,
    compatible_research_release_id,
    compatible_research_manifest_sha256,
    object_visual_reference_id, archive_object_id,
    external_visual_reference_id, reference_role,
    delivery_assessment_id, object_urn, visual_reference_urn,
    provider_code, rights_outcome_sha256, policy_outcome_sha256,
    attribution_bundle_sha256, base_delivery_mode, reason_code,
    machine_reason_code
  ) VALUES (
    p_registry_id, p_entry_id,
    v_registry.compatible_research_release_id,
    v_registry.compatible_research_manifest_sha256,
    v_bridge.object_visual_reference_id, v_bridge.archive_object_id,
    v_bridge.external_visual_reference_id, v_bridge.reference_role,
    v_delivery.delivery_assessment_id, v_object.object_urn,
    v_reference.visual_reference_urn, v_provider.provider_code,
    rights.compute_delivery_rights_sha(v_delivery.delivery_assessment_id),
    rights.compute_delivery_policy_sha(v_delivery.delivery_assessment_id),
    CASE WHEN v_delivery.attribution_bundle_id IS NULL THEN NULL ELSE
      rights.compute_attribution_bundle_sha(
        v_delivery.attribution_bundle_id) END,
    v_delivery.delivery_mode, v_delivery.reason_code, v_machine_reason
  );

  INSERT INTO release.visual_registry_attribution_value
  SELECT p_registry_id, p_entry_id, a.value_kind, a.value_ordinal,
    a.language_tag, a.value_text
  FROM rights.attribution_bundle_value a
  WHERE a.attribution_bundle_id = v_delivery.attribution_bundle_id;

  INSERT INTO release.visual_registry_public_locator
  SELECT p_registry_id, p_entry_id, l.visual_locator_id,
    q.allowlisted_role,
    row_number() OVER (
      PARTITION BY q.allowlisted_role ORDER BY l.visual_locator_id)::integer - 1,
    l.raw_locator, l.locator_fingerprint,
    h.endpoint_health_observation_id, h.health_state, h.method_version,
    h.checked_at, h.valid_until,
    rights.compute_health_observation_sha(h.endpoint_health_observation_id)
  FROM rights.delivery_locator_qualification q
  JOIN rights.visual_locator l ON l.visual_locator_id = q.visual_locator_id
  JOIN rights.endpoint_health_observation h
    ON h.endpoint_health_observation_id = q.endpoint_health_observation_id
  WHERE q.delivery_assessment_id = p_delivery_assessment_id
    AND l.visibility = 'public_candidate'
    AND h.health_state = 'healthy_fresh'
    AND h.checked_at <= clock_timestamp()
    AND h.valid_until > clock_timestamp()
    AND q.allowlisted_role IN (
      'canonical_record', 'source_viewer', 'direct_image')
    AND ((v_delivery.delivery_mode = 'link_only'
          AND q.allowlisted_role = 'canonical_record')
      OR (v_delivery.delivery_mode = 'source_viewer'
          AND q.allowlisted_role IN ('canonical_record', 'source_viewer'))
      OR (v_delivery.delivery_mode = 'remote_image'
          AND q.allowlisted_role IN ('canonical_record', 'direct_image')));

  INSERT INTO release.visual_registry_takedown_snapshot
  SELECT p_registry_id, p_entry_id, o.takedown_override_id,
    o.restrictive_mode, o.overlay_sha256, te.effective_from,
    te.effective_until, clock_timestamp()
  FROM rights.takedown_scope s
  JOIN rights.takedown_event te ON te.takedown_event_id = s.takedown_event_id
  JOIN rights.takedown_override o ON o.takedown_scope_id = s.takedown_scope_id
  WHERE rights.scope_matches_bridge(
      s.takedown_scope_id, p_object_visual_reference_id)
    AND NOT EXISTS (
      SELECT 1 FROM rights.takedown_override newer
      WHERE newer.supersedes_takedown_override_id = o.takedown_override_id)
  ON CONFLICT DO NOTHING;
END
$$;


--
-- Name: create_research_release(uuid, core.release_token, core.release_token, core.release_token, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.create_research_release(p_release_id uuid, p_release_token core.release_token, p_schema_version core.release_token, p_model_version core.release_token, p_event_id uuid, p_event_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_profile uuid;v_now timestamptz:=clock_timestamp();
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  SELECT validation_profile_id INTO v_profile FROM release.validation_profile
  WHERE boundary_kind='research' AND profile_token=p_model_version;
  IF v_profile IS NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='APPROVED_RESEARCH_VALIDATION_PROFILE_REQUIRED';END IF;
  PERFORM release.assert_validation_profile_complete(v_profile,'research');
  INSERT INTO release.research_release(research_release_id,release_token,release_state,schema_version,model_version,created_at,validation_profile_id,validation_boundary)
  VALUES(p_release_id,p_release_token,'draft',p_schema_version,p_model_version,v_now,v_profile,'research');
  INSERT INTO audit.research_release_event VALUES(p_event_id,p_release_id,NULL,'draft',session_user::text,v_now,p_event_sha256);
END
$$;


--
-- Name: create_visual_registry(uuid, core.release_token, core.release_token, core.release_token, uuid, core.sha256_hex, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.create_visual_registry(p_registry_id uuid, p_registry_version core.release_token, p_schema_version core.release_token, p_model_version core.release_token, p_research_release_id uuid, p_research_manifest_sha256 core.sha256_hex, p_event_id uuid, p_event_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_profile uuid;v_now timestamptz:=clock_timestamp();
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  SELECT validation_profile_id INTO v_profile FROM release.validation_profile
  WHERE boundary_kind='visual' AND profile_token=p_model_version;
  IF v_profile IS NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='APPROVED_VISUAL_VALIDATION_PROFILE_REQUIRED';END IF;
  PERFORM release.assert_validation_profile_complete(v_profile,'visual');
  INSERT INTO release.visual_registry_release(visual_registry_release_id,registry_version,release_state,schema_version,model_version,compatible_research_release_id,compatible_research_manifest_sha256,created_at,validation_profile_id,validation_boundary)
  VALUES(p_registry_id,p_registry_version,'draft',p_schema_version,p_model_version,p_research_release_id,p_research_manifest_sha256,v_now,v_profile,'visual');
  INSERT INTO audit.visual_release_event VALUES(p_event_id,p_registry_id,NULL,'draft',session_user::text,v_now,p_event_sha256);
END
$$;


--
-- Name: enforce_analysis_run_copy_source(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.enforce_analysis_run_copy_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a research.analysis_run%ROWTYPE;
BEGIN
  SELECT * INTO STRICT a
  FROM research.analysis_run x
  WHERE x.analysis_run_id = NEW.analysis_run_id;
  IF NEW.method_version IS DISTINCT FROM a.method_version
    OR NEW.software_sha256 IS DISTINCT FROM a.software_sha256
    OR NEW.parameters_sha256 IS DISTINCT FROM a.parameters_sha256
    OR NEW.input_research_release_id IS DISTINCT FROM a.input_release_id
    OR NEW.input_research_manifest_sha256 IS DISTINCT FROM a.input_manifest_sha256
    OR NEW.input_corpus_version_id IS DISTINCT FROM a.input_corpus_version_id
    OR NEW.input_corpus_policy_sha256 IS DISTINCT FROM a.input_corpus_policy_sha256
    OR NEW.score_value IS DISTINCT FROM a.score_value
    OR NEW.score_unit IS DISTINCT FROM a.score_unit
    OR NEW.uncertainty_lower IS DISTINCT FROM a.uncertainty_lower
    OR NEW.uncertainty_upper IS DISTINCT FROM a.uncertainty_upper
    OR NEW.threshold_value IS DISTINCT FROM a.threshold_value
    OR NEW.threshold_unit IS DISTINCT FROM a.threshold_unit
    OR NEW.output_sha256 IS DISTINCT FROM a.output_sha256
    OR NEW.run_snapshot_sha256 IS DISTINCT FROM
      release.analysis_run_snapshot_sha(a.analysis_run_id) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RESEARCH_ANALYSIS_RUN_COPY_SOURCE_MISMATCH';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: enforce_claim_evidence_copy_source(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.enforce_claim_evidence_copy_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e provenance.evidence_item%ROWTYPE;
BEGIN
  SELECT * INTO STRICT e
  FROM provenance.evidence_item x
  WHERE x.evidence_item_id = NEW.evidence_item_id;
  IF NEW.source_asset_id IS DISTINCT FROM e.source_asset_id
    OR NEW.source_version_id IS DISTINCT FROM e.source_version_id
    OR NEW.source_record_id IS DISTINCT FROM e.source_record_id
    OR NEW.locator_scheme IS DISTINCT FROM COALESCE(e.locator_scheme, 'none')
    OR NEW.locator_value IS DISTINCT FROM e.internal_locator
    OR NEW.span_start IS DISTINCT FROM e.span_start
    OR NEW.span_end IS DISTINCT FROM e.span_end
    OR NEW.content_sha256 IS DISTINCT FROM e.content_sha256
    OR NEW.stable_citation IS DISTINCT FROM e.stable_citation
    OR NEW.evidence_snapshot_sha256 IS DISTINCT FROM
      release.evidence_snapshot_sha(e.evidence_item_id) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RESEARCH_CLAIM_EVIDENCE_COPY_SOURCE_MISMATCH';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: enforce_folder_copy_source(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.enforce_folder_copy_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM research.folder f
    WHERE f.folder_id = NEW.folder_id
      AND f.folder_token = NEW.folder_token
      AND f.label = NEW.label
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RESEARCH_FOLDER_COPY_SOURCE_MISMATCH';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: enforce_legacy_resolution_copy_source(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.enforce_legacy_resolution_copy_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM core.legacy_identity_resolution r
    JOIN core.legacy_identity i ON i.legacy_identity_id = r.legacy_identity_id
    WHERE r.legacy_identity_resolution_id = NEW.legacy_identity_resolution_id
      AND r.legacy_identity_id = NEW.legacy_identity_id
      AND i.identity_kind = NEW.identity_kind
      AND i.namespace = NEW.namespace
      AND i.legacy_id = NEW.legacy_id
      AND r.resolution_state = NEW.resolution_state
      AND r.target_archive_object_id IS NOT DISTINCT FROM
        NEW.target_archive_object_id
      AND r.target_source_record_id IS NOT DISTINCT FROM
        NEW.target_source_record_id
      AND r.target_trace_node_id IS NOT DISTINCT FROM NEW.target_trace_node_id
      AND r.target_folder_id IS NOT DISTINCT FROM NEW.target_folder_id
      AND r.target_trace_edge_corpus_version_id IS NOT DISTINCT FROM
        NEW.target_trace_edge_corpus_version_id
      AND r.target_trace_edge_subject_node_id IS NOT DISTINCT FROM
        NEW.target_trace_edge_subject_node_id
      AND r.target_trace_edge_relation_id IS NOT DISTINCT FROM
        NEW.target_trace_edge_relation_id
      AND r.target_trace_edge_object_node_id IS NOT DISTINCT FROM
        NEW.target_trace_edge_object_node_id
      AND r.target_trace_edge_projection_role IS NOT DISTINCT FROM
        NEW.target_trace_edge_projection_role
      AND r.reason_code = NEW.reason_code
      AND r.effective_from = NEW.effective_from
      AND r.effective_release_id = NEW.research_release_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RESEARCH_LEGACY_RESOLUTION_COPY_SOURCE_MISMATCH';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: enforce_legacy_split_copy_source(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.enforce_legacy_split_copy_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM core.legacy_identity_split_successor s
    JOIN core.archive_object o
      ON o.archive_object_id = s.successor_archive_object_id
    WHERE s.legacy_identity_resolution_id = NEW.legacy_identity_resolution_id
      AND s.successor_ordinal + 1 = NEW.successor_ordinal
      AND s.successor_archive_object_id = NEW.successor_archive_object_id
      AND o.object_urn = NEW.successor_object_urn
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RESEARCH_LEGACY_SPLIT_COPY_SOURCE_MISMATCH';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: enforce_public_locator_mode(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.enforce_public_locator_mode() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_entry release.visual_registry_entry%ROWTYPE;
  v_locator rights.visual_locator%ROWTYPE;
  v_health rights.endpoint_health_observation%ROWTYPE;
BEGIN
  SELECT * INTO v_entry FROM release.visual_registry_entry e
  WHERE e.visual_registry_release_id = NEW.visual_registry_release_id
    AND e.visual_registry_entry_id = NEW.visual_registry_entry_id;
  SELECT * INTO v_locator FROM rights.visual_locator l
  WHERE l.visual_locator_id = NEW.visual_locator_id;
  SELECT * INTO v_health FROM rights.endpoint_health_observation h
  WHERE h.endpoint_health_observation_id = NEW.endpoint_health_observation_id;

  IF v_locator.external_visual_reference_id IS DISTINCT FROM v_entry.external_visual_reference_id
    OR v_locator.locator_role IS DISTINCT FROM NEW.locator_role
    OR v_locator.visibility <> 'public_candidate'
    OR v_locator.raw_locator IS DISTINCT FROM NEW.public_locator
    OR v_locator.locator_fingerprint IS DISTINCT FROM NEW.locator_sha256
    OR v_health.visual_locator_id IS DISTINCT FROM NEW.visual_locator_id
    OR v_health.health_state <> 'healthy_fresh'
    OR v_health.checked_at > clock_timestamp()
    OR v_health.valid_until IS NULL
    OR v_health.valid_until <= clock_timestamp()
    OR v_health.health_state IS DISTINCT FROM NEW.health_state
    OR v_health.checked_at IS DISTINCT FROM NEW.health_observed_at
    OR v_health.valid_until IS DISTINCT FROM NEW.health_valid_until
    OR rights.compute_health_observation_sha(NEW.endpoint_health_observation_id)
      IS DISTINCT FROM NEW.health_observation_sha256
    OR NOT EXISTS (
      SELECT 1 FROM rights.delivery_locator_qualification q
      WHERE q.delivery_assessment_id = v_entry.delivery_assessment_id
        AND q.visual_locator_id = NEW.visual_locator_id
        AND q.endpoint_health_observation_id = NEW.endpoint_health_observation_id
        AND q.allowlisted_role = NEW.locator_role
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'PUBLIC_LOCATOR_SOURCE_HEALTH_OR_QUALIFICATION_MISMATCH';
  END IF;
  IF (NEW.locator_role = 'direct_image' AND v_entry.base_delivery_mode <> 'remote_image')
    OR (NEW.locator_role = 'source_viewer' AND v_entry.base_delivery_mode <> 'source_viewer')
    OR (NEW.locator_role = 'canonical_record'
      AND v_entry.base_delivery_mode NOT IN ('link_only', 'source_viewer', 'remote_image')) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'PUBLIC_LOCATOR_NOT_ALLOWED_FOR_DELIVERY_MODE';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: enforce_relation_evidence_copy_source(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.enforce_relation_evidence_copy_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE e provenance.evidence_item%ROWTYPE;
BEGIN
  SELECT * INTO STRICT e
  FROM provenance.evidence_item x
  WHERE x.evidence_item_id = NEW.evidence_item_id;
  IF NEW.source_asset_id IS DISTINCT FROM e.source_asset_id
    OR NEW.source_version_id IS DISTINCT FROM e.source_version_id
    OR NEW.source_record_id IS DISTINCT FROM e.source_record_id
    OR NEW.locator_value IS DISTINCT FROM e.internal_locator
    OR NEW.content_sha256 IS DISTINCT FROM e.content_sha256
    OR NEW.stable_citation IS DISTINCT FROM e.stable_citation
    OR NEW.evidence_snapshot_sha256 IS DISTINCT FROM
      release.evidence_snapshot_sha(e.evidence_item_id) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RESEARCH_RELATION_EVIDENCE_COPY_SOURCE_MISMATCH';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: enforce_takedown_snapshot(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.enforce_takedown_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_entry release.visual_registry_entry%ROWTYPE;
  v_override rights.takedown_override%ROWTYPE;
  v_event rights.takedown_event%ROWTYPE;
BEGIN
  SELECT * INTO v_entry FROM release.visual_registry_entry e
  WHERE e.visual_registry_release_id = NEW.visual_registry_release_id
    AND e.visual_registry_entry_id = NEW.visual_registry_entry_id;
  SELECT * INTO v_override FROM rights.takedown_override o
  WHERE o.takedown_override_id = NEW.takedown_override_id;
  SELECT te.* INTO v_event
  FROM rights.takedown_scope s
  JOIN rights.takedown_event te ON te.takedown_event_id = s.takedown_event_id
  WHERE s.takedown_scope_id = v_override.takedown_scope_id;
  IF NOT rights.scope_matches_bridge(v_override.takedown_scope_id, v_entry.object_visual_reference_id)
    OR v_override.restrictive_mode IS DISTINCT FROM NEW.restrictive_mode
    OR v_override.overlay_sha256 IS DISTINCT FROM NEW.overlay_sha256
    OR v_event.effective_from IS DISTINCT FROM NEW.effective_from
    OR v_event.effective_until IS DISTINCT FROM NEW.effective_until THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TAKEDOWN_SNAPSHOT_SCOPE_OR_COPY_MISMATCH';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: enforce_visual_registry_entry_source(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.enforce_visual_registry_entry_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_delivery rights.delivery_assessment%ROWTYPE;
  v_bridge rights.object_visual_reference%ROWTYPE;
  v_reference rights.external_visual_reference%ROWTYPE;
  v_provider_code text;
  v_object_urn core.canonical_urn;
  v_attribution_sha core.sha256_hex;
BEGIN
  SELECT * INTO v_delivery FROM rights.delivery_assessment d
  WHERE d.delivery_assessment_id = NEW.delivery_assessment_id;
  SELECT * INTO v_bridge FROM rights.object_visual_reference b
  WHERE b.object_visual_reference_id = NEW.object_visual_reference_id;
  SELECT * INTO v_reference FROM rights.external_visual_reference r
  WHERE r.external_visual_reference_id = NEW.external_visual_reference_id;
  SELECT o.object_urn INTO v_object_urn FROM core.archive_object o
  WHERE o.archive_object_id = NEW.archive_object_id;
  SELECT p.provider_code INTO v_provider_code
  FROM rights.provider_object po
  JOIN rights.provider p ON p.provider_id = po.provider_id
  WHERE po.provider_object_id = v_reference.provider_object_id;
  SELECT a.bundle_sha256 INTO v_attribution_sha
  FROM rights.attribution_bundle a
  WHERE a.attribution_bundle_id = v_delivery.attribution_bundle_id;

  IF v_delivery.object_visual_reference_id IS DISTINCT FROM NEW.object_visual_reference_id
    OR v_delivery.delivery_mode IS DISTINCT FROM NEW.base_delivery_mode
    OR v_delivery.reason_code IS DISTINCT FROM NEW.reason_code
    OR v_bridge.archive_object_id IS DISTINCT FROM NEW.archive_object_id
    OR v_bridge.external_visual_reference_id IS DISTINCT FROM NEW.external_visual_reference_id
    OR v_bridge.reference_role IS DISTINCT FROM NEW.reference_role
    OR v_bridge.acceptance_state <> 'accepted'
    OR v_object_urn IS DISTINCT FROM NEW.object_urn
    OR v_reference.visual_reference_urn IS DISTINCT FROM NEW.visual_reference_urn
    OR v_provider_code IS DISTINCT FROM NEW.provider_code
    OR v_attribution_sha IS DISTINCT FROM NEW.attribution_bundle_sha256
    OR rights.compute_delivery_rights_sha(NEW.delivery_assessment_id)
      IS DISTINCT FROM NEW.rights_outcome_sha256
    OR rights.compute_delivery_policy_sha(NEW.delivery_assessment_id)
      IS DISTINCT FROM NEW.policy_outcome_sha256 THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'VISUAL_ENTRY_COPIED_SOURCE_MISMATCH';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: evidence_item; Type: TABLE; Schema: provenance; Owner: -
--

CREATE TABLE provenance.evidence_item (
    evidence_item_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    source_record_id uuid,
    locator_scheme text,
    internal_locator text,
    span_start bigint,
    span_end bigint,
    content_sha256 core.sha256_hex,
    stable_citation text,
    supersedes_evidence_item_id uuid,
    created_at timestamp with time zone NOT NULL,
    source_asset_id uuid NOT NULL,
    CONSTRAINT evidence_item_check CHECK (((span_end IS NULL) OR (span_end >= span_start))),
    CONSTRAINT evidence_item_has_locator_or_hash CHECK (((internal_locator IS NOT NULL) OR (content_sha256 IS NOT NULL) OR (stable_citation IS NOT NULL))),
    CONSTRAINT evidence_item_span_start_check CHECK (((span_start IS NULL) OR (span_start >= 0)))
);


--
-- Name: evidence_snapshot_sha(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.evidence_snapshot_sha(p_evidence_item_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN release.canonical_jsonb_sha256((SELECT to_jsonb(e.*) AS to_jsonb FROM provenance.evidence_item e WHERE (e.evidence_item_id = evidence_snapshot_sha.p_evidence_item_id)));


--
-- Name: guard_research_launch_snapshot_mutation_v3(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.guard_research_launch_snapshot_mutation_v3() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_release_id uuid;
BEGIN
  IF TG_OP='DELETE' THEN
    v_release_id := (to_jsonb(OLD)->>'research_release_id')::uuid;
  ELSE
    v_release_id := (to_jsonb(NEW)->>'research_release_id')::uuid;
  END IF;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)->>'research_release_id') IS DISTINCT FROM
      (to_jsonb(OLD)->>'research_release_id') THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='RESEARCH_LAUNCH_V3_REPARENT_DENIED';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM release.research_release r WHERE r.research_release_id=v_release_id AND r.release_state='draft') THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='RESEARCH_LAUNCH_V3_PROJECTION_CLOSED';
  END IF;
  IF EXISTS (SELECT 1 FROM release.research_launch_build_receipt_v3 b WHERE b.research_release_id=v_release_id) THEN
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='RESEARCH_LAUNCH_V3_POST_BUILD_MUTATION_DENIED';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END
$$;


--
-- Name: guard_research_manifest(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.guard_research_manifest() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_state release.release_state;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'RESEARCH_MANIFEST_IMMUTABLE';
  END IF;
  SELECT r.release_state INTO v_state FROM release.research_release r
  WHERE r.research_release_id = NEW.research_release_id FOR SHARE;
  IF v_state <> 'validated' THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'RESEARCH_MANIFEST_REQUIRES_VALIDATED_RELEASE';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: guard_research_projection_mutation(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.guard_research_projection_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_new jsonb := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  v_old jsonb := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  v_release_id uuid := COALESCE(
    (v_new ->> 'research_release_id')::uuid,
    (v_old ->> 'research_release_id')::uuid
  );
  v_state release.release_state;
BEGIN
  IF TG_OP = 'UPDATE'
    AND (v_new ->> 'research_release_id') IS DISTINCT FROM (v_old ->> 'research_release_id') THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'RESEARCH_PROJECTION_REPARENT_DENIED';
  END IF;
  SELECT r.release_state INTO v_state
  FROM release.research_release r
  WHERE r.research_release_id = v_release_id
  FOR SHARE;
  IF v_state IS DISTINCT FROM 'draft'::release.release_state THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'RESEARCH_PROJECTION_CLOSED';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END
$$;


--
-- Name: guard_research_release_parent(); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.guard_research_release_parent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.release_state <> 'draft' THEN
      RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'RESEARCH_RELEASE_NOT_DELETABLE';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.release_state = 'sealed' THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'SEALED_RELEASE_IMMUTABLE';
  END IF;
  IF OLD.release_token IS DISTINCT FROM NEW.release_token
    OR OLD.schema_version IS DISTINCT FROM NEW.schema_version
    OR OLD.model_version IS DISTINCT FROM NEW.model_version
    OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'RELEASE_IDENTITY_MUTATION_DENIED';
  END IF;
  IF NOT (
    (OLD.release_state = 'draft' AND NEW.release_state = 'candidate')
    OR (OLD.release_state = 'candidate' AND NEW.release_state = 'validated')
    OR (OLD.release_state = 'validated' AND NEW.release_state = 'sealed')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'INVALID_RESEARCH_RELEASE_TRANSITION';
  END IF;
  RETURN NEW;
END
$$;


