--
-- Name: promote_research_current_cas(uuid, core.release_token, bigint, uuid, core.sha256_hex, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.promote_research_current_cas(p_attempt_id uuid, p_channel core.release_token, p_expected_generation bigint, p_expected_release_id uuid, p_expected_manifest_sha256 core.sha256_hex, p_target_release_id uuid) RETURNS TABLE(succeeded boolean, reason_code text, new_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_pointer release.research_current_pointer%ROWTYPE;
  v_target release.research_release%ROWTYPE; v_reason text;
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  SELECT * INTO v_pointer FROM release.research_current_pointer p
    WHERE p.channel = p_channel FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'RESEARCH_CURRENT_CHANNEL_NOT_INITIALIZED'; END IF;
  IF p_expected_generation IS NULL
    OR v_pointer.generation IS DISTINCT FROM p_expected_generation
    OR v_pointer.research_release_id IS DISTINCT FROM p_expected_release_id
    OR v_pointer.manifest_sha256 IS DISTINCT FROM p_expected_manifest_sha256 THEN
    v_reason := 'STALE_RESEARCH_CURRENT_CAS';
  ELSE
    SELECT * INTO v_target FROM release.research_release r
      WHERE r.research_release_id = p_target_release_id;
    IF NOT FOUND OR v_target.release_state <> 'sealed' THEN
      v_reason := 'UNSEALED_RESEARCH_CURRENT_TARGET';
    ELSIF NOT EXISTS (
      SELECT 1 FROM release.research_release_verification v
      WHERE v.research_release_id = v_target.research_release_id
        AND v.manifest_sha256 = v_target.manifest_sha256 AND v.verified
    ) THEN v_reason := 'UNVERIFIED_RESEARCH_CURRENT_TARGET'; END IF;
  END IF;
  IF v_reason IS NOT NULL THEN
    INSERT INTO audit.research_cas_attempt VALUES (
      p_attempt_id, p_channel, COALESCE(p_expected_generation, -1), v_pointer.generation,
      p_target_release_id, false, v_reason, session_user::text, clock_timestamp());
    RETURN QUERY SELECT false, v_reason, v_pointer.generation; RETURN;
  END IF;
  UPDATE release.research_current_pointer SET generation = generation + 1,
    research_release_id = v_target.research_release_id,
    manifest_sha256 = v_target.manifest_sha256, updated_at = clock_timestamp()
  WHERE channel = p_channel;
  IF EXISTS (SELECT 1 FROM release.public_channel c WHERE c.channel = p_channel) THEN
    INSERT INTO release.research_publication_history (
      channel, research_release_id, manifest_sha256,
      promoted_generation, published_at
    ) VALUES (
      p_channel, v_target.research_release_id, v_target.manifest_sha256,
      v_pointer.generation + 1, clock_timestamp()
    );
  END IF;
  INSERT INTO audit.research_cas_attempt VALUES (
    p_attempt_id, p_channel, p_expected_generation, v_pointer.generation,
    p_target_release_id, true, 'PROMOTED', session_user::text, clock_timestamp());
  RETURN QUERY SELECT true, 'PROMOTED'::text, v_pointer.generation + 1;
END
$$;


--
-- Name: promote_visual_current_cas(uuid, core.release_token, bigint, uuid, core.sha256_hex, core.release_token, bigint, uuid, core.sha256_hex, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.promote_visual_current_cas(p_attempt_id uuid, p_research_channel core.release_token, p_expected_research_generation bigint, p_expected_research_release_id uuid, p_expected_research_manifest_sha256 core.sha256_hex, p_visual_channel core.release_token, p_expected_visual_generation bigint, p_expected_visual_release_id uuid, p_expected_visual_manifest_sha256 core.sha256_hex, p_target_visual_release_id uuid) RETURNS TABLE(succeeded boolean, reason_code text, new_generation bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_research release.research_current_pointer%ROWTYPE;
  v_visual release.visual_current_pointer%ROWTYPE;
  v_target release.visual_registry_release%ROWTYPE; v_reason text;
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  SELECT * INTO v_research FROM release.research_current_pointer p
    WHERE p.channel = p_research_channel FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'RESEARCH_CURRENT_CHANNEL_NOT_INITIALIZED'; END IF;
  SELECT * INTO v_visual FROM release.visual_current_pointer p
    WHERE p.channel = p_visual_channel FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'VISUAL_CURRENT_CHANNEL_NOT_INITIALIZED'; END IF;
  IF p_expected_research_generation IS NULL
    OR v_research.research_release_id IS NULL OR v_research.manifest_sha256 IS NULL
    OR v_research.generation IS DISTINCT FROM p_expected_research_generation
    OR v_research.research_release_id IS DISTINCT FROM p_expected_research_release_id
    OR v_research.manifest_sha256 IS DISTINCT FROM p_expected_research_manifest_sha256 THEN
    v_reason := 'STALE_OR_UNAVAILABLE_RESEARCH_GUARD_FOR_VISUAL_CAS';
  ELSIF p_expected_visual_generation IS NULL
    OR v_visual.generation IS DISTINCT FROM p_expected_visual_generation
    OR v_visual.visual_registry_release_id IS DISTINCT FROM p_expected_visual_release_id
    OR v_visual.manifest_sha256 IS DISTINCT FROM p_expected_visual_manifest_sha256 THEN
    v_reason := 'STALE_VISUAL_CURRENT_CAS';
  ELSE
    SELECT * INTO v_target FROM release.visual_registry_release r
      WHERE r.visual_registry_release_id = p_target_visual_release_id;
    IF NOT FOUND OR v_target.release_state <> 'sealed' THEN
      v_reason := 'UNSEALED_VISUAL_CURRENT_TARGET';
    ELSIF NOT EXISTS (
      SELECT 1 FROM release.visual_registry_verification v
      WHERE v.visual_registry_release_id = v_target.visual_registry_release_id
        AND v.manifest_sha256 = v_target.manifest_sha256 AND v.verified
    ) THEN v_reason := 'UNVERIFIED_VISUAL_CURRENT_TARGET';
    ELSIF v_target.compatible_research_release_id IS DISTINCT FROM v_research.research_release_id
      OR v_target.compatible_research_manifest_sha256 IS DISTINCT FROM v_research.manifest_sha256 THEN
      v_reason := 'RELEASE_VERSION_MISMATCH'; END IF;
  END IF;
  IF v_reason IS NOT NULL THEN
    INSERT INTO audit.visual_cas_attempt VALUES (
      p_attempt_id, p_visual_channel, COALESCE(p_expected_visual_generation, -1),
      v_visual.generation, p_target_visual_release_id, v_research.research_release_id,
      false, v_reason, session_user::text, clock_timestamp());
    RETURN QUERY SELECT false, v_reason, v_visual.generation; RETURN;
  END IF;
  UPDATE release.visual_current_pointer SET generation = generation + 1,
    visual_registry_release_id = v_target.visual_registry_release_id,
    manifest_sha256 = v_target.manifest_sha256, updated_at = clock_timestamp()
  WHERE channel = p_visual_channel;
  IF EXISTS (
    SELECT 1 FROM release.public_channel c WHERE c.channel = p_visual_channel
  ) THEN
    INSERT INTO release.visual_publication_history (
      channel, visual_registry_release_id, manifest_sha256,
      promoted_generation, published_at
    ) VALUES (
      p_visual_channel, v_target.visual_registry_release_id,
      v_target.manifest_sha256, v_visual.generation + 1,
      clock_timestamp()
    );
  END IF;
  INSERT INTO audit.visual_cas_attempt VALUES (
    p_attempt_id, p_visual_channel, p_expected_visual_generation,
    v_visual.generation, p_target_visual_release_id, v_research.research_release_id,
    true, 'PROMOTED', session_user::text, clock_timestamp());
  RETURN QUERY SELECT true, 'PROMOTED'::text, v_visual.generation + 1;
END
$$;


--
-- Name: record_research_launch_verification_v5(uuid, uuid, core.sha256_hex, core.release_token, core.sha256_hex, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.record_research_launch_verification_v5(p_verification_id uuid, p_release_id uuid, p_manifest_sha256 core.sha256_hex, p_verifier_version core.release_token, p_sidecar_sha256 core.sha256_hex, p_audit_event_id uuid, p_audit_receipt_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_expected core.sha256_hex;
  v_seal audit.research_seal_event%ROWTYPE;
  v_now timestamptz:=clock_timestamp();
BEGIN
  PERFORM rights.require_reviewer();
  PERFORM release.validate_research_launch_snapshot_v5_integrity(p_release_id);
  IF NOT EXISTS (
    SELECT 1
    FROM release.research_release r
    JOIN release.research_launch_manifest_v3 lm USING(research_release_id)
    JOIN release.research_release_manifest m USING(research_release_id)
    WHERE r.research_release_id=p_release_id
      AND r.release_state='sealed'
      AND r.manifest_sha256=p_manifest_sha256
      AND lm.manifest_sha256=p_manifest_sha256
      AND m.manifest_sha256=p_manifest_sha256
      AND lm.manifest_bytes=m.manifest_bytes
      AND m.manifest_bytes=release.build_research_launch_manifest_bytes_v5(p_release_id)
      AND encode(sha256(m.manifest_bytes),'hex')=p_manifest_sha256
      AND r.candidate_fingerprint=
        release.compute_research_launch_candidate_fingerprint_v5(p_release_id)
  ) THEN
    RAISE EXCEPTION USING ERRCODE='23514',
      MESSAGE='SEALED_RESEARCH_LAUNCH_V5_DETACHED_INTEGRITY_FAILURE';
  END IF;
  SELECT * INTO STRICT v_seal FROM audit.research_seal_event
  WHERE research_release_id=p_release_id
    AND seal_function_version='release-snapshot-v5';
  v_expected:=release.compute_research_verification_sidecar_sha(
    p_release_id,p_manifest_sha256,p_verifier_version);
  IF p_sidecar_sha256 IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION USING ERRCODE='23514',
      MESSAGE='RESEARCH_LAUNCH_V5_VERIFICATION_SIDECAR_MISMATCH';
  END IF;
  INSERT INTO release.research_release_verification(
    research_release_verification_id,research_release_id,manifest_sha256,
    verifier_version,sidecar_sha256,verified,verified_at,seal_transaction_id,
    candidate_fingerprint,seal_function_version,attestation_sha256)
  VALUES(p_verification_id,p_release_id,p_manifest_sha256,p_verifier_version,
    p_sidecar_sha256,true,v_now,v_seal.seal_transaction_id,
    v_seal.candidate_fingerprint,v_seal.seal_function_version,NULL);
  INSERT INTO audit.verification_receipt_event VALUES(
    p_audit_event_id,p_verification_id,NULL,p_audit_receipt_sha256,
    session_user::text,v_now);
END
$$;


--
-- Name: record_research_validation_receipt(uuid, uuid, release.validation_receipt_kind, core.release_token, core.sha256_hex, bytea, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.record_research_validation_receipt(p_receipt_id uuid, p_release_id uuid, p_kind release.validation_receipt_kind, p_verifier_version core.release_token, p_evidence_sha256 core.sha256_hex, p_receipt_bytes bytea, p_audit_event_id uuid) RETURNS core.sha256_hex
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_expected bytea;v_sha core.sha256_hex;v_fingerprint core.sha256_hex;v_now timestamptz:=clock_timestamp();
BEGIN
  PERFORM rights.require_reviewer();
  SELECT candidate_fingerprint INTO v_fingerprint FROM release.research_release
  WHERE research_release_id=p_release_id AND release_state='candidate' FOR SHARE;
  IF NOT FOUND OR p_kind::text !~ '^research_' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='RESEARCH_RECEIPT_REQUIRES_CANDIDATE_AND_RESEARCH_KIND';END IF;
  IF NOT EXISTS (SELECT 1 FROM release.validation_profile_requirement req JOIN release.research_release r ON r.validation_profile_id=req.validation_profile_id WHERE r.research_release_id=p_release_id AND req.receipt_kind=p_kind) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='RECEIPT_KIND_NOT_REQUIRED_BY_PROFILE';END IF;
  v_expected:=release.build_validation_receipt_bytes('research',p_release_id,p_kind,p_verifier_version,p_evidence_sha256);
  IF p_receipt_bytes IS DISTINCT FROM v_expected THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='RESEARCH_RECEIPT_BYTES_NOT_CANONICAL_OR_BOUND';END IF;
  v_sha:=encode(sha256(p_receipt_bytes),'hex')::core.sha256_hex;
  INSERT INTO release.research_validation_receipt(
    research_validation_receipt_id,research_release_id,candidate_fingerprint,
    verifier_version,receipt_sha256,validation_result,checked_at,
    receipt_kind,receipt_bytes,byte_length)
  VALUES(p_receipt_id,p_release_id,v_fingerprint,p_verifier_version,v_sha,'pass',v_now,p_kind,p_receipt_bytes,octet_length(p_receipt_bytes));
  INSERT INTO audit.research_validation_receipt_event VALUES(
    p_audit_event_id,p_receipt_id,session_user::text,v_now,
    release.canonical_jsonb_sha256(jsonb_build_array(p_audit_event_id,p_receipt_id,session_user::text,(extract(epoch FROM v_now)*1000000)::bigint,v_sha)));
  RETURN v_sha;
END
$$;


--
-- Name: record_research_verification(uuid, uuid, core.sha256_hex, core.release_token, core.sha256_hex, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
