CREATE FUNCTION release.record_research_verification(p_verification_id uuid, p_release_id uuid, p_manifest_sha256 core.sha256_hex, p_verifier_version core.release_token, p_sidecar_sha256 core.sha256_hex, p_audit_event_id uuid, p_audit_receipt_sha256 core.sha256_hex) RETURNS void
