--
-- Name: require_research_draft(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.require_research_draft(p_release_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM 1
  FROM release.research_release r
  WHERE r.research_release_id = p_release_id
    AND r.release_state = 'draft'
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '55000',
      MESSAGE = 'RESEARCH_DRAFT_REQUIRED';
  END IF;
END
$$;


--
-- Name: require_session_actor(text); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.require_session_actor(p_expected text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF session_user::text <> p_expected THEN
    RAISE EXCEPTION USING ERRCODE = '42501',
      MESSAGE = 'ROLE_NOT_AUTHORIZED_FOR_CONTROLLED_FUNCTION';
  END IF;
END
$$;


