--
-- Name: assignment_folder_membership; Type: TABLE; Schema: provenance; Owner: -
--

CREATE TABLE provenance.assignment_folder_membership (
    canonical_assignment_id uuid NOT NULL,
    folder_id uuid NOT NULL,
    archive_object_id uuid NOT NULL,
    membership_role text NOT NULL,
    member_ordinal integer NOT NULL,
    CONSTRAINT assignment_folder_membership_member_ordinal_check CHECK ((member_ordinal >= 0)),
    CONSTRAINT assignment_folder_membership_membership_role_check CHECK ((membership_role ~ '^[a-z][a-z0-9_]*$'::text))
);


--
-- Name: canonical_assignment; Type: TABLE; Schema: provenance; Owner: -
--

CREATE TABLE provenance.canonical_assignment (
    canonical_assignment_id uuid NOT NULL,
    assignment_kind provenance.assignment_kind NOT NULL,
    status provenance.assertion_status NOT NULL,
    supersedes_assignment_id uuid,
    created_at timestamp with time zone NOT NULL
);


--
-- Name: research_launch_assignment_snapshot_sha_v3(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_assignment_snapshot_sha_v3(p_assignment_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN release.canonical_jsonb_sha256(jsonb_build_object('assignment', (SELECT jsonb_build_array(a.canonical_assignment_id, a.assignment_kind, a.status) AS jsonb_build_array FROM provenance.canonical_assignment a WHERE (a.canonical_assignment_id = research_launch_assignment_snapshot_sha_v3.p_assignment_id)), 'membership', (SELECT jsonb_build_array(m.folder_id, m.archive_object_id, m.membership_role, m.member_ordinal) AS jsonb_build_array FROM provenance.assignment_folder_membership m WHERE (m.canonical_assignment_id = research_launch_assignment_snapshot_sha_v3.p_assignment_id))));


--
-- Name: research_launch_assignment_snapshot_sha_v4(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_assignment_snapshot_sha_v4(p_assignment_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT encode(sha256(convert_to(jsonb_build_object(
    'assignment',(SELECT jsonb_build_array(a.canonical_assignment_id,a.assignment_kind,a.status,a.supersedes_assignment_id)
      FROM provenance.canonical_assignment a WHERE a.canonical_assignment_id=p_assignment_id),
    'membership',(SELECT jsonb_build_array(m.folder_id,m.archive_object_id,m.membership_role,m.member_ordinal)
      FROM provenance.assignment_folder_membership m WHERE m.canonical_assignment_id=p_assignment_id)
  )::text,'UTF8')),'hex')::core.sha256_hex
$$;


--
-- Name: research_launch_component_hash_staged_v5(text); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_component_hash_staged_v5(p_component text) RETURNS core.sha256_hex
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_hash core.sha256_hex;
BEGIN
  WITH chunks AS (
    SELECT ((row_number-1)/1024)::bigint AS chunk_ordinal,count(*)::bigint AS chunk_row_count,
      encode(sha256(convert_to(jsonb_build_object(
        'format','gda-v49-research-component-chunk-v5','component',p_component,
        'chunkSize',1024,'chunkOrdinal',((row_number-1)/1024)::bigint,
        'rowDigests',jsonb_agg(row_digest ORDER BY row_number)
      )::text,'UTF8')),'hex') AS chunk_digest
    FROM (
      SELECT row_number() OVER (ORDER BY semantic_key) AS row_number,row_digest
      FROM pg_temp.gda_v5_component_rows WHERE component_code=p_component
    ) rows GROUP BY ((row_number-1)/1024)
  )
  SELECT encode(sha256(convert_to(jsonb_build_object(
    'format','gda-v49-research-component-merkle-v5','component',p_component,
    'rowCount',coalesce((SELECT sum(chunk_row_count) FROM chunks),0),
    'chunkSize',1024,
    'chunks',coalesce((SELECT jsonb_agg(jsonb_build_array(chunk_ordinal,chunk_row_count,chunk_digest)
      ORDER BY chunk_ordinal) FROM chunks),'[]'::jsonb)
  )::text,'UTF8')),'hex')::core.sha256_hex INTO v_hash;
  RETURN v_hash;
END
$$;


--
-- Name: research_launch_component_hash_v3(uuid, text); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_component_hash_v3(p_release_id uuid, p_component text) RETURNS core.sha256_hex
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_rows jsonb;
BEGIN
  CASE p_component
    WHEN 'releaseObjects' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(archive_object_id, object_urn,
        legacy_surface_id, title, publication_layer, acceptance_state, workflow_state)
        ORDER BY archive_object_id), '[]'::jsonb) INTO v_rows
      FROM release.research_release_object WHERE research_release_id = p_release_id;
    WHEN 'surfacePresentation' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(archive_object_id, public_surface_id,
        title, title_missingness, display_date, display_date_missingness,
        normalized_year, normalized_year_missingness, place_label, place_missingness,
        medium_label, medium_missingness, type_label, type_missingness, source_label,
        description, description_missingness, public_citation_label, public_source_route,
        publication_layer) ORDER BY archive_object_id), '[]'::jsonb) INTO v_rows
      FROM release.research_surface_presentation_projection_v3 WHERE research_release_id = p_release_id;
    WHEN 'surfaceCredits' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(archive_object_id, credit_ordinal,
        credited_label, credit_role) ORDER BY archive_object_id, credit_ordinal), '[]'::jsonb) INTO v_rows
      FROM release.research_surface_credit_projection_v3 WHERE research_release_id = p_release_id;
    WHEN 'surfaceCitations' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(archive_object_id, citation_ordinal,
        citation_label, public_source_route) ORDER BY archive_object_id, citation_ordinal), '[]'::jsonb) INTO v_rows
      FROM release.research_surface_citation_projection_v3 WHERE research_release_id = p_release_id;
    WHEN 'folderTypes' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(folder_type_code, type_label, sort_ordinal)
        ORDER BY sort_ordinal, folder_type_code), '[]'::jsonb) INTO v_rows
      FROM release.research_folder_type_projection_v3 WHERE research_release_id = p_release_id;
    WHEN 'folders' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(folder_id, folder_token, folder_type_code,
        slug, label, scope_note, sort_ordinal) ORDER BY folder_type_code, sort_ordinal, folder_id), '[]'::jsonb) INTO v_rows
      FROM release.research_folder_projection_v3 WHERE research_release_id = p_release_id;
    WHEN 'folderMemberships' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(folder_id, archive_object_id,
        source_assignment_id, membership_role, member_ordinal, source_assignment_status,
        source_assignment_snapshot_sha256, effective_decision_id,
        effective_decision_snapshot_sha256) ORDER BY folder_id, membership_role,
        member_ordinal, archive_object_id), '[]'::jsonb) INTO v_rows
      FROM release.research_folder_membership_projection_v3 WHERE research_release_id = p_release_id;
    WHEN 'searchDocuments' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(archive_object_id, public_surface_id,
        title, search_document, sort_key) ORDER BY sort_key, archive_object_id), '[]'::jsonb) INTO v_rows
      FROM release.research_search_document_projection_v3 WHERE research_release_id = p_release_id;
    WHEN 'corpusSummary' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(corpus_version_id, corpus_token,
        corpus_version_token, corpus_label, eligible_object_count, held_object_count)
        ORDER BY corpus_version_id), '[]'::jsonb) INTO v_rows
      FROM release.research_corpus_summary_projection_v3 WHERE research_release_id = p_release_id;
    WHEN 'traceAvailability' THEN
      SELECT COALESCE(jsonb_agg(jsonb_build_array(trace_eligible_object_count,
        trace_relation_count, availability_reason) ORDER BY research_release_id), '[]'::jsonb) INTO v_rows
      FROM release.research_trace_availability_projection_v3 WHERE research_release_id = p_release_id;
    ELSE RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'UNKNOWN_LAUNCH_COMPONENT';
  END CASE;
  RETURN release.canonical_jsonb_sha256(jsonb_build_object(
    'format', 'gda-v49-research-component-jcs-v3', 'component', p_component, 'rows', v_rows));
END
$$;


--
-- Name: research_launch_component_hash_v4(uuid, text); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_component_hash_v4(p_release_id uuid, p_component text) RETURNS core.sha256_hex
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_rows text;
BEGIN
  CASE p_component
    WHEN 'releaseObjects' THEN SELECT string_agg(jsonb_build_array(archive_object_id,object_urn,legacy_surface_id,title,publication_layer,acceptance_state,workflow_state)::text,E'\n' ORDER BY archive_object_id) INTO v_rows FROM release.research_release_object WHERE research_release_id=p_release_id;
    WHEN 'surfacePresentation' THEN SELECT string_agg(jsonb_build_array(archive_object_id,public_surface_id,title,title_missingness,display_date,display_date_missingness,normalized_year,normalized_year_missingness,place_label,place_missingness,medium_label,medium_missingness,type_label,type_missingness,source_label,description,description_missingness,public_citation_label,public_source_route,publication_layer)::text,E'\n' ORDER BY archive_object_id) INTO v_rows FROM release.research_surface_presentation_projection_v3 WHERE research_release_id=p_release_id;
    WHEN 'surfaceCredits' THEN SELECT string_agg(jsonb_build_array(archive_object_id,credit_ordinal,credited_label,credit_role)::text,E'\n' ORDER BY archive_object_id,credit_ordinal) INTO v_rows FROM release.research_surface_credit_projection_v3 WHERE research_release_id=p_release_id;
    WHEN 'surfaceCitations' THEN SELECT string_agg(jsonb_build_array(archive_object_id,citation_ordinal,citation_label,public_source_route)::text,E'\n' ORDER BY archive_object_id,citation_ordinal) INTO v_rows FROM release.research_surface_citation_projection_v3 WHERE research_release_id=p_release_id;
    WHEN 'folderTypes' THEN SELECT string_agg(jsonb_build_array(folder_type_code,type_label,sort_ordinal)::text,E'\n' ORDER BY sort_ordinal,folder_type_code) INTO v_rows FROM release.research_folder_type_projection_v3 WHERE research_release_id=p_release_id;
    WHEN 'folders' THEN SELECT string_agg(jsonb_build_array(folder_id,folder_token,folder_type_code,slug,label,scope_note,sort_ordinal)::text,E'\n' ORDER BY folder_type_code,sort_ordinal,folder_id) INTO v_rows FROM release.research_folder_projection_v3 WHERE research_release_id=p_release_id;
    WHEN 'folderMemberships' THEN SELECT string_agg(jsonb_build_array(folder_id,archive_object_id,source_assignment_id,membership_role,member_ordinal,source_assignment_status,source_assignment_snapshot_sha256,effective_decision_id,effective_decision_snapshot_sha256)::text,E'\n' ORDER BY folder_id,membership_role,member_ordinal,archive_object_id) INTO v_rows FROM release.research_folder_membership_projection_v3 WHERE research_release_id=p_release_id;
    WHEN 'searchDocuments' THEN SELECT string_agg(jsonb_build_array(archive_object_id,public_surface_id,title,search_document,sort_key)::text,E'\n' ORDER BY sort_key,archive_object_id) INTO v_rows FROM release.research_search_document_projection_v3 WHERE research_release_id=p_release_id;
    WHEN 'corpusSummary' THEN SELECT string_agg(jsonb_build_array(corpus_version_id,corpus_token,corpus_version_token,corpus_label,eligible_object_count,held_object_count)::text,E'\n' ORDER BY corpus_version_id) INTO v_rows FROM release.research_corpus_summary_projection_v3 WHERE research_release_id=p_release_id;
    WHEN 'traceAvailability' THEN SELECT string_agg(jsonb_build_array(trace_eligible_object_count,trace_relation_count,availability_reason)::text,E'\n' ORDER BY research_release_id) INTO v_rows FROM release.research_trace_availability_projection_v3 WHERE research_release_id=p_release_id;
    ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='UNKNOWN_LAUNCH_COMPONENT';
  END CASE;
  RETURN encode(sha256(convert_to(coalesce(v_rows,''),'UTF8')),'hex')::core.sha256_hex;
END
$$;


--
-- Name: research_launch_component_hash_v5(uuid, text); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_component_hash_v5(p_release_id uuid, p_component text) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  WITH rows AS (
    SELECT row_number() OVER (ORDER BY semantic_key) AS rn,
      encode(sha256(convert_to(row_payload::text,'UTF8')),'hex') AS row_digest
    FROM release.research_launch_component_rows_v5(p_release_id,p_component)
  ), chunks AS (
    SELECT ((rn-1)/1024)::bigint AS chunk_ordinal,count(*)::bigint AS chunk_row_count,
      encode(sha256(convert_to(jsonb_build_object(
        'format','gda-v49-research-component-chunk-v5','component',p_component,
        'chunkSize',1024,'chunkOrdinal',((rn-1)/1024)::bigint,
        'rowDigests',jsonb_agg(row_digest ORDER BY rn)
      )::text,'UTF8')),'hex') AS chunk_digest
    FROM rows GROUP BY ((rn-1)/1024)
  )
  SELECT encode(sha256(convert_to(jsonb_build_object(
    'format','gda-v49-research-component-merkle-v5','component',p_component,
    'rowCount',coalesce((SELECT sum(chunk_row_count) FROM chunks),0),
    'chunkSize',1024,
    'chunks',coalesce((SELECT jsonb_agg(jsonb_build_array(chunk_ordinal,chunk_row_count,chunk_digest)
      ORDER BY chunk_ordinal) FROM chunks),'[]'::jsonb)
  )::text,'UTF8')),'hex')::core.sha256_hex
$$;


