--
-- Name: assignment_decision_evidence; Type: TABLE; Schema: provenance; Owner: -
--

CREATE TABLE provenance.assignment_decision_evidence (
    assignment_review_decision_id uuid NOT NULL,
    evidence_item_id uuid NOT NULL,
    evidence_role provenance.evidence_role NOT NULL
);


--
-- Name: assignment_review_decision; Type: TABLE; Schema: provenance; Owner: -
--

CREATE TABLE provenance.assignment_review_decision (
    assignment_review_decision_id uuid NOT NULL,
    canonical_assignment_id uuid NOT NULL,
    outcome workflow.review_outcome NOT NULL,
    reviewer_actor text NOT NULL,
    rationale text NOT NULL,
    supersedes_decision_id uuid,
    decided_at timestamp with time zone NOT NULL,
    CONSTRAINT assignment_review_decision_rationale_check CHECK ((btrim(rationale) <> ''::text)),
    CONSTRAINT assignment_review_decision_reviewer_actor_check CHECK ((btrim(reviewer_actor) <> ''::text))
);


--
-- Name: research_launch_decision_snapshot_sha_v3(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_decision_snapshot_sha_v3(p_decision_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN release.canonical_jsonb_sha256(jsonb_build_object('decision', (SELECT jsonb_build_array(d.assignment_review_decision_id, d.canonical_assignment_id, d.outcome) AS jsonb_build_array FROM provenance.assignment_review_decision d WHERE (d.assignment_review_decision_id = research_launch_decision_snapshot_sha_v3.p_decision_id)), 'evidence', COALESCE((SELECT jsonb_agg(jsonb_build_array(e.evidence_item_id, e.evidence_role) ORDER BY e.evidence_item_id, e.evidence_role) AS jsonb_agg FROM provenance.assignment_decision_evidence e WHERE (e.assignment_review_decision_id = research_launch_decision_snapshot_sha_v3.p_decision_id)), '[]'::jsonb)));


--
-- Name: research_launch_decision_snapshot_sha_v4(uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_decision_snapshot_sha_v4(p_decision_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT encode(sha256(convert_to(jsonb_build_object(
    'decision',(SELECT jsonb_build_array(d.assignment_review_decision_id,d.canonical_assignment_id,d.outcome,d.supersedes_decision_id)
      FROM provenance.assignment_review_decision d WHERE d.assignment_review_decision_id=p_decision_id),
    'evidence',coalesce((SELECT jsonb_agg(jsonb_build_array(e.evidence_item_id,e.evidence_role)
      ORDER BY e.evidence_item_id,e.evidence_role) FROM provenance.assignment_decision_evidence e
      WHERE e.assignment_review_decision_id=p_decision_id),'[]'::jsonb)
  )::text,'UTF8')),'hex')::core.sha256_hex
$$;


--
-- Name: research_launch_publishable_folder_assignments_v4(uuid, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_publishable_folder_assignments_v4(p_migration_batch_id uuid, p_corpus_version_id uuid) RETURNS TABLE(folder_id uuid, archive_object_id uuid, source_assignment_id uuid, membership_role text, member_ordinal integer, effective_decision_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT fm.folder_id, fm.archive_object_id, a.canonical_assignment_id,
    fm.membership_role, fm.member_ordinal, d.assignment_review_decision_id
  FROM provenance.assignment_folder_membership fm
  JOIN provenance.canonical_assignment a
    ON a.canonical_assignment_id = fm.canonical_assignment_id
  JOIN raw.legacy_surface_ledger l
    ON l.archive_object_id = fm.archive_object_id
   AND l.migration_batch_id = p_migration_batch_id
   AND l.import_disposition = 'accounted'
  JOIN research.corpus_membership cm
    ON cm.archive_object_id = fm.archive_object_id
   AND cm.corpus_version_id = p_corpus_version_id
   AND cm.disposition = 'eligible'
  JOIN provenance.assignment_review_decision d
    ON d.canonical_assignment_id = a.canonical_assignment_id
   AND d.outcome = 'accept'
   AND NOT EXISTS (
     SELECT 1 FROM provenance.assignment_review_decision newer
      WHERE newer.supersedes_decision_id = d.assignment_review_decision_id
   )
   AND EXISTS (
     SELECT 1 FROM provenance.assignment_decision_evidence e
      WHERE e.assignment_review_decision_id = d.assignment_review_decision_id
        AND e.evidence_role = 'supports'
   )
  WHERE a.assignment_kind = 'folder_membership'
    AND a.status = 'accepted'
    AND a.supersedes_assignment_id IS NULL
$$;


--
-- Name: research_launch_publishable_folder_assignments_v5(uuid, uuid); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.research_launch_publishable_folder_assignments_v5(p_migration_batch_id uuid, p_corpus_version_id uuid) RETURNS TABLE(folder_id uuid, archive_object_id uuid, source_assignment_id uuid, membership_role text, member_ordinal integer, effective_decision_id uuid, assignment_snapshot_sha256 core.sha256_hex, decision_snapshot_sha256 core.sha256_hex)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  WITH current_assignment AS MATERIALIZED (
    SELECT a.canonical_assignment_id, a.assignment_kind, a.status,
      a.supersedes_assignment_id
    FROM provenance.canonical_assignment a
    WHERE a.assignment_kind='folder_membership'
      AND a.status='accepted'
      AND NOT EXISTS (
        SELECT 1 FROM provenance.canonical_assignment newer
        WHERE newer.supersedes_assignment_id=a.canonical_assignment_id
      )
  ), effective_decision AS MATERIALIZED (
    SELECT d.assignment_review_decision_id, d.canonical_assignment_id,
      encode(sha256(convert_to(jsonb_build_object(
        'decision',jsonb_build_array(d.assignment_review_decision_id,
          d.canonical_assignment_id,d.outcome,d.supersedes_decision_id),
        'supports',jsonb_agg(jsonb_build_array(e.evidence_item_id,e.evidence_role)
          ORDER BY e.evidence_item_id,e.evidence_role)
      )::text,'UTF8')),'hex')::core.sha256_hex AS decision_snapshot_sha256
    FROM provenance.assignment_review_decision d
    JOIN current_assignment a ON a.canonical_assignment_id=d.canonical_assignment_id
    JOIN provenance.assignment_decision_evidence e
      ON e.assignment_review_decision_id=d.assignment_review_decision_id
     AND e.evidence_role='supports'
    WHERE d.outcome='accept'
      AND NOT EXISTS (
        SELECT 1 FROM provenance.assignment_review_decision newer
        WHERE newer.supersedes_decision_id=d.assignment_review_decision_id
      )
    GROUP BY d.assignment_review_decision_id,d.canonical_assignment_id,
      d.outcome,d.supersedes_decision_id
  ), assignment_snapshot AS MATERIALIZED (
    SELECT a.canonical_assignment_id,
      encode(sha256(convert_to(jsonb_build_object(
        'assignment',jsonb_build_array(a.canonical_assignment_id,a.assignment_kind,
          a.status,a.supersedes_assignment_id),
        'memberships',jsonb_agg(jsonb_build_array(fm.folder_id,fm.archive_object_id,
          fm.membership_role,fm.member_ordinal)
          ORDER BY fm.folder_id,fm.membership_role,fm.member_ordinal,fm.archive_object_id)
      )::text,'UTF8')),'hex')::core.sha256_hex AS assignment_snapshot_sha256
    FROM current_assignment a
    JOIN provenance.assignment_folder_membership fm
      ON fm.canonical_assignment_id=a.canonical_assignment_id
    GROUP BY a.canonical_assignment_id,a.assignment_kind,a.status,a.supersedes_assignment_id
  )
  SELECT fm.folder_id,fm.archive_object_id,a.canonical_assignment_id,
    fm.membership_role,fm.member_ordinal,d.assignment_review_decision_id,
    s.assignment_snapshot_sha256,d.decision_snapshot_sha256
  FROM current_assignment a
  JOIN provenance.assignment_folder_membership fm
    ON fm.canonical_assignment_id=a.canonical_assignment_id
  JOIN effective_decision d ON d.canonical_assignment_id=a.canonical_assignment_id
  JOIN assignment_snapshot s ON s.canonical_assignment_id=a.canonical_assignment_id
  JOIN raw.legacy_surface_ledger l ON l.archive_object_id=fm.archive_object_id
    AND l.migration_batch_id=p_migration_batch_id AND l.import_disposition='accounted'
  JOIN research.corpus_membership cm ON cm.archive_object_id=fm.archive_object_id
    AND cm.corpus_version_id=p_corpus_version_id AND cm.disposition='eligible'
$$;


--
-- Name: seal_research_launch_snapshot_v3(uuid, uuid, uuid, core.sha256_hex); Type: FUNCTION; Schema: release; Owner: -
--

CREATE FUNCTION release.seal_research_launch_snapshot_v3(p_release_id uuid, p_seal_event_id uuid, p_release_event_id uuid, p_event_sha256 core.sha256_hex) RETURNS core.sha256_hex
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_bytes bytea; v_sha core.sha256_hex; v_fingerprint core.sha256_hex;
BEGIN
  PERFORM release.require_session_actor('gda_v49_phase2a_publisher');
  IF current_setting('transaction_isolation')<>'serializable' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='RESEARCH_LAUNCH_V3_SEAL_REQUIRES_SERIALIZABLE'; END IF;
  SELECT candidate_fingerprint INTO v_fingerprint FROM release.research_release WHERE research_release_id=p_release_id AND release_state='validated' FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM release.research_launch_validation_v3 WHERE research_release_id=p_release_id AND candidate_fingerprint=v_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='RESEARCH_LAUNCH_V3_PASS_RECEIPT_REQUIRED'; END IF;
  PERFORM release.validate_research_launch_snapshot_v3_integrity(p_release_id);
  v_bytes:=release.build_research_launch_manifest_bytes_v3(p_release_id); v_sha:=encode(sha256(v_bytes),'hex')::core.sha256_hex;
  INSERT INTO release.research_launch_manifest_v3 VALUES(p_release_id,v_bytes,v_sha,clock_timestamp());
  INSERT INTO release.research_release_manifest VALUES(p_release_id,v_bytes,v_sha,octet_length(v_bytes),clock_timestamp());
  UPDATE release.research_release SET release_state='sealed',manifest_sha256=v_sha,sealed_at=clock_timestamp() WHERE research_release_id=p_release_id;
  INSERT INTO audit.research_release_event VALUES(p_release_event_id,p_release_id,'validated','sealed',session_user::text,clock_timestamp(),p_event_sha256);
  INSERT INTO audit.research_seal_event(
    research_seal_event_id,research_release_id,manifest_sha256,actor,sealed_at,
    seal_transaction_id,candidate_fingerprint,seal_function_version
  ) VALUES(p_seal_event_id,p_release_id,v_sha,session_user::text,clock_timestamp(),
    txid_current(),v_fingerprint,'release-snapshot-v3');
  RETURN v_sha;
END
$$;


