    SELECT d.semantic_relation_id INTO v_id
    FROM research.relation_review_decision d
    WHERE d.relation_review_decision_id = (v_row ->> 'relation_review_decision_id')::uuid;
  END IF;
  PERFORM research.validate_one_semantic_relation(v_id);
  RETURN NULL;
END
$$;


--
-- Name: record_claim_review_decision(uuid, uuid, workflow.review_outcome, boolean, text, uuid, uuid[], provenance.evidence_role[]); Type: FUNCTION; Schema: research; Owner: -
--

CREATE FUNCTION research.record_claim_review_decision(p_decision_id uuid, p_claim_revision_id uuid, p_outcome workflow.review_outcome, p_heightened_review boolean, p_rationale text, p_supersedes_decision_id uuid, p_evidence_item_ids uuid[], p_evidence_roles provenance.evidence_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM rights.require_reviewer();
  IF p_supersedes_decision_id IS NULL THEN
    PERFORM 1
    FROM workflow.review_case c
    JOIN workflow.review_case_claim x USING (review_case_id)
    WHERE x.claim_revision_id = p_claim_revision_id
      AND c.queue_state IN ('claimed', 'in_review')
      AND c.claimed_by = session_user::text
    FOR UPDATE OF c;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'CLAIM_REVIEW_CASE_NOT_CLAIMED';
    END IF;
  END IF;
  PERFORM research.record_claim_review_decision_v1(
    p_decision_id, p_claim_revision_id, p_outcome,
    p_heightened_review, p_rationale, p_supersedes_decision_id,
    p_evidence_item_ids, p_evidence_roles);
  UPDATE workflow.review_case c
  SET queue_state = 'resolved', claimed_by = NULL, claimed_at = NULL,
    resolved_at = clock_timestamp()
  FROM workflow.review_case_claim x
  WHERE x.review_case_id = c.review_case_id
    AND x.claim_revision_id = p_claim_revision_id
    AND c.claimed_by = session_user::text;
END
$$;


--
-- Name: record_claim_review_decision_v1(uuid, uuid, workflow.review_outcome, boolean, text, uuid, uuid[], provenance.evidence_role[]); Type: FUNCTION; Schema: research; Owner: -
--

CREATE FUNCTION research.record_claim_review_decision_v1(p_decision_id uuid, p_claim_revision_id uuid, p_outcome workflow.review_outcome, p_heightened_review boolean, p_rationale text, p_supersedes_decision_id uuid, p_evidence_item_ids uuid[], p_evidence_roles provenance.evidence_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_index integer;
BEGIN
  PERFORM rights.require_reviewer();
  IF COALESCE(cardinality(p_evidence_item_ids), 0) = 0
    OR cardinality(p_evidence_item_ids) IS DISTINCT FROM cardinality(p_evidence_roles) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'CLAIM_REVIEW_EVIDENCE_SET_INVALID';
  END IF;
  IF p_supersedes_decision_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM research.claim_review_decision prior
    WHERE prior.claim_review_decision_id = p_supersedes_decision_id
      AND prior.claim_revision_id = p_claim_revision_id
      AND NOT EXISTS (
        SELECT 1 FROM research.claim_review_decision newer
        WHERE newer.supersedes_decision_id = prior.claim_review_decision_id)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '55000',
      MESSAGE = 'CLAIM_REVIEW_SUPERSEDES_NONCURRENT_DECISION';
  END IF;
  INSERT INTO research.claim_review_decision (
    claim_review_decision_id, claim_revision_id, outcome,
    heightened_review, reviewer_actor, rationale,
    supersedes_decision_id, decided_at
  ) VALUES (
    p_decision_id, p_claim_revision_id, p_outcome,
    p_heightened_review, session_user::text, p_rationale,
    p_supersedes_decision_id, clock_timestamp()
  );
  FOR v_index IN 1..cardinality(p_evidence_item_ids) LOOP
    INSERT INTO research.claim_decision_evidence VALUES (
      p_decision_id, p_evidence_item_ids[v_index], p_evidence_roles[v_index]);
  END LOOP;
  UPDATE research.claim_revision
  SET status = CASE p_outcome
      WHEN 'accept' THEN 'accepted'::research.claim_status
      WHEN 'reject' THEN 'rejected'::research.claim_status
      WHEN 'supersede' THEN 'superseded'::research.claim_status
      ELSE 'proposed'::research.claim_status END,
    workflow_state = 'resolved'
  WHERE claim_revision_id = p_claim_revision_id
    AND ((p_supersedes_decision_id IS NULL AND status IN ('draft', 'proposed'))
      OR (p_supersedes_decision_id IS NOT NULL AND status <> 'superseded'));
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '55000',
      MESSAGE = 'CLAIM_REVISION_NOT_REVIEWABLE';
  END IF;
  PERFORM audit.record_decision_event('claim_review', p_decision_id);
END
$$;


--
-- Name: record_relation_review_decision(uuid, uuid, workflow.review_outcome, text, uuid, uuid[], provenance.evidence_role[], uuid, core.sha256_hex); Type: FUNCTION; Schema: research; Owner: -
--

CREATE FUNCTION research.record_relation_review_decision(p_decision_id uuid, p_relation_id uuid, p_outcome workflow.review_outcome, p_rationale text, p_supersedes_decision_id uuid, p_evidence_item_ids uuid[], p_evidence_roles provenance.evidence_role[], p_audit_event_id uuid, p_audit_event_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM rights.require_reviewer();
  IF p_supersedes_decision_id IS NULL THEN
    PERFORM 1
    FROM workflow.review_case c
    JOIN workflow.review_case_relation x USING (review_case_id)
    WHERE x.semantic_relation_id = p_relation_id
      AND c.queue_state IN ('claimed', 'in_review')
      AND c.claimed_by = session_user::text
    FOR UPDATE OF c;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '55000',
        MESSAGE = 'RELATION_REVIEW_CASE_NOT_CLAIMED';
    END IF;
  END IF;
  PERFORM research.record_relation_review_decision_v1(
    p_decision_id, p_relation_id, p_outcome, p_rationale,
    p_supersedes_decision_id, p_evidence_item_ids, p_evidence_roles,
    p_audit_event_id, p_audit_event_sha256);
  UPDATE workflow.review_case c
  SET queue_state = 'resolved', claimed_by = NULL, claimed_at = NULL,
    resolved_at = clock_timestamp()
  FROM workflow.review_case_relation x
  WHERE x.review_case_id = c.review_case_id
    AND x.semantic_relation_id = p_relation_id
    AND c.claimed_by = session_user::text;
END
$$;


--
-- Name: record_relation_review_decision_v1(uuid, uuid, workflow.review_outcome, text, uuid, uuid[], provenance.evidence_role[], uuid, core.sha256_hex); Type: FUNCTION; Schema: research; Owner: -
--

CREATE FUNCTION research.record_relation_review_decision_v1(p_decision_id uuid, p_relation_id uuid, p_outcome workflow.review_outcome, p_rationale text, p_supersedes_decision_id uuid, p_evidence_item_ids uuid[], p_evidence_roles provenance.evidence_role[], p_audit_event_id uuid, p_audit_event_sha256 core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_index integer;
BEGIN
  PERFORM rights.require_reviewer();
  IF COALESCE(cardinality(p_evidence_item_ids), 0) = 0
    OR cardinality(p_evidence_item_ids) IS DISTINCT FROM cardinality(p_evidence_roles) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RELATION_REVIEW_EVIDENCE_SET_INVALID';
  END IF;
  IF p_supersedes_decision_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM research.relation_review_decision prior
    WHERE prior.relation_review_decision_id = p_supersedes_decision_id
      AND prior.semantic_relation_id = p_relation_id
      AND NOT EXISTS (
        SELECT 1 FROM research.relation_review_decision newer
        WHERE newer.supersedes_decision_id = prior.relation_review_decision_id)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '55000',
      MESSAGE = 'RELATION_REVIEW_SUPERSEDES_NONCURRENT_DECISION';
  END IF;
  INSERT INTO research.relation_review_decision (
    relation_review_decision_id, semantic_relation_id, outcome,
    reviewer_actor, reviewer_agent_id, rationale, supersedes_decision_id, decided_at
  ) VALUES (
    p_decision_id, p_relation_id, p_outcome, session_user::text,
    NULL, p_rationale, p_supersedes_decision_id, clock_timestamp()
  );
  FOR v_index IN 1..cardinality(p_evidence_item_ids) LOOP
    INSERT INTO research.relation_decision_evidence VALUES (
      p_decision_id, p_evidence_item_ids[v_index], p_evidence_roles[v_index]);
  END LOOP;
  UPDATE research.semantic_relation
  SET status = CASE p_outcome
      WHEN 'accept' THEN 'accepted'::research.relation_status
      WHEN 'reject' THEN 'rejected'::research.relation_status
      WHEN 'supersede' THEN 'superseded'::research.relation_status
      ELSE 'proposed'::research.relation_status END
  WHERE semantic_relation_id = p_relation_id
    AND ((p_supersedes_decision_id IS NULL AND status = 'proposed')
      OR (p_supersedes_decision_id IS NOT NULL AND status <> 'superseded'));
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '55000',
      MESSAGE = 'SEMANTIC_RELATION_NOT_REVIEWABLE';
  END IF;
  INSERT INTO audit.review_event VALUES (
    p_audit_event_id, p_decision_id, session_user::text,
    clock_timestamp(), p_audit_event_sha256
  );
  PERFORM audit.record_decision_event('relation_review', p_decision_id);
END
$$;


--
-- Name: validate_one_semantic_relation(uuid); Type: FUNCTION; Schema: research; Owner: -
--

CREATE FUNCTION research.validate_one_semantic_relation(p_relation_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_bad boolean;
BEGIN
  SELECT (
    NOT rt.active
    OR sr.origin = 'legacy_projection_only'
    OR se.entity_kind <> rt.subject_entity_kind
    OR oe.entity_kind <> rt.object_entity_kind
    OR NOT (
      EXISTS (
      SELECT 1 FROM research.relation_claim rc
      JOIN research.claim_revision cr ON cr.claim_revision_id = rc.claim_revision_id
      JOIN research.claim_evidence ce ON ce.claim_revision_id = cr.claim_revision_id
      WHERE rc.semantic_relation_id = sr.semantic_relation_id
        AND rc.claim_role = 'supports' AND cr.status = 'accepted'
        AND ce.evidence_role = 'supports'
      )
      OR EXISTS (
      SELECT 1 FROM research.relation_review_decision rd
      WHERE rd.semantic_relation_id = sr.semantic_relation_id AND rd.outcome = 'accept'
        AND NOT EXISTS (
          SELECT 1 FROM research.relation_review_decision newer
          WHERE newer.supersedes_decision_id = rd.relation_review_decision_id
        )
        AND EXISTS (
          SELECT 1 FROM research.relation_decision_evidence de
          WHERE de.relation_review_decision_id = rd.relation_review_decision_id
            AND de.evidence_role = 'supports'
        )
      )
    )
  ) INTO v_bad
  FROM research.semantic_relation sr
  JOIN research.relation_type rt ON rt.relation_type_id = sr.relation_type_id
  JOIN research.relation_endpoint_entity sre ON sre.relation_endpoint_id = sr.subject_endpoint_id
  JOIN core.entity se ON se.entity_id = sre.entity_id
  JOIN research.relation_endpoint_entity ore ON ore.relation_endpoint_id = sr.object_endpoint_id
  JOIN core.entity oe ON oe.entity_id = ore.entity_id
  WHERE sr.semantic_relation_id = p_relation_id AND sr.status = 'accepted';

  IF COALESCE(v_bad, false) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'ACCEPTED_RELATION_VALIDATION_FAILED';
  END IF;
END
$$;


--
-- Name: assessment_subject_key(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.assessment_subject_key(p_assessment_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_kind rights.rights_subject_kind; v_target uuid;
BEGIN
  SELECT a.subject_kind INTO v_kind FROM rights.rights_assessment a
  WHERE a.rights_assessment_id = p_assessment_id;
  IF v_kind = 'provider_object' THEN
    SELECT x.provider_object_id INTO v_target FROM rights.rights_assessment_provider_object x WHERE x.rights_assessment_id = p_assessment_id;
  ELSIF v_kind = 'external_visual_reference' THEN
    SELECT x.external_visual_reference_id INTO v_target FROM rights.rights_assessment_visual_reference x WHERE x.rights_assessment_id = p_assessment_id;
  ELSIF v_kind = 'digital_representation' THEN
    SELECT x.digital_representation_id INTO v_target FROM rights.rights_assessment_representation x WHERE x.rights_assessment_id = p_assessment_id;
  ELSIF v_kind = 'visual_locator' THEN
    SELECT x.visual_locator_id INTO v_target FROM rights.rights_assessment_locator x WHERE x.rights_assessment_id = p_assessment_id;
  END IF;
  RETURN v_kind::text || ':' || v_target::text;
END
$$;


