    value_ordinal integer NOT NULL,
    language_tag text,
    value_text text NOT NULL,
    CONSTRAINT attribution_bundle_value_value_kind_check CHECK ((value_kind = ANY (ARRAY['attribution'::text, 'required_statement'::text]))),
    CONSTRAINT attribution_bundle_value_value_ordinal_check CHECK ((value_ordinal >= 0)),
    CONSTRAINT attribution_bundle_value_value_text_check CHECK ((btrim(value_text) <> ''::text))
);


--
-- Name: compute_attribution_bundle_sha(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.compute_attribution_bundle_sha(p_bundle_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN (SELECT release.canonical_jsonb_sha256(jsonb_build_object('bridgeId', a.object_visual_reference_id, 'bundleId', a.attribution_bundle_id, 'evidenceId', a.evidence_item_id, 'state', a.attribution_state, 'supersedesBundleId', a.supersedes_attribution_bundle_id, 'validatedAtUs', ((EXTRACT(epoch FROM a.validated_at) * (1000000)::numeric))::bigint, 'validatedBy', a.validated_by, 'values', COALESCE((SELECT jsonb_agg(jsonb_build_array(v.value_kind, v.value_ordinal, v.language_tag, v.value_text) ORDER BY v.value_kind, v.value_ordinal) AS jsonb_agg FROM rights.attribution_bundle_value v WHERE (v.attribution_bundle_id = a.attribution_bundle_id)), '[]'::jsonb))) AS canonical_jsonb_sha256 FROM rights.attribution_bundle a WHERE (a.attribution_bundle_id = compute_attribution_bundle_sha.p_bundle_id));


