--
-- Name: compute_provider_policy_evaluation_sha(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.compute_provider_policy_evaluation_sha(p_evaluation_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN (SELECT release.canonical_jsonb_sha256(jsonb_build_object('bridgeId', e.object_visual_reference_id, 'evaluatedAtUs', ((EXTRACT(epoch FROM e.evaluated_at) * (1000000)::numeric))::bigint, 'evaluationId', e.provider_policy_evaluation_id, 'evaluator', e.evaluator_actor, 'state', e.evaluated_state, 'versions', COALESCE((SELECT jsonb_agg(jsonb_build_object('effectiveFromUs', ((EXTRACT(epoch FROM pv.effective_from) * (1000000)::numeric))::bigint, 'effectiveUntilUs', CASE WHEN (pv.effective_until IS NULL) THEN NULL::bigint ELSE ((EXTRACT(epoch FROM pv.effective_until) * (1000000)::numeric))::bigint END, 'policyScopeId', pv.policy_scope_id, 'policySha256', pv.policy_sha256, 'policyState', pv.policy_state, 'providerId', pv.provider_id, 'reviewDueUs', ((EXTRACT(epoch FROM pv.review_due) * (1000000)::numeric))::bigint, 'sourceEvidence', to_jsonb(ei.*), 'sourceEvidenceId', pv.source_evidence_item_id, 'versionId', pv.provider_policy_version_id, 'versionToken', pv.version_token) ORDER BY pv.provider_policy_version_id) AS jsonb_agg FROM ((rights.provider_policy_evaluation_version x JOIN rights.provider_policy_version pv ON ((pv.provider_policy_version_id = x.provider_policy_version_id))) JOIN provenance.evidence_item ei ON ((ei.evidence_item_id = pv.source_evidence_item_id))) WHERE (x.provider_policy_evaluation_id = e.provider_policy_evaluation_id)), '[]'::jsonb))) AS canonical_jsonb_sha256 FROM rights.provider_policy_evaluation e WHERE (e.provider_policy_evaluation_id = compute_provider_policy_evaluation_sha.p_evaluation_id));


