    RETURN release.canonical_jsonb_sha256(COALESCE((SELECT jsonb_agg(jsonb_build_array(x.provider_policy_evaluation_id, rights.compute_provider_policy_evaluation_sha(x.provider_policy_evaluation_id)) ORDER BY x.provider_policy_evaluation_id) AS jsonb_agg FROM rights.delivery_policy_evaluation x WHERE (x.delivery_assessment_id = compute_delivery_policy_sha.p_delivery_id)), '[]'::jsonb));


