--
-- Name: compute_rights_observation_sha(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.compute_rights_observation_sha(p_observation_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN (SELECT release.canonical_jsonb_sha256(jsonb_build_object('evidence', CASE WHEN (ei.evidence_item_id IS NULL) THEN NULL::jsonb ELSE to_jsonb(ei.*) END, 'evidenceId', o.evidence_item_id, 'observationId', o.rights_observation_id, 'observedAtUs', ((EXTRACT(epoch FROM o.observed_at) * (1000000)::numeric))::bigint, 'state', o.evidence_state, 'subjectKey', rights.observation_subject_key(o.rights_observation_id), 'subjectKind', o.subject_kind, 'wording', o.observed_wording)) AS canonical_jsonb_sha256 FROM (rights.rights_observation o LEFT JOIN provenance.evidence_item ei ON ((ei.evidence_item_id = o.evidence_item_id))) WHERE (o.rights_observation_id = compute_rights_observation_sha.p_observation_id));


