CREATE FUNCTION rights.compute_rights_assessment_sha(p_assessment_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN (SELECT release.canonical_jsonb_sha256(jsonb_build_object('assessedAtUs', ((EXTRACT(epoch FROM a.assessed_at) * (1000000)::numeric))::bigint, 'assessmentId', a.rights_assessment_id, 'observations', COALESCE((SELECT jsonb_agg(jsonb_build_object('observationId', x.rights_observation_id, 'observationSha256', rights.compute_rights_observation_sha(x.rights_observation_id), 'role', x.evidence_role) ORDER BY x.rights_observation_id, x.evidence_role) AS jsonb_agg FROM rights.rights_assessment_observation x WHERE (x.rights_assessment_id = a.rights_assessment_id)), '[]'::jsonb), 'rationale', a.rationale, 'reviewer', a.reviewer_actor, 'state', a.assessed_state, 'subjectKey', rights.assessment_subject_key(a.rights_assessment_id), 'subjectKind', a.subject_kind)) AS canonical_jsonb_sha256 FROM rights.rights_assessment a WHERE (a.rights_assessment_id = compute_rights_assessment_sha.p_assessment_id));


