CREATE FUNCTION rights.compute_delivery_snapshot_sha(p_delivery_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN (SELECT release.canonical_jsonb_sha256(jsonb_build_object('assessedAtUs', ((EXTRACT(epoch FROM d.assessed_at) * (1000000)::numeric))::bigint, 'assessor', d.assessor_actor, 'attributionBundleId', d.attribution_bundle_id, 'attributionSha256', CASE WHEN (d.attribution_bundle_id IS NULL) THEN NULL::text ELSE (rights.compute_attribution_bundle_sha(d.attribution_bundle_id))::text END, 'bridgeId', d.object_visual_reference_id, 'deliveryId', d.delivery_assessment_id, 'machineReasonCode', d.machine_reason_code, 'mode', d.delivery_mode, 'policySha256', rights.compute_delivery_policy_sha(d.delivery_assessment_id), 'qualifications', COALESCE((SELECT jsonb_agg(jsonb_build_array(q.visual_locator_id, q.endpoint_health_observation_id, q.allowlisted_role, rights.compute_health_observation_sha(q.endpoint_health_observation_id)) ORDER BY q.allowlisted_role, q.visual_locator_id) AS jsonb_agg FROM rights.delivery_locator_qualification q WHERE (q.delivery_assessment_id = d.delivery_assessment_id)), '[]'::jsonb), 'reasonCode', d.reason_code, 'rightsSha256', rights.compute_delivery_rights_sha(d.delivery_assessment_id))) AS canonical_jsonb_sha256 FROM rights.delivery_assessment d WHERE (d.delivery_assessment_id = compute_delivery_snapshot_sha.p_delivery_id));


