CREATE FUNCTION rights.takedown_scope_target_key(p_scope_id uuid) RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    RETURN (SELECT COALESCE(p.provider_id, po.provider_object_id, vr.external_visual_reference_id, dr.digital_representation_id, vl.visual_locator_id, ov.object_visual_reference_id) AS "coalesce" FROM ((((((rights.takedown_scope s LEFT JOIN rights.takedown_scope_provider p ON ((p.takedown_scope_id = s.takedown_scope_id))) LEFT JOIN rights.takedown_scope_provider_object po ON ((po.takedown_scope_id = s.takedown_scope_id))) LEFT JOIN rights.takedown_scope_visual_reference vr ON ((vr.takedown_scope_id = s.takedown_scope_id))) LEFT JOIN rights.takedown_scope_representation dr ON ((dr.takedown_scope_id = s.takedown_scope_id))) LEFT JOIN rights.takedown_scope_locator vl ON ((vl.takedown_scope_id = s.takedown_scope_id))) LEFT JOIN rights.takedown_scope_object_visual_reference ov ON ((ov.takedown_scope_id = s.takedown_scope_id))) WHERE (s.takedown_scope_id = takedown_scope_target_key.p_scope_id));


--
-- Name: takedown_event; Type: TABLE; Schema: rights; Owner: -
--

CREATE TABLE rights.takedown_event (
    takedown_event_id uuid NOT NULL,
    action rights.takedown_action NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_until timestamp with time zone,
    reason_code text NOT NULL,
    evidence_item_id uuid NOT NULL,
    recorded_by text NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT takedown_event_check CHECK (((effective_until IS NULL) OR (effective_until > effective_from))),
    CONSTRAINT takedown_event_reason_code_check CHECK ((btrim(reason_code) <> ''::text)),
    CONSTRAINT takedown_event_recorded_by_check CHECK ((btrim(recorded_by) <> ''::text))
);


--
-- Name: takedown_override; Type: TABLE; Schema: rights; Owner: -
--

CREATE TABLE rights.takedown_override (
    takedown_override_id uuid NOT NULL,
    takedown_scope_id uuid NOT NULL,
    restrictive_mode rights.delivery_mode NOT NULL,
    overlay_sha256 core.sha256_hex NOT NULL,
    supersedes_takedown_override_id uuid,
    created_at timestamp with time zone NOT NULL,
    override_version integer NOT NULL,
    CONSTRAINT takedown_override_override_version_check CHECK ((override_version > 0)),
    CONSTRAINT takedown_override_restrictive_mode_check CHECK ((restrictive_mode = ANY (ARRAY['blocked'::rights.delivery_mode, 'citation_only'::rights.delivery_mode])))
);


--
-- Name: compute_takedown_override_sha(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.compute_takedown_override_sha(p_override_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN (SELECT release.canonical_jsonb_sha256(jsonb_build_object('action', e.action, 'createdAtUs', ((EXTRACT(epoch FROM o.created_at) * (1000000)::numeric))::bigint, 'effectiveFromUs', ((EXTRACT(epoch FROM e.effective_from) * (1000000)::numeric))::bigint, 'effectiveUntilUs', CASE WHEN (e.effective_until IS NULL) THEN NULL::bigint ELSE ((EXTRACT(epoch FROM e.effective_until) * (1000000)::numeric))::bigint END, 'eventId', e.takedown_event_id, 'evidenceId', e.evidence_item_id, 'overrideId', o.takedown_override_id, 'overrideVersion', o.override_version, 'reasonCode', e.reason_code, 'restrictiveMode', o.restrictive_mode, 'scopeId', s.takedown_scope_id, 'scopeKind', s.scope_kind, 'scopeOrdinal', s.scope_ordinal, 'scopeTarget', rights.takedown_scope_target_key(s.takedown_scope_id), 'supersedesOverrideId', o.supersedes_takedown_override_id)) AS canonical_jsonb_sha256 FROM ((rights.takedown_override o JOIN rights.takedown_scope s ON ((s.takedown_scope_id = o.takedown_scope_id))) JOIN rights.takedown_event e ON ((e.takedown_event_id = s.takedown_event_id))) WHERE (o.takedown_override_id = compute_takedown_override_sha.p_override_id));


--
-- Name: delivery_mode_for_rule(rights.delivery_rule_id); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.delivery_mode_for_rule(p_rule rights.delivery_rule_id) RETURNS rights.delivery_mode
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    RETURN CASE p_rule WHEN 'RD-001'::rights.delivery_rule_id THEN 'blocked'::rights.delivery_mode WHEN 'RD-002'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode WHEN 'RD-010'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode WHEN 'RD-011'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode WHEN 'RD-020'::rights.delivery_rule_id THEN 'link_only'::rights.delivery_mode WHEN 'RD-021'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode WHEN 'RD-030'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode WHEN 'RD-040'::rights.delivery_rule_id THEN 'link_only'::rights.delivery_mode WHEN 'RD-041'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode WHEN 'RD-050'::rights.delivery_rule_id THEN 'source_viewer'::rights.delivery_mode WHEN 'RD-051'::rights.delivery_rule_id THEN 'link_only'::rights.delivery_mode WHEN 'RD-052'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode WHEN 'RD-060'::rights.delivery_rule_id THEN 'link_only'::rights.delivery_mode WHEN 'RD-061'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode WHEN 'RD-070'::rights.delivery_rule_id THEN 'link_only'::rights.delivery_mode WHEN 'RD-071'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode WHEN 'RD-080'::rights.delivery_rule_id THEN 'remote_image'::rights.delivery_mode WHEN 'RD-081'::rights.delivery_rule_id THEN 'link_only'::rights.delivery_mode WHEN 'RD-082'::rights.delivery_rule_id THEN 'citation_only'::rights.delivery_mode ELSE 'citation_only'::rights.delivery_mode END;


--
-- Name: delivery_rank(rights.delivery_mode); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.delivery_rank(p_mode rights.delivery_mode) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    RETURN CASE p_mode WHEN 'remote_image'::rights.delivery_mode THEN 4 WHEN 'source_viewer'::rights.delivery_mode THEN 3 WHEN 'link_only'::rights.delivery_mode THEN 2 WHEN 'citation_only'::rights.delivery_mode THEN 1 WHEN 'blocked'::rights.delivery_mode THEN 0 ELSE NULL::integer END;


