--
-- Name: enforce_rights_assessment(); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.enforce_rights_assessment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := COALESCE(to_jsonb(NEW), to_jsonb(OLD));
  v_id uuid := (v_row ->> 'rights_assessment_id')::uuid;
  v_kind rights.rights_subject_kind;
  v_state rights.rights_evidence_state;
  v_count integer;
  v_assessed_at timestamptz;
BEGIN
  SELECT a.subject_kind, a.assessed_state, a.assessed_at
  INTO v_kind, v_state, v_assessed_at
  FROM rights.rights_assessment a WHERE a.rights_assessment_id = v_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_assessed_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_RIGHTS_ASSESSMENT_DENIED';
  END IF;
  SELECT
      (SELECT count(*) FROM rights.rights_assessment_provider_object x WHERE x.rights_assessment_id = v_id)
    + (SELECT count(*) FROM rights.rights_assessment_visual_reference x WHERE x.rights_assessment_id = v_id)
    + (SELECT count(*) FROM rights.rights_assessment_representation x WHERE x.rights_assessment_id = v_id)
    + (SELECT count(*) FROM rights.rights_assessment_locator x WHERE x.rights_assessment_id = v_id)
  INTO v_count;
  IF v_count <> 1 OR NOT (CASE v_kind
    WHEN 'provider_object' THEN EXISTS (SELECT 1 FROM rights.rights_assessment_provider_object x WHERE x.rights_assessment_id = v_id)
    WHEN 'external_visual_reference' THEN EXISTS (SELECT 1 FROM rights.rights_assessment_visual_reference x WHERE x.rights_assessment_id = v_id)
    WHEN 'digital_representation' THEN EXISTS (SELECT 1 FROM rights.rights_assessment_representation x WHERE x.rights_assessment_id = v_id)
    WHEN 'visual_locator' THEN EXISTS (SELECT 1 FROM rights.rights_assessment_locator x WHERE x.rights_assessment_id = v_id)
    ELSE false
  END) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RIGHTS_ASSESSMENT_EXACTLY_ONE_TYPED_SUBJECT_REQUIRED';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM rights.rights_assessment_observation x
    WHERE x.rights_assessment_id = v_id
  ) OR EXISTS (
    SELECT 1 FROM rights.rights_assessment_observation x
    JOIN rights.rights_observation o
      ON o.rights_observation_id = x.rights_observation_id
    WHERE x.rights_assessment_id = v_id
      AND (
        rights.observation_subject_key(x.rights_observation_id)
          IS DISTINCT FROM rights.assessment_subject_key(v_id)
        OR o.observed_at > (
          SELECT a.assessed_at FROM rights.rights_assessment a
          WHERE a.rights_assessment_id = v_id
        )
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RIGHTS_ASSESSMENT_REQUIRES_MATCHING_OBSERVATION';
  END IF;
  IF v_state = 'permitted' AND NOT EXISTS (
    SELECT 1 FROM rights.rights_assessment_observation x
    JOIN rights.rights_observation o
      ON o.rights_observation_id = x.rights_observation_id
    WHERE x.rights_assessment_id = v_id
      AND x.evidence_role = 'supports'
      AND o.evidence_state = 'permitted'
      AND o.evidence_item_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'PERMITTED_RIGHTS_REQUIRES_EVIDENCE_OBSERVATION';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_rights_observation_shape(); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.enforce_rights_observation_shape() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := COALESCE(to_jsonb(NEW), to_jsonb(OLD));
  v_id uuid := (v_row ->> 'rights_observation_id')::uuid;
  v_kind rights.rights_subject_kind;
  v_count integer;
  v_observed_at timestamptz;
BEGIN
  SELECT o.subject_kind, o.observed_at INTO v_kind, v_observed_at
  FROM rights.rights_observation o WHERE o.rights_observation_id = v_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_observed_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_RIGHTS_OBSERVATION_DENIED';
  END IF;
  SELECT
      (SELECT count(*) FROM rights.rights_observation_provider_object x WHERE x.rights_observation_id = v_id)
    + (SELECT count(*) FROM rights.rights_observation_visual_reference x WHERE x.rights_observation_id = v_id)
    + (SELECT count(*) FROM rights.rights_observation_representation x WHERE x.rights_observation_id = v_id)
    + (SELECT count(*) FROM rights.rights_observation_locator x WHERE x.rights_observation_id = v_id)
  INTO v_count;
  IF v_count <> 1 OR NOT (CASE v_kind
    WHEN 'provider_object' THEN EXISTS (SELECT 1 FROM rights.rights_observation_provider_object x WHERE x.rights_observation_id = v_id)
    WHEN 'external_visual_reference' THEN EXISTS (SELECT 1 FROM rights.rights_observation_visual_reference x WHERE x.rights_observation_id = v_id)
    WHEN 'digital_representation' THEN EXISTS (SELECT 1 FROM rights.rights_observation_representation x WHERE x.rights_observation_id = v_id)
    WHEN 'visual_locator' THEN EXISTS (SELECT 1 FROM rights.rights_observation_locator x WHERE x.rights_observation_id = v_id)
    ELSE false
  END) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RIGHTS_OBSERVATION_EXACTLY_ONE_TYPED_SUBJECT_REQUIRED';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_rights_supersession_parent(); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.enforce_rights_supersession_parent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := pg_catalog.to_jsonb(NEW);
BEGIN
  IF TG_TABLE_NAME = 'rights_observation'
    AND v_row->>'supersedes_rights_observation_id' IS NOT NULL
    AND rights.observation_subject_key((v_row->>'supersedes_rights_observation_id')::uuid)
      IS DISTINCT FROM rights.observation_subject_key((v_row->>'rights_observation_id')::uuid) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'RIGHTS_OBSERVATION_SUPERSESSION_SUBJECT_MISMATCH';
  ELSIF TG_TABLE_NAME = 'rights_assessment'
    AND v_row->>'supersedes_rights_assessment_id' IS NOT NULL
    AND rights.assessment_subject_key((v_row->>'supersedes_rights_assessment_id')::uuid)
      IS DISTINCT FROM rights.assessment_subject_key((v_row->>'rights_assessment_id')::uuid) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'RIGHTS_ASSESSMENT_SUPERSESSION_SUBJECT_MISMATCH';
  ELSIF TG_TABLE_NAME = 'provider_policy_evaluation'
    AND v_row->>'supersedes_provider_policy_evaluation_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM rights.provider_policy_evaluation prior
      WHERE prior.provider_policy_evaluation_id = (v_row->>'supersedes_provider_policy_evaluation_id')::uuid
        AND prior.object_visual_reference_id = (v_row->>'object_visual_reference_id')::uuid
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'POLICY_EVALUATION_SUPERSESSION_BRIDGE_MISMATCH';
  ELSIF TG_TABLE_NAME = 'delivery_assessment'
    AND v_row->>'supersedes_delivery_assessment_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM rights.delivery_assessment prior
      WHERE prior.delivery_assessment_id = (v_row->>'supersedes_delivery_assessment_id')::uuid
        AND prior.object_visual_reference_id = (v_row->>'object_visual_reference_id')::uuid
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'DELIVERY_SUPERSESSION_BRIDGE_MISMATCH';
  ELSIF TG_TABLE_NAME = 'visual_locator'
    AND v_row->>'supersedes_visual_locator_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM rights.visual_locator prior
      WHERE prior.visual_locator_id = (v_row->>'supersedes_visual_locator_id')::uuid
        AND prior.external_visual_reference_id = (v_row->>'external_visual_reference_id')::uuid
        AND prior.locator_role::text = v_row->>'locator_role'
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'LOCATOR_SUPERSESSION_REFERENCE_ROLE_MISMATCH';
  ELSIF TG_TABLE_NAME = 'takedown_override'
    AND v_row->>'supersedes_takedown_override_id' IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM rights.takedown_override prior
      WHERE prior.takedown_override_id = (v_row->>'supersedes_takedown_override_id')::uuid
        AND prior.takedown_scope_id = (v_row->>'takedown_scope_id')::uuid
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TAKEDOWN_OVERRIDE_SUPERSESSION_SCOPE_MISMATCH';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_takedown_event_scope(); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.enforce_takedown_event_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := COALESCE(to_jsonb(NEW), to_jsonb(OLD));
  v_event_id uuid := (v_row ->> 'takedown_event_id')::uuid;
BEGIN
  IF EXISTS (
    SELECT 1 FROM rights.takedown_event e
    WHERE e.takedown_event_id = v_event_id
      AND NOT EXISTS (
        SELECT 1 FROM rights.takedown_scope s
        WHERE s.takedown_event_id = e.takedown_event_id
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TAKEDOWN_EVENT_REQUIRES_ONE_OR_MORE_SCOPES';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_takedown_override(); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.enforce_takedown_override() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := COALESCE(to_jsonb(NEW), to_jsonb(OLD));
  v_id uuid := (v_row ->> 'takedown_override_id')::uuid;
BEGIN
  IF EXISTS (
    SELECT 1
    FROM rights.takedown_override o
    JOIN rights.takedown_scope s ON s.takedown_scope_id = o.takedown_scope_id
    JOIN rights.takedown_event e ON e.takedown_event_id = s.takedown_event_id
    WHERE o.takedown_override_id = v_id
      AND e.action = 'blocked' AND o.restrictive_mode <> 'blocked'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TAKEDOWN_OVERRIDE_CANNOT_WEAKEN_EVENT';
  END IF;
  IF EXISTS (
    SELECT 1 FROM rights.takedown_override o
    JOIN rights.takedown_override p
      ON p.takedown_override_id = o.supersedes_takedown_override_id
    WHERE o.takedown_override_id = v_id
      AND (o.takedown_scope_id IS DISTINCT FROM p.takedown_scope_id
        OR rights.delivery_rank(o.restrictive_mode)
          > rights.delivery_rank(p.restrictive_mode))
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TAKEDOWN_OVERRIDE_SUPERSESSION_CANNOT_REPARENT_OR_WEAKEN';
  END IF;
  IF EXISTS (
    SELECT 1 FROM rights.takedown_override o
    WHERE o.takedown_override_id = v_id
      AND o.overlay_sha256 IS DISTINCT FROM
        rights.compute_takedown_override_sha(o.takedown_override_id)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TAKEDOWN_OVERRIDE_DIGEST_MISMATCH';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: enforce_takedown_scope_shape(); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.enforce_takedown_scope_shape() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_row jsonb := COALESCE(to_jsonb(NEW), to_jsonb(OLD));
  v_id uuid := (v_row ->> 'takedown_scope_id')::uuid;
  v_kind rights.takedown_scope_kind;
  v_count integer;
BEGIN
  SELECT s.scope_kind INTO v_kind FROM rights.takedown_scope s
  WHERE s.takedown_scope_id = v_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT
      (SELECT count(*) FROM rights.takedown_scope_provider x WHERE x.takedown_scope_id = v_id)
    + (SELECT count(*) FROM rights.takedown_scope_provider_object x WHERE x.takedown_scope_id = v_id)
    + (SELECT count(*) FROM rights.takedown_scope_visual_reference x WHERE x.takedown_scope_id = v_id)
    + (SELECT count(*) FROM rights.takedown_scope_representation x WHERE x.takedown_scope_id = v_id)
    + (SELECT count(*) FROM rights.takedown_scope_locator x WHERE x.takedown_scope_id = v_id)
    + (SELECT count(*) FROM rights.takedown_scope_object_visual_reference x WHERE x.takedown_scope_id = v_id)
  INTO v_count;
  IF v_count <> 1 OR NOT (CASE v_kind
    WHEN 'provider' THEN EXISTS (SELECT 1 FROM rights.takedown_scope_provider x WHERE x.takedown_scope_id = v_id)
    WHEN 'provider_object' THEN EXISTS (SELECT 1 FROM rights.takedown_scope_provider_object x WHERE x.takedown_scope_id = v_id)
    WHEN 'external_visual_reference' THEN EXISTS (SELECT 1 FROM rights.takedown_scope_visual_reference x WHERE x.takedown_scope_id = v_id)
    WHEN 'digital_representation' THEN EXISTS (SELECT 1 FROM rights.takedown_scope_representation x WHERE x.takedown_scope_id = v_id)
    WHEN 'visual_locator' THEN EXISTS (SELECT 1 FROM rights.takedown_scope_locator x WHERE x.takedown_scope_id = v_id)
    WHEN 'object_visual_reference' THEN EXISTS (SELECT 1 FROM rights.takedown_scope_object_visual_reference x WHERE x.takedown_scope_id = v_id)
    ELSE false
  END) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TAKEDOWN_SCOPE_EXACTLY_ONE_TYPED_TARGET_REQUIRED';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM rights.takedown_override o
    WHERE o.takedown_scope_id = v_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TAKEDOWN_SCOPE_REQUIRES_RESTRICTIVE_OVERRIDE';
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: insert_takedown_scope(uuid, uuid, integer, rights.takedown_scope_kind, uuid, uuid, integer, rights.delivery_mode, uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.insert_takedown_scope(p_event_id uuid, p_scope_id uuid, p_scope_ordinal integer, p_scope_kind rights.takedown_scope_kind, p_subject_id uuid, p_override_id uuid, p_override_version integer, p_restrictive_mode rights.delivery_mode, p_supersedes_override_id uuid) RETURNS core.sha256_hex
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_created_at timestamptz := clock_timestamp();
  v_overlay_sha256 core.sha256_hex;
  v_event rights.takedown_event%ROWTYPE;
BEGIN
  INSERT INTO rights.takedown_scope (
    takedown_scope_id, takedown_event_id, scope_kind, scope_ordinal
  ) VALUES (p_scope_id, p_event_id, p_scope_kind, p_scope_ordinal);
  CASE p_scope_kind
    WHEN 'provider' THEN
      INSERT INTO rights.takedown_scope_provider VALUES (
        p_scope_id, p_subject_id);
    WHEN 'provider_object' THEN
      INSERT INTO rights.takedown_scope_provider_object VALUES (
        p_scope_id, p_subject_id);
    WHEN 'external_visual_reference' THEN
      INSERT INTO rights.takedown_scope_visual_reference VALUES (
        p_scope_id, p_subject_id);
    WHEN 'digital_representation' THEN
      INSERT INTO rights.takedown_scope_representation VALUES (
        p_scope_id, p_subject_id);
    WHEN 'visual_locator' THEN
      INSERT INTO rights.takedown_scope_locator VALUES (
        p_scope_id, p_subject_id);
    WHEN 'object_visual_reference' THEN
      INSERT INTO rights.takedown_scope_object_visual_reference VALUES (
        p_scope_id, p_subject_id);
  END CASE;
  SELECT * INTO STRICT v_event
  FROM rights.takedown_event e
  WHERE e.takedown_event_id = p_event_id;
  v_overlay_sha256 := release.canonical_jsonb_sha256(jsonb_build_object(
    'action', v_event.action,
    'createdAtUs', (extract(epoch FROM v_created_at) * 1000000)::bigint,
    'effectiveFromUs',
      (extract(epoch FROM v_event.effective_from) * 1000000)::bigint,
    'effectiveUntilUs', CASE WHEN v_event.effective_until IS NULL THEN NULL
      ELSE (extract(epoch FROM v_event.effective_until) * 1000000)::bigint END,
    'eventId', p_event_id,
    'evidenceId', v_event.evidence_item_id,
    'overrideId', p_override_id,
    'overrideVersion', p_override_version,
    'reasonCode', v_event.reason_code,
    'restrictiveMode', p_restrictive_mode,
    'scopeId', p_scope_id,
    'scopeKind', p_scope_kind,
    'scopeOrdinal', p_scope_ordinal,
    'scopeTarget', p_subject_id,
    'supersedesOverrideId', p_supersedes_override_id
  ));
  INSERT INTO rights.takedown_override (
    takedown_override_id, takedown_scope_id, restrictive_mode,
    overlay_sha256, supersedes_takedown_override_id, created_at,
    override_version
  ) VALUES (
    p_override_id, p_scope_id, p_restrictive_mode,
    v_overlay_sha256, p_supersedes_override_id, v_created_at,
    p_override_version
  );
  RETURN v_overlay_sha256;
END
$$;


--
-- Name: machine_reason_for_rule(rights.delivery_rule_id); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.machine_reason_for_rule(p_rule rights.delivery_rule_id) RETURNS rights.delivery_reason_code
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    RETURN CASE p_rule WHEN 'RD-001'::rights.delivery_rule_id THEN 'ACTIVE_TAKEDOWN_BLOCK'::rights.delivery_reason_code WHEN 'RD-002'::rights.delivery_rule_id THEN 'ACTIVE_TAKEDOWN_CITATION_ONLY'::rights.delivery_reason_code WHEN 'RD-010'::rights.delivery_rule_id THEN 'RIGHTS_PROHIBIT_LOCATOR'::rights.delivery_reason_code WHEN 'RD-011'::rights.delivery_rule_id THEN 'POLICY_PROHIBITS_PUBLIC_LOCATOR'::rights.delivery_reason_code WHEN 'RD-020'::rights.delivery_rule_id THEN 'RIGHTS_FAIL_CLOSED_LINK'::rights.delivery_reason_code WHEN 'RD-021'::rights.delivery_rule_id THEN 'RIGHTS_FAIL_CLOSED_CITATION'::rights.delivery_reason_code WHEN 'RD-030'::rights.delivery_rule_id THEN 'POLICY_FAIL_CLOSED_CITATION'::rights.delivery_reason_code WHEN 'RD-040'::rights.delivery_rule_id THEN 'RIGHTS_CAP_LINK_ONLY'::rights.delivery_reason_code WHEN 'RD-041'::rights.delivery_rule_id THEN 'LINK_ENDPOINT_UNQUALIFIED'::rights.delivery_reason_code WHEN 'RD-050'::rights.delivery_rule_id THEN 'POLICY_CAP_SOURCE_VIEWER'::rights.delivery_reason_code WHEN 'RD-051'::rights.delivery_rule_id THEN 'VIEWER_ENDPOINT_DOWNGRADE_LINK'::rights.delivery_reason_code WHEN 'RD-052'::rights.delivery_rule_id THEN 'VIEWER_ENDPOINT_DOWNGRADE_CITATION'::rights.delivery_reason_code WHEN 'RD-060'::rights.delivery_rule_id THEN 'POLICY_CAP_LINK_ONLY'::rights.delivery_reason_code WHEN 'RD-061'::rights.delivery_rule_id THEN 'POLICY_LINK_UNAVAILABLE'::rights.delivery_reason_code WHEN 'RD-070'::rights.delivery_rule_id THEN 'ATTRIBUTION_FAIL_CLOSED_LINK'::rights.delivery_reason_code WHEN 'RD-071'::rights.delivery_rule_id THEN 'ATTRIBUTION_FAIL_CLOSED_CITATION'::rights.delivery_reason_code WHEN 'RD-080'::rights.delivery_rule_id THEN 'REMOTE_IMAGE_ALL_GATES_PASS'::rights.delivery_reason_code WHEN 'RD-081'::rights.delivery_rule_id THEN 'REMOTE_ENDPOINT_DOWNGRADE_LINK'::rights.delivery_reason_code WHEN 'RD-082'::rights.delivery_rule_id THEN 'REMOTE_ENDPOINT_DOWNGRADE_CITATION'::rights.delivery_reason_code ELSE 'FAIL_CLOSED_DEFAULT'::rights.delivery_reason_code END;


--
-- Name: object_visual_reference_review_decision; Type: TABLE; Schema: rights; Owner: -
--

CREATE TABLE rights.object_visual_reference_review_decision (
    object_visual_reference_review_decision_id uuid NOT NULL,
    object_visual_reference_id uuid NOT NULL,
    outcome workflow.review_outcome NOT NULL,
    evidence_item_id uuid NOT NULL,
    reviewer_actor text NOT NULL,
    rationale text NOT NULL,
    supersedes_decision_id uuid,
    decided_at timestamp with time zone NOT NULL,
    CONSTRAINT object_visual_reference_review_decision_outcome_check CHECK ((outcome = ANY (ARRAY['accept'::workflow.review_outcome, 'hold'::workflow.review_outcome, 'reject'::workflow.review_outcome, 'supersede'::workflow.review_outcome]))),
    CONSTRAINT object_visual_reference_review_decision_rationale_check CHECK ((btrim(rationale) <> ''::text)),
    CONSTRAINT object_visual_reference_review_decision_reviewer_actor_check CHECK ((btrim(reviewer_actor) <> ''::text))
);


--
-- Name: object_visual_reference_decision_sha(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.object_visual_reference_decision_sha(p_decision_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN release.canonical_jsonb_sha256((SELECT to_jsonb(d.*) AS to_jsonb FROM rights.object_visual_reference_review_decision d WHERE (d.object_visual_reference_review_decision_id = object_visual_reference_decision_sha.p_decision_id)));


--
-- Name: object_visual_reference_evidence_sha(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.object_visual_reference_evidence_sha(p_evidence_item_id uuid) RETURNS core.sha256_hex
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN release.canonical_jsonb_sha256((SELECT to_jsonb(e.*) AS to_jsonb FROM provenance.evidence_item e WHERE (e.evidence_item_id = object_visual_reference_evidence_sha.p_evidence_item_id)));


--
-- Name: object_visual_reference; Type: TABLE; Schema: rights; Owner: -
--

CREATE TABLE rights.object_visual_reference (
    object_visual_reference_id uuid NOT NULL,
    archive_object_id uuid NOT NULL,
    external_visual_reference_id uuid NOT NULL,
    reference_role rights.reference_role NOT NULL,
    ordinal integer NOT NULL,
    acceptance_state provenance.assertion_status NOT NULL,
    evidence_item_id uuid,
    CONSTRAINT object_visual_reference_ordinal_check CHECK ((ordinal >= 0))
);


--
-- Name: object_visual_reference_snapshot_sha(uuid, uuid, core.sha256_hex); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.object_visual_reference_snapshot_sha(p_bridge_id uuid, p_compatible_research_release_id uuid, p_compatible_research_manifest_sha256 core.sha256_hex) RETURNS core.sha256_hex
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    RETURN (SELECT release.canonical_jsonb_sha256(jsonb_build_object('objectVisualReferenceId', b.object_visual_reference_id, 'compatibleResearchReleaseId', object_visual_reference_snapshot_sha.p_compatible_research_release_id, 'compatibleResearchManifestSha256', object_visual_reference_snapshot_sha.p_compatible_research_manifest_sha256, 'archiveObjectId', b.archive_object_id, 'externalVisualReferenceId', b.external_visual_reference_id, 'referenceRole', b.reference_role, 'ordinal', b.ordinal, 'acceptanceState', b.acceptance_state, 'evidenceItemId', b.evidence_item_id, 'evidenceSnapshotSha256', rights.object_visual_reference_evidence_sha(b.evidence_item_id), 'reviewDecisionId', d.object_visual_reference_review_decision_id, 'decisionSnapshotSha256', rights.object_visual_reference_decision_sha(d.object_visual_reference_review_decision_id))) AS canonical_jsonb_sha256 FROM (rights.object_visual_reference b JOIN rights.object_visual_reference_review_decision d ON (((d.object_visual_reference_id = b.object_visual_reference_id) AND (d.outcome = 'accept'::workflow.review_outcome) AND (d.evidence_item_id = b.evidence_item_id)))) WHERE ((b.object_visual_reference_id = object_visual_reference_snapshot_sha.p_bridge_id) AND (b.acceptance_state = 'accepted'::provenance.assertion_status) AND (NOT (EXISTS (SELECT 1 FROM rights.object_visual_reference_review_decision newer WHERE (newer.supersedes_decision_id = d.object_visual_reference_review_decision_id))))));


--
-- Name: policy_rank(rights.policy_state); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.policy_rank(p_state rights.policy_state) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    RETURN CASE p_state WHEN 'remote_display_allowed'::rights.policy_state THEN 4 WHEN 'source_viewer_only'::rights.policy_state THEN 3 WHEN 'link_only'::rights.policy_state THEN 2 WHEN 'citation_only'::rights.policy_state THEN 1 WHEN 'disallowed'::rights.policy_state THEN 1 ELSE 1 END;


--
-- Name: record_attribution_bundle(uuid, uuid, rights.attribution_state, uuid, timestamp with time zone, uuid, text[], integer[], text[], text[]); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.record_attribution_bundle(p_bundle_id uuid, p_bridge_id uuid, p_state rights.attribution_state, p_evidence_item_id uuid, p_validated_at timestamp with time zone, p_supersedes_bundle_id uuid, p_value_kinds text[], p_value_ordinals integer[], p_language_tags text[], p_value_texts text[]) RETURNS core.sha256_hex
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_index integer;
  v_values jsonb;
  v_sha256 core.sha256_hex;
BEGIN
  PERFORM rights.require_reviewer();
  PERFORM pg_advisory_xact_lock(hashtext('gda_v49_visual_seal_takedown'));
  IF p_validated_at > clock_timestamp()
    OR cardinality(p_value_kinds) IS DISTINCT FROM cardinality(p_value_ordinals)
    OR cardinality(p_value_kinds) IS DISTINCT FROM cardinality(p_language_tags)
    OR cardinality(p_value_kinds) IS DISTINCT FROM cardinality(p_value_texts)
    OR (p_state = 'complete' AND (
      p_evidence_item_id IS NULL OR COALESCE(cardinality(p_value_kinds), 0) = 0)) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'ATTRIBUTION_BUNDLE_INPUT_INVALID';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_array(
      p_value_kinds[i], p_value_ordinals[i],
      p_language_tags[i], p_value_texts[i]
    ) ORDER BY p_value_kinds[i], p_value_ordinals[i]), '[]'::jsonb)
  INTO v_values
  FROM generate_subscripts(COALESCE(p_value_kinds, ARRAY[]::text[]), 1) AS g(i);
  v_sha256 := release.canonical_jsonb_sha256(jsonb_build_object(
    'bundleId', p_bundle_id,
    'bridgeId', p_bridge_id,
    'state', p_state,
    'evidenceId', p_evidence_item_id,
    'validatedBy', session_user::text,
    'validatedAtUs', (extract(epoch FROM p_validated_at) * 1000000)::bigint,
    'supersedesBundleId', p_supersedes_bundle_id,
    'values', v_values
  ));
  INSERT INTO rights.attribution_bundle VALUES (
    p_bundle_id, p_bridge_id, p_state, v_sha256, p_evidence_item_id,
    session_user::text, p_validated_at, p_supersedes_bundle_id);
  IF COALESCE(cardinality(p_value_kinds), 0) > 0 THEN
    FOR v_index IN 1..cardinality(p_value_kinds) LOOP
      INSERT INTO rights.attribution_bundle_value VALUES (
        p_bundle_id, p_value_kinds[v_index], p_value_ordinals[v_index],
        p_language_tags[v_index], p_value_texts[v_index]);
    END LOOP;
  END IF;
  PERFORM audit.record_decision_event('attribution_validation', p_bundle_id);
  RETURN v_sha256;
END
$$;


--
-- Name: record_delivery_assessment(uuid, uuid, uuid[], provenance.evidence_role[], uuid[], uuid, rights.delivery_mode, rights.delivery_rule_id, timestamp with time zone, uuid, uuid[], uuid[], rights.locator_role[]); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.record_delivery_assessment(p_delivery_id uuid, p_bridge_id uuid, p_rights_assessment_ids uuid[], p_rights_evidence_roles provenance.evidence_role[], p_policy_evaluation_ids uuid[], p_attribution_bundle_id uuid, p_mode rights.delivery_mode, p_reason_code rights.delivery_rule_id, p_assessed_at timestamp with time zone, p_supersedes_id uuid, p_locator_ids uuid[], p_health_observation_ids uuid[], p_locator_roles rights.locator_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_index integer;
BEGIN
  PERFORM rights.require_reviewer();
  PERFORM pg_advisory_xact_lock(hashtext('gda_v49_visual_seal_takedown'));
  IF p_assessed_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_DELIVERY_ASSESSMENT_DENIED';
  END IF;
  IF p_mode IS DISTINCT FROM rights.delivery_mode_for_rule(p_reason_code) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'DELIVERY_RULE_MODE_PAIR_INVALID';
  END IF;
  IF COALESCE(cardinality(p_rights_assessment_ids), 0) = 0
    OR cardinality(p_rights_assessment_ids)
      IS DISTINCT FROM cardinality(p_rights_evidence_roles)
    OR COALESCE(cardinality(p_policy_evaluation_ids), 0) = 0
    OR cardinality(p_locator_ids)
      IS DISTINCT FROM cardinality(p_health_observation_ids)
    OR cardinality(p_locator_ids)
      IS DISTINCT FROM cardinality(p_locator_roles) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'DELIVERY_GOVERNING_SET_CARDINALITY_INVALID';
  END IF;
  INSERT INTO rights.delivery_assessment (
    delivery_assessment_id, object_visual_reference_id,
    attribution_bundle_id, delivery_mode, reason_code, assessor_actor,
    assessed_at, supersedes_delivery_assessment_id, machine_reason_code
  ) VALUES (
    p_delivery_id, p_bridge_id, p_attribution_bundle_id, p_mode,
    p_reason_code, session_user::text, p_assessed_at, p_supersedes_id,
    rights.machine_reason_for_rule(p_reason_code)
  );
  FOR v_index IN 1..cardinality(p_rights_assessment_ids) LOOP
    INSERT INTO rights.delivery_rights_assessment VALUES (
      p_delivery_id, p_rights_assessment_ids[v_index],
      p_rights_evidence_roles[v_index]);
  END LOOP;
  FOR v_index IN 1..cardinality(p_policy_evaluation_ids) LOOP
    INSERT INTO rights.delivery_policy_evaluation VALUES (
      p_delivery_id, p_policy_evaluation_ids[v_index]);
  END LOOP;
  IF COALESCE(cardinality(p_locator_ids), 0) > 0 THEN
    FOR v_index IN 1..cardinality(p_locator_ids) LOOP
      IF num_nonnulls(
          p_locator_ids[v_index], p_health_observation_ids[v_index],
          p_locator_roles[v_index]) <> 3 THEN
        RAISE EXCEPTION USING ERRCODE = '23514',
          MESSAGE = 'DELIVERY_LOCATOR_QUALIFICATION_MUST_BE_COMPLETE';
      END IF;
      INSERT INTO rights.delivery_locator_qualification VALUES (
        p_delivery_id, p_locator_ids[v_index],
        p_health_observation_ids[v_index], p_locator_roles[v_index]);
    END LOOP;
  END IF;
  PERFORM audit.record_decision_event('delivery_assessment', p_delivery_id);
END
$$;


--
-- Name: record_endpoint_health_observation(uuid, uuid, rights.health_state, core.release_token, timestamp with time zone, timestamp with time zone, core.sha256_hex); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.record_endpoint_health_observation(p_observation_id uuid, p_locator_id uuid, p_health_state rights.health_state, p_method_version core.release_token, p_checked_at timestamp with time zone, p_valid_until timestamp with time zone, p_request_fingerprint core.sha256_hex) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM raw.require_ingest_writer();
  PERFORM pg_advisory_xact_lock(hashtext('gda_v49_visual_seal_takedown'));
  IF p_checked_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_ENDPOINT_HEALTH_OBSERVATION_DENIED';
  END IF;
  INSERT INTO rights.endpoint_health_observation (
    endpoint_health_observation_id, visual_locator_id, health_state,
    method_version,
    checked_at, valid_until, request_fingerprint
  ) VALUES (
    p_observation_id, p_locator_id, p_health_state,
    p_method_version,
    p_checked_at, p_valid_until, p_request_fingerprint
  );
END
$$;


--
-- Name: record_object_visual_reference_review_decision(uuid, uuid, workflow.review_outcome, uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.record_object_visual_reference_review_decision(p_decision_id uuid, p_bridge_id uuid, p_outcome workflow.review_outcome, p_evidence_item_id uuid, p_rationale text, p_supersedes_decision_id uuid, p_decided_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_bridge rights.object_visual_reference%ROWTYPE;
  v_current_id uuid;
  v_state provenance.assertion_status;
BEGIN
  PERFORM rights.require_reviewer();
  IF p_decided_at IS NULL OR p_decided_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_VISUAL_BRIDGE_REVIEW_DENIED';
  END IF;
  IF p_outcome NOT IN ('accept','hold','reject','supersede') THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'VISUAL_BRIDGE_REVIEW_OUTCOME_INVALID';
  END IF;
  SELECT * INTO STRICT v_bridge
  FROM rights.object_visual_reference b
  WHERE b.object_visual_reference_id = p_bridge_id
  FOR UPDATE;
  SELECT d.object_visual_reference_review_decision_id INTO v_current_id
  FROM rights.object_visual_reference_review_decision d
  WHERE d.object_visual_reference_id = p_bridge_id
    AND NOT EXISTS (
      SELECT 1
      FROM rights.object_visual_reference_review_decision newer
      WHERE newer.supersedes_decision_id =
        d.object_visual_reference_review_decision_id
    );
  IF p_supersedes_decision_id IS DISTINCT FROM v_current_id THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'VISUAL_BRIDGE_REVIEW_MUST_SUPERSEDE_CURRENT_DECISION';
  END IF;
  IF v_current_id IS NULL AND v_bridge.acceptance_state <> 'proposed' THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'VISUAL_BRIDGE_INITIAL_REVIEW_REQUIRES_PROPOSED_STATE';
  END IF;

  INSERT INTO rights.object_visual_reference_review_decision (
    object_visual_reference_review_decision_id,
    object_visual_reference_id, outcome, evidence_item_id,
    reviewer_actor, rationale, supersedes_decision_id, decided_at
  ) VALUES (
    p_decision_id, p_bridge_id, p_outcome, p_evidence_item_id,
    session_user::text, p_rationale, p_supersedes_decision_id,
    p_decided_at
  );
  v_state := CASE p_outcome
    WHEN 'accept' THEN 'accepted'::provenance.assertion_status
    WHEN 'reject' THEN 'rejected'::provenance.assertion_status
    WHEN 'supersede' THEN 'superseded'::provenance.assertion_status
    ELSE 'proposed'::provenance.assertion_status
  END;
  UPDATE rights.object_visual_reference
  SET acceptance_state = v_state,
      evidence_item_id = p_evidence_item_id
  WHERE object_visual_reference_id = p_bridge_id;
  PERFORM audit.record_decision_event('visual_bridge_review', p_decision_id);
END
$$;


--
-- Name: record_provider_policy_evaluation(uuid, uuid, rights.policy_state, uuid[], timestamp with time zone, uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.record_provider_policy_evaluation(p_evaluation_id uuid, p_bridge_id uuid, p_state rights.policy_state, p_policy_version_ids uuid[], p_evaluated_at timestamp with time zone, p_supersedes_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_policy_id uuid;
BEGIN
  PERFORM rights.require_reviewer();
  PERFORM pg_advisory_xact_lock(hashtext('gda_v49_visual_seal_takedown'));
  IF p_evaluated_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_PROVIDER_POLICY_EVALUATION_DENIED';
  END IF;
  INSERT INTO rights.provider_policy_evaluation (
    provider_policy_evaluation_id, object_visual_reference_id,
    evaluated_state, evaluator_actor, evaluated_at,
    supersedes_provider_policy_evaluation_id
  ) VALUES (
    p_evaluation_id, p_bridge_id, p_state, session_user::text,
    p_evaluated_at, p_supersedes_id
  );
  FOREACH v_policy_id IN ARRAY COALESCE(p_policy_version_ids, ARRAY[]::uuid[]) LOOP
    INSERT INTO rights.provider_policy_evaluation_version VALUES (
      p_evaluation_id, v_policy_id);
  END LOOP;
  PERFORM audit.record_decision_event(
    'provider_policy_evaluation', p_evaluation_id);
END
$$;


--
-- Name: record_rights_assessment(uuid, rights.rights_subject_kind, uuid, rights.rights_evidence_state, text, timestamp with time zone, uuid, uuid[], provenance.evidence_role[]); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.record_rights_assessment(p_assessment_id uuid, p_subject_kind rights.rights_subject_kind, p_subject_id uuid, p_assessed_state rights.rights_evidence_state, p_rationale text, p_assessed_at timestamp with time zone, p_supersedes_id uuid, p_observation_ids uuid[], p_evidence_roles provenance.evidence_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_index integer;
BEGIN
  PERFORM rights.require_reviewer();
  PERFORM pg_advisory_xact_lock(hashtext('gda_v49_visual_seal_takedown'));
  IF p_assessed_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_RIGHTS_ASSESSMENT_DENIED';
  END IF;
  INSERT INTO rights.rights_assessment (
    rights_assessment_id, subject_kind, assessed_state, reviewer_actor,
    rationale, assessed_at, supersedes_rights_assessment_id
  ) VALUES (
    p_assessment_id, p_subject_kind, p_assessed_state, session_user::text,
    p_rationale, p_assessed_at, p_supersedes_id
  );
  CASE p_subject_kind
    WHEN 'provider_object' THEN
      INSERT INTO rights.rights_assessment_provider_object VALUES (p_assessment_id, p_subject_id);
    WHEN 'external_visual_reference' THEN
      INSERT INTO rights.rights_assessment_visual_reference VALUES (p_assessment_id, p_subject_id);
    WHEN 'digital_representation' THEN
      INSERT INTO rights.rights_assessment_representation VALUES (p_assessment_id, p_subject_id);
    WHEN 'visual_locator' THEN
      INSERT INTO rights.rights_assessment_locator VALUES (p_assessment_id, p_subject_id);
  END CASE;
  IF COALESCE(cardinality(p_observation_ids), 0) = 0
    OR cardinality(p_observation_ids) IS DISTINCT FROM cardinality(p_evidence_roles) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'RIGHTS_ASSESSMENT_OBSERVATION_SET_INVALID';
  END IF;
  FOR v_index IN 1..cardinality(p_observation_ids) LOOP
    INSERT INTO rights.rights_assessment_observation VALUES (
      p_assessment_id, p_observation_ids[v_index], p_evidence_roles[v_index]);
  END LOOP;
  PERFORM audit.record_decision_event('rights_assessment', p_assessment_id);
END
$$;


--
-- Name: record_rights_observation(uuid, rights.rights_subject_kind, uuid, rights.rights_evidence_state, uuid, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.record_rights_observation(p_observation_id uuid, p_subject_kind rights.rights_subject_kind, p_subject_id uuid, p_evidence_state rights.rights_evidence_state, p_evidence_item_id uuid, p_wording text, p_observed_at timestamp with time zone, p_supersedes_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM rights.require_reviewer();
  PERFORM pg_advisory_xact_lock(hashtext('gda_v49_visual_seal_takedown'));
  IF p_observed_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_RIGHTS_OBSERVATION_DENIED';
  END IF;
  INSERT INTO rights.rights_observation (
    rights_observation_id, subject_kind, evidence_state, evidence_item_id,
    observed_wording, observed_at, supersedes_rights_observation_id
  ) VALUES (
    p_observation_id, p_subject_kind, p_evidence_state, p_evidence_item_id,
    p_wording, p_observed_at, p_supersedes_id
  );
  CASE p_subject_kind
    WHEN 'provider_object' THEN
      INSERT INTO rights.rights_observation_provider_object VALUES (p_observation_id, p_subject_id);
    WHEN 'external_visual_reference' THEN
      INSERT INTO rights.rights_observation_visual_reference VALUES (p_observation_id, p_subject_id);
    WHEN 'digital_representation' THEN
      INSERT INTO rights.rights_observation_representation VALUES (p_observation_id, p_subject_id);
    WHEN 'visual_locator' THEN
      INSERT INTO rights.rights_observation_locator VALUES (p_observation_id, p_subject_id);
  END CASE;
  PERFORM audit.record_decision_event('rights_observation', p_observation_id);
END
$$;


--
-- Name: record_takedown_event(uuid, rights.takedown_action, timestamp with time zone, timestamp with time zone, text, uuid, uuid[], rights.takedown_scope_kind[], uuid[], uuid[], rights.delivery_mode[], uuid[]); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.record_takedown_event(p_event_id uuid, p_action rights.takedown_action, p_effective_from timestamp with time zone, p_effective_until timestamp with time zone, p_reason_code text, p_evidence_item_id uuid, p_scope_ids uuid[], p_scope_kinds rights.takedown_scope_kind[], p_subject_ids uuid[], p_override_ids uuid[], p_restrictive_modes rights.delivery_mode[], p_supersedes_override_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_overlay_sha256 core.sha256_hex;
  v_entry record;
  v_sidecar_id uuid;
  v_index integer;
BEGIN
  PERFORM rights.require_reviewer();
  PERFORM pg_advisory_xact_lock(hashtext('gda_v49_visual_seal_takedown'));
  IF p_evidence_item_id IS NULL
    OR COALESCE(cardinality(p_scope_ids), 0) = 0
    OR cardinality(p_scope_ids) IS DISTINCT FROM cardinality(p_scope_kinds)
    OR cardinality(p_scope_ids) IS DISTINCT FROM cardinality(p_subject_ids)
    OR cardinality(p_scope_ids) IS DISTINCT FROM cardinality(p_override_ids)
    OR cardinality(p_scope_ids) IS DISTINCT FROM cardinality(p_restrictive_modes)
    OR cardinality(p_scope_ids)
      IS DISTINCT FROM cardinality(p_supersedes_override_ids)
    OR EXISTS (
      SELECT 1 FROM unnest(p_supersedes_override_ids) x(id)
      WHERE x.id IS NOT NULL) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TAKEDOWN_NEW_EVENT_SCOPE_SET_INVALID';
  END IF;
  INSERT INTO rights.takedown_event VALUES (
    p_event_id, p_action, p_effective_from, p_effective_until,
    p_reason_code, p_evidence_item_id, session_user::text,
    clock_timestamp());
  PERFORM audit.record_decision_event('takedown', p_event_id);
  FOR v_index IN 1..cardinality(p_scope_ids) LOOP
    v_overlay_sha256 := rights.insert_takedown_scope(
      p_event_id, p_scope_ids[v_index], v_index,
      p_scope_kinds[v_index], p_subject_ids[v_index],
      p_override_ids[v_index], 1,
      p_restrictive_modes[v_index], NULL);
    FOR v_entry IN
      SELECT e.visual_registry_release_id, e.visual_registry_entry_id
      FROM release.visual_registry_entry e
      JOIN release.visual_registry_release r
        ON r.visual_registry_release_id = e.visual_registry_release_id
      WHERE r.release_state = 'sealed'
        AND rights.scope_matches_bridge(
          p_scope_ids[v_index], e.object_visual_reference_id)
    LOOP
      v_sidecar_id := gen_random_uuid();
      INSERT INTO release.visual_takedown_sidecar_event (
        visual_takedown_sidecar_event_id, visual_registry_release_id,
        visual_registry_entry_id, takedown_override_id, restrictive_mode,
        overlay_sha256, effective_from, effective_until, recorded_at
      ) VALUES (
        v_sidecar_id, v_entry.visual_registry_release_id,
        v_entry.visual_registry_entry_id, p_override_ids[v_index],
        p_restrictive_modes[v_index], v_overlay_sha256,
        p_effective_from, p_effective_until, clock_timestamp()
      );
      INSERT INTO audit.sidecar_event VALUES (
        gen_random_uuid(), NULL, v_sidecar_id,
        release.canonical_jsonb_sha256(jsonb_build_array(
          'takedown-sidecar', v_sidecar_id,
          v_entry.visual_registry_release_id,
          v_entry.visual_registry_entry_id, p_override_ids[v_index],
          v_overlay_sha256)), session_user::text, clock_timestamp()
      );
    END LOOP;
  END LOOP;
END
$$;


--
-- Name: record_takedown_override_correction(uuid, uuid, rights.delivery_mode, uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.record_takedown_override_correction(p_override_id uuid, p_scope_id uuid, p_restrictive_mode rights.delivery_mode, p_supersedes_override_id uuid) RETURNS core.sha256_hex
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_prior rights.takedown_override%ROWTYPE;
  v_event rights.takedown_event%ROWTYPE;
  v_created_at timestamptz := clock_timestamp();
  v_sha core.sha256_hex;
  v_entry record;
  v_sidecar_id uuid;
  v_recorded_at timestamptz;
BEGIN
  PERFORM rights.require_reviewer();
  PERFORM pg_advisory_xact_lock(hashtext('gda_v49_visual_seal_takedown'));
  SELECT * INTO STRICT v_prior
  FROM rights.takedown_override o
  WHERE o.takedown_override_id = p_supersedes_override_id
    AND o.takedown_scope_id = p_scope_id
    AND NOT EXISTS (
      SELECT 1 FROM rights.takedown_override newer
      WHERE newer.supersedes_takedown_override_id = o.takedown_override_id)
  FOR UPDATE;
  SELECT e.* INTO STRICT v_event
  FROM rights.takedown_scope s
  JOIN rights.takedown_event e ON e.takedown_event_id = s.takedown_event_id
  WHERE s.takedown_scope_id = p_scope_id;
  IF rights.delivery_rank(p_restrictive_mode) >
      rights.delivery_rank(v_prior.restrictive_mode)
    OR rights.delivery_rank(p_restrictive_mode) >
      rights.delivery_rank(CASE v_event.action
        WHEN 'blocked' THEN 'blocked'::rights.delivery_mode
        ELSE 'citation_only'::rights.delivery_mode END) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'TAKEDOWN_OVERRIDE_CANNOT_RELAX';
  END IF;
  v_sha := release.canonical_jsonb_sha256(jsonb_build_object(
    'action', v_event.action,
    'createdAtUs', (extract(epoch FROM v_created_at) * 1000000)::bigint,
    'effectiveFromUs',
      (extract(epoch FROM v_event.effective_from) * 1000000)::bigint,
    'effectiveUntilUs', CASE WHEN v_event.effective_until IS NULL THEN NULL
      ELSE (extract(epoch FROM v_event.effective_until) * 1000000)::bigint END,
    'eventId', v_event.takedown_event_id,
    'evidenceId', v_event.evidence_item_id,
    'overrideId', p_override_id,
    'overrideVersion', v_prior.override_version + 1,
    'reasonCode', v_event.reason_code,
    'restrictiveMode', p_restrictive_mode,
    'scopeId', p_scope_id,
    'scopeKind', (SELECT s.scope_kind FROM rights.takedown_scope s
      WHERE s.takedown_scope_id = p_scope_id),
    'scopeOrdinal', (SELECT s.scope_ordinal FROM rights.takedown_scope s
      WHERE s.takedown_scope_id = p_scope_id),
    'scopeTarget', rights.takedown_scope_target_key(p_scope_id),
    'supersedesOverrideId', p_supersedes_override_id
  ));
  INSERT INTO rights.takedown_override (
    takedown_override_id, takedown_scope_id, restrictive_mode,
    overlay_sha256, supersedes_takedown_override_id, created_at,
    override_version
  ) VALUES (
    p_override_id, p_scope_id, p_restrictive_mode, v_sha,
    p_supersedes_override_id, v_created_at,
    v_prior.override_version + 1
  );
  FOR v_entry IN
    SELECT e.visual_registry_release_id, e.visual_registry_entry_id
    FROM release.visual_registry_entry e
    JOIN release.visual_registry_release r
      ON r.visual_registry_release_id = e.visual_registry_release_id
    WHERE r.release_state = 'sealed'
      AND rights.scope_matches_bridge(
        p_scope_id, e.object_visual_reference_id)
  LOOP
    v_sidecar_id := gen_random_uuid();
    v_recorded_at := clock_timestamp();
    INSERT INTO release.visual_takedown_sidecar_event (
      visual_takedown_sidecar_event_id, visual_registry_release_id,
      visual_registry_entry_id, takedown_override_id, restrictive_mode,
      overlay_sha256, effective_from, effective_until, recorded_at
    ) VALUES (
      v_sidecar_id, v_entry.visual_registry_release_id,
      v_entry.visual_registry_entry_id, p_override_id,
      p_restrictive_mode, v_sha, v_event.effective_from,
      v_event.effective_until, v_recorded_at
    );
    INSERT INTO audit.sidecar_event (
      sidecar_event_id, visual_health_sidecar_event_id,
      visual_takedown_sidecar_event_id, event_sha256, actor, occurred_at
    ) VALUES (
      gen_random_uuid(), NULL, v_sidecar_id,
      release.canonical_jsonb_sha256(jsonb_build_array(
        'takedown-correction-sidecar', v_sidecar_id,
        v_entry.visual_registry_release_id,
        v_entry.visual_registry_entry_id, p_override_id, v_sha)),
      session_user::text, v_recorded_at
    );
  END LOOP;
  RETURN v_sha;
END
$$;


--
-- Name: require_reviewer(); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.require_reviewer() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF session_user::text <> 'gda_v49_phase2a_reviewer' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'REVIEWER_REQUIRED';
  END IF;
END
$$;


--
-- Name: scope_matches_bridge(uuid, uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.scope_matches_bridge(p_scope_id uuid, p_bridge_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_kind rights.takedown_scope_kind;
  v_reference_id uuid;
  v_provider_object_id uuid;
  v_provider_id uuid;
BEGIN
  SELECT s.scope_kind, b.external_visual_reference_id,
    vr.provider_object_id, po.provider_id
  INTO v_kind, v_reference_id, v_provider_object_id, v_provider_id
  FROM rights.takedown_scope s
  CROSS JOIN rights.object_visual_reference b
  JOIN rights.external_visual_reference vr
    ON vr.external_visual_reference_id = b.external_visual_reference_id
  LEFT JOIN rights.provider_object po ON po.provider_object_id = vr.provider_object_id
  WHERE s.takedown_scope_id = p_scope_id
    AND b.object_visual_reference_id = p_bridge_id;
  IF NOT FOUND THEN RETURN false; END IF;
  RETURN CASE v_kind
    WHEN 'provider' THEN EXISTS (
      SELECT 1 FROM rights.takedown_scope_provider x
      WHERE x.takedown_scope_id = p_scope_id AND x.provider_id = v_provider_id)
    WHEN 'provider_object' THEN EXISTS (
      SELECT 1 FROM rights.takedown_scope_provider_object x
      WHERE x.takedown_scope_id = p_scope_id AND x.provider_object_id = v_provider_object_id)
    WHEN 'external_visual_reference' THEN EXISTS (
      SELECT 1 FROM rights.takedown_scope_visual_reference x
      WHERE x.takedown_scope_id = p_scope_id AND x.external_visual_reference_id = v_reference_id)
    WHEN 'digital_representation' THEN EXISTS (
      SELECT 1 FROM rights.takedown_scope_representation x
      JOIN rights.visual_reference_representation r
        ON r.digital_representation_id = x.digital_representation_id
      WHERE x.takedown_scope_id = p_scope_id
        AND r.external_visual_reference_id = v_reference_id)
    WHEN 'visual_locator' THEN EXISTS (
      SELECT 1 FROM rights.takedown_scope_locator x
      JOIN rights.visual_locator l ON l.visual_locator_id = x.visual_locator_id
      WHERE x.takedown_scope_id = p_scope_id
        AND l.external_visual_reference_id = v_reference_id)
    WHEN 'object_visual_reference' THEN EXISTS (
      SELECT 1 FROM rights.takedown_scope_object_visual_reference x
      WHERE x.takedown_scope_id = p_scope_id
        AND x.object_visual_reference_id = p_bridge_id)
    ELSE false
  END;
END
$$;


--
-- Name: subject_applies_to_delivery(rights.rights_subject_kind, uuid, uuid, uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.subject_applies_to_delivery(p_subject_kind rights.rights_subject_kind, p_subject_id uuid, p_bridge_id uuid, p_delivery_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_reference_id uuid; v_provider_object_id uuid;
BEGIN
  SELECT b.external_visual_reference_id, vr.provider_object_id
  INTO v_reference_id, v_provider_object_id
  FROM rights.object_visual_reference b
  JOIN rights.external_visual_reference vr
    ON vr.external_visual_reference_id = b.external_visual_reference_id
  WHERE b.object_visual_reference_id = p_bridge_id;
  RETURN CASE p_subject_kind
    WHEN 'provider_object' THEN p_subject_id = v_provider_object_id
    WHEN 'external_visual_reference' THEN p_subject_id = v_reference_id
    WHEN 'digital_representation' THEN EXISTS (
      SELECT 1
      FROM rights.delivery_locator_qualification q
      JOIN rights.visual_locator_representation r
        ON r.visual_locator_id = q.visual_locator_id
      WHERE q.delivery_assessment_id = p_delivery_id
        AND r.external_visual_reference_id = v_reference_id
        AND r.digital_representation_id = p_subject_id)
    WHEN 'visual_locator' THEN EXISTS (
      SELECT 1 FROM rights.delivery_locator_qualification q
      JOIN rights.visual_locator l ON l.visual_locator_id = q.visual_locator_id
      WHERE q.delivery_assessment_id = p_delivery_id
        AND q.visual_locator_id = p_subject_id
        AND l.external_visual_reference_id = v_reference_id)
    ELSE false
  END;
END
$$;


--
-- Name: validate_one_delivery_assessment(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.validate_one_delivery_assessment(p_delivery_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_id uuid := p_delivery_id;
  v_bridge uuid;
  v_mode rights.delivery_mode;
  v_assessed_at timestamptz;
  v_attribution uuid;
  v_rights_cap integer;
  v_policy_cap integer;
  v_attribution_cap integer;
  v_takedown_cap integer := 4;
  v_required_role rights.locator_role;
BEGIN
  SELECT d.object_visual_reference_id, d.delivery_mode, d.assessed_at,
    d.attribution_bundle_id
  INTO v_bridge, v_mode, v_assessed_at, v_attribution
  FROM rights.delivery_assessment d WHERE d.delivery_assessment_id = v_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_assessed_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_DELIVERY_ASSESSMENT_DENIED';
  END IF;

  -- Enumerate only subjects reachable from this delivery.  Each branch starts
  -- from a typed target and therefore uses the four forward-migration indexes
  -- above.  UNION retains the original set semantics when a representation is
  -- reachable through more than one qualified locator.
  IF NOT EXISTS (
    SELECT 1 FROM rights.delivery_rights_assessment x
    WHERE x.delivery_assessment_id = v_id
  ) OR EXISTS (
    WITH applicable(rights_assessment_id) AS (
      SELECT t.rights_assessment_id
      FROM rights.object_visual_reference b
      JOIN rights.external_visual_reference r
        ON r.external_visual_reference_id=b.external_visual_reference_id
      JOIN rights.rights_assessment_provider_object t
        ON t.provider_object_id=r.provider_object_id
      JOIN rights.rights_assessment a
        ON a.rights_assessment_id=t.rights_assessment_id
       AND a.subject_kind='provider_object'
      WHERE b.object_visual_reference_id=v_bridge
      UNION
      SELECT t.rights_assessment_id
      FROM rights.object_visual_reference b
      JOIN rights.rights_assessment_visual_reference t
        ON t.external_visual_reference_id=b.external_visual_reference_id
      JOIN rights.rights_assessment a
        ON a.rights_assessment_id=t.rights_assessment_id
       AND a.subject_kind='external_visual_reference'
      WHERE b.object_visual_reference_id=v_bridge
      UNION
      SELECT t.rights_assessment_id
      FROM rights.object_visual_reference b
      JOIN rights.delivery_locator_qualification q
        ON q.delivery_assessment_id=v_id
      JOIN rights.visual_locator_representation r
        ON r.visual_locator_id=q.visual_locator_id
       AND r.external_visual_reference_id=b.external_visual_reference_id
      JOIN rights.rights_assessment_representation t
        ON t.digital_representation_id=r.digital_representation_id
      JOIN rights.rights_assessment a
        ON a.rights_assessment_id=t.rights_assessment_id
       AND a.subject_kind='digital_representation'
      WHERE b.object_visual_reference_id=v_bridge
      UNION
      SELECT t.rights_assessment_id
      FROM rights.object_visual_reference b
      JOIN rights.delivery_locator_qualification q
        ON q.delivery_assessment_id=v_id
      JOIN rights.visual_locator l
        ON l.visual_locator_id=q.visual_locator_id
       AND l.external_visual_reference_id=b.external_visual_reference_id
      JOIN rights.rights_assessment_locator t
        ON t.visual_locator_id=q.visual_locator_id
      JOIN rights.rights_assessment a
        ON a.rights_assessment_id=t.rights_assessment_id
       AND a.subject_kind='visual_locator'
      WHERE b.object_visual_reference_id=v_bridge
    )
    SELECT 1
    FROM rights.delivery_rights_assessment x
    JOIN rights.rights_assessment a
      ON a.rights_assessment_id=x.rights_assessment_id
    WHERE x.delivery_assessment_id=v_id
      AND (
        NOT EXISTS (SELECT 1 FROM applicable p
          WHERE p.rights_assessment_id=a.rights_assessment_id)
        OR a.assessed_at > v_assessed_at
        OR EXISTS (SELECT 1 FROM rights.rights_assessment newer
          WHERE newer.supersedes_rights_assessment_id=a.rights_assessment_id)
      )
  ) OR EXISTS (
    WITH applicable(rights_assessment_id) AS (
      SELECT t.rights_assessment_id
      FROM rights.object_visual_reference b
      JOIN rights.external_visual_reference r
        ON r.external_visual_reference_id=b.external_visual_reference_id
      JOIN rights.rights_assessment_provider_object t
        ON t.provider_object_id=r.provider_object_id
      JOIN rights.rights_assessment a
        ON a.rights_assessment_id=t.rights_assessment_id
       AND a.subject_kind='provider_object'
      WHERE b.object_visual_reference_id=v_bridge
      UNION
      SELECT t.rights_assessment_id
      FROM rights.object_visual_reference b
      JOIN rights.rights_assessment_visual_reference t
        ON t.external_visual_reference_id=b.external_visual_reference_id
      JOIN rights.rights_assessment a
        ON a.rights_assessment_id=t.rights_assessment_id
       AND a.subject_kind='external_visual_reference'
      WHERE b.object_visual_reference_id=v_bridge
      UNION
      SELECT t.rights_assessment_id
      FROM rights.object_visual_reference b
      JOIN rights.delivery_locator_qualification q
        ON q.delivery_assessment_id=v_id
      JOIN rights.visual_locator_representation r
        ON r.visual_locator_id=q.visual_locator_id
       AND r.external_visual_reference_id=b.external_visual_reference_id
      JOIN rights.rights_assessment_representation t
        ON t.digital_representation_id=r.digital_representation_id
      JOIN rights.rights_assessment a
        ON a.rights_assessment_id=t.rights_assessment_id
       AND a.subject_kind='digital_representation'
      WHERE b.object_visual_reference_id=v_bridge
      UNION
      SELECT t.rights_assessment_id
      FROM rights.object_visual_reference b
      JOIN rights.delivery_locator_qualification q
        ON q.delivery_assessment_id=v_id
      JOIN rights.visual_locator l
        ON l.visual_locator_id=q.visual_locator_id
       AND l.external_visual_reference_id=b.external_visual_reference_id
      JOIN rights.rights_assessment_locator t
        ON t.visual_locator_id=q.visual_locator_id
      JOIN rights.rights_assessment a
        ON a.rights_assessment_id=t.rights_assessment_id
       AND a.subject_kind='visual_locator'
      WHERE b.object_visual_reference_id=v_bridge
    )
    SELECT 1
    FROM applicable p
    JOIN rights.rights_assessment a
      ON a.rights_assessment_id=p.rights_assessment_id
    WHERE NOT EXISTS (SELECT 1 FROM rights.rights_assessment newer
      WHERE newer.supersedes_rights_assessment_id=a.rights_assessment_id)
      AND NOT EXISTS (
        SELECT 1 FROM rights.delivery_rights_assessment linked
        WHERE linked.delivery_assessment_id=v_id
          AND linked.rights_assessment_id=a.rights_assessment_id
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'DELIVERY_REQUIRES_APPLICABLE_RIGHTS_ASSESSMENT';
  END IF;

  SELECT min(CASE
    WHEN x.evidence_role = 'contradicts' THEN 1
    WHEN x.evidence_role = 'contextualises' THEN 2
    WHEN a.assessed_state = 'permitted' THEN CASE
      WHEN a.subject_kind = 'digital_representation' THEN 2 ELSE 4 END
    WHEN a.assessed_state = 'restricted' THEN 1
    ELSE 2 END)
  INTO v_rights_cap
  FROM rights.delivery_rights_assessment x
  JOIN rights.rights_assessment a ON a.rights_assessment_id = x.rights_assessment_id
  WHERE x.delivery_assessment_id = v_id;

  IF NOT EXISTS (
    SELECT 1 FROM rights.delivery_policy_evaluation x
    WHERE x.delivery_assessment_id = v_id
  ) OR EXISTS (
    SELECT 1 FROM rights.delivery_policy_evaluation x
    JOIN rights.provider_policy_evaluation e
      ON e.provider_policy_evaluation_id = x.provider_policy_evaluation_id
    WHERE x.delivery_assessment_id = v_id
      AND (e.object_visual_reference_id IS DISTINCT FROM v_bridge
        OR e.evaluated_at > v_assessed_at
        OR EXISTS (
          SELECT 1 FROM rights.provider_policy_evaluation newer
          WHERE newer.supersedes_provider_policy_evaluation_id =
            e.provider_policy_evaluation_id
        ))
  ) OR EXISTS (
    SELECT 1 FROM rights.provider_policy_evaluation e
    WHERE e.object_visual_reference_id = v_bridge
      AND NOT EXISTS (
        SELECT 1 FROM rights.provider_policy_evaluation newer
        WHERE newer.supersedes_provider_policy_evaluation_id =
          e.provider_policy_evaluation_id
      )
      AND NOT EXISTS (
        SELECT 1 FROM rights.delivery_policy_evaluation linked
        WHERE linked.delivery_assessment_id = v_id
          AND linked.provider_policy_evaluation_id =
            e.provider_policy_evaluation_id
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'DELIVERY_REQUIRES_APPLICABLE_PROVIDER_POLICY_EVALUATION';
  END IF;

  SELECT min(rights.policy_rank(e.evaluated_state))
  INTO v_policy_cap
  FROM rights.delivery_policy_evaluation x
  JOIN rights.provider_policy_evaluation e
    ON e.provider_policy_evaluation_id = x.provider_policy_evaluation_id
  WHERE x.delivery_assessment_id = v_id;

  IF v_attribution IS NULL THEN
    v_attribution_cap := 2;
  ELSIF NOT EXISTS (
    SELECT 1 FROM rights.attribution_bundle a
    WHERE a.attribution_bundle_id = v_attribution
      AND a.object_visual_reference_id = v_bridge
      AND a.evidence_item_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM rights.attribution_bundle newer
        WHERE newer.supersedes_attribution_bundle_id = a.attribution_bundle_id
      )
      AND 1 = (
        SELECT count(*) FROM rights.attribution_bundle current_bundle
        WHERE current_bundle.object_visual_reference_id = v_bridge
          AND NOT EXISTS (
            SELECT 1 FROM rights.attribution_bundle newer
            WHERE newer.supersedes_attribution_bundle_id =
              current_bundle.attribution_bundle_id
          )
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'DELIVERY_ATTRIBUTION_BUNDLE_BRIDGE_MISMATCH';
  ELSIF EXISTS (
    SELECT 1 FROM rights.attribution_bundle a
    WHERE a.attribution_bundle_id = v_attribution
      AND a.validated_at > v_assessed_at
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'DELIVERY_ATTRIBUTION_POSTDATES_DECISION';
  ELSIF EXISTS (
    SELECT 1 FROM rights.attribution_bundle a
    WHERE a.attribution_bundle_id = v_attribution
      AND a.bundle_sha256 IS DISTINCT FROM
        rights.compute_attribution_bundle_sha(a.attribution_bundle_id)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'ATTRIBUTION_BUNDLE_HASH_MISMATCH';
  ELSIF EXISTS (
    SELECT 1 FROM rights.attribution_bundle a
    WHERE a.attribution_bundle_id = v_attribution
      AND a.attribution_state = 'complete'
      AND EXISTS (
        SELECT 1 FROM rights.attribution_bundle_value x
        WHERE x.attribution_bundle_id = a.attribution_bundle_id
          AND x.value_kind = 'attribution'
      )
      AND EXISTS (
        SELECT 1 FROM rights.attribution_bundle_value x
        WHERE x.attribution_bundle_id = a.attribution_bundle_id
          AND x.value_kind = 'required_statement'
      )
  ) THEN
    v_attribution_cap := 4;
  ELSE
    v_attribution_cap := 2;
  END IF;

  SELECT COALESCE(min(CASE e.action WHEN 'blocked' THEN 0 ELSE 1 END), 4)
  INTO v_takedown_cap
  FROM rights.takedown_event e
  JOIN rights.takedown_scope s ON s.takedown_event_id = e.takedown_event_id
  WHERE e.effective_from <= v_assessed_at
    AND (e.effective_until IS NULL OR e.effective_until > v_assessed_at)
    AND rights.scope_matches_bridge(s.takedown_scope_id, v_bridge);

  IF rights.delivery_rank(v_mode) > LEAST(
    v_rights_cap, v_policy_cap, v_attribution_cap, v_takedown_cap
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'DELIVERY_ASSESSMENT_EXCEEDS_FAIL_CLOSED_CAP';
  END IF;

  v_required_role := CASE v_mode
    WHEN 'link_only' THEN 'canonical_record'::rights.locator_role
    WHEN 'source_viewer' THEN 'source_viewer'::rights.locator_role
    WHEN 'remote_image' THEN 'direct_image'::rights.locator_role
    ELSE NULL
  END;

  IF EXISTS (
    SELECT 1
    FROM rights.delivery_locator_qualification q
    JOIN rights.visual_locator l ON l.visual_locator_id = q.visual_locator_id
    JOIN rights.endpoint_health_observation h
      ON h.endpoint_health_observation_id = q.endpoint_health_observation_id
    JOIN rights.object_visual_reference b ON b.object_visual_reference_id = v_bridge
    WHERE q.delivery_assessment_id = v_id
      AND (
        l.external_visual_reference_id IS DISTINCT FROM b.external_visual_reference_id
        OR l.locator_role IS DISTINCT FROM q.allowlisted_role
        OR h.visual_locator_id IS DISTINCT FROM l.visual_locator_id
        OR h.health_state <> 'healthy_fresh'
        OR h.checked_at > v_assessed_at
        OR h.valid_until IS NULL
        OR h.valid_until <= v_assessed_at
        OR EXISTS (
          SELECT 1 FROM rights.visual_locator newer
          WHERE newer.supersedes_visual_locator_id = l.visual_locator_id
        )
      )
  ) OR (v_required_role IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM rights.delivery_locator_qualification q
    WHERE q.delivery_assessment_id = v_id
      AND q.allowlisted_role = v_required_role
  )) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'DELIVERY_REQUIRES_MATCHING_HEALTHY_FRESH_TYPED_LOCATOR';
  END IF;
  RETURN;
END
$$;


--
-- Name: validate_one_object_visual_reference(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.validate_one_object_visual_reference(p_bridge_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_bridge rights.object_visual_reference%ROWTYPE;
  v_current_count integer;
  v_current rights.object_visual_reference_review_decision%ROWTYPE;
BEGIN
  SELECT * INTO v_bridge
  FROM rights.object_visual_reference b
  WHERE b.object_visual_reference_id = p_bridge_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT count(*) INTO v_current_count
  FROM rights.object_visual_reference_review_decision d
  WHERE d.object_visual_reference_id = p_bridge_id
    AND NOT EXISTS (
      SELECT 1
      FROM rights.object_visual_reference_review_decision newer
      WHERE newer.supersedes_decision_id =
        d.object_visual_reference_review_decision_id
    );
  IF v_current_count > 1 THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'VISUAL_BRIDGE_REQUIRES_AT_MOST_ONE_CURRENT_DECISION';
  END IF;
  IF v_current_count = 1 THEN
    SELECT * INTO STRICT v_current
    FROM rights.object_visual_reference_review_decision d
    WHERE d.object_visual_reference_id = p_bridge_id
      AND NOT EXISTS (
        SELECT 1
        FROM rights.object_visual_reference_review_decision newer
        WHERE newer.supersedes_decision_id =
          d.object_visual_reference_review_decision_id
      );
  END IF;

  IF v_bridge.acceptance_state = 'accepted' AND (
      v_current_count <> 1 OR v_bridge.evidence_item_id IS NULL
      OR v_current.outcome <> 'accept'
      OR v_current.evidence_item_id IS DISTINCT FROM v_bridge.evidence_item_id
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'ACCEPTED_VISUAL_BRIDGE_REQUIRES_EVIDENCE_BOUND_ACCEPT_DECISION';
  ELSIF v_bridge.acceptance_state = 'rejected' AND (
      v_current_count <> 1 OR v_current.outcome <> 'reject'
      OR v_current.evidence_item_id IS DISTINCT FROM v_bridge.evidence_item_id
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'REJECTED_VISUAL_BRIDGE_REQUIRES_EVIDENCE_BOUND_REJECT_DECISION';
  ELSIF v_bridge.acceptance_state = 'superseded' AND (
      v_current_count <> 1 OR v_current.outcome <> 'supersede'
      OR v_current.evidence_item_id IS DISTINCT FROM v_bridge.evidence_item_id
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'SUPERSEDED_VISUAL_BRIDGE_REQUIRES_EVIDENCE_BOUND_DECISION';
  ELSIF v_bridge.acceptance_state = 'proposed' AND (
      v_current_count = 1 AND (
        v_current.outcome <> 'hold'
        OR v_current.evidence_item_id IS DISTINCT FROM
          v_bridge.evidence_item_id
      )
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'PROPOSED_VISUAL_BRIDGE_DECISION_MUST_BE_EVIDENCE_BOUND_HOLD';
  END IF;
END
$$;


--
-- Name: validate_one_provider_policy_evaluation(uuid); Type: FUNCTION; Schema: rights; Owner: -
--

CREATE FUNCTION rights.validate_one_provider_policy_evaluation(p_evaluation_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_id uuid := p_evaluation_id;
  v_state rights.policy_state;
  v_bridge uuid;
  v_provider uuid;
  v_count integer;
  v_evaluated_at timestamptz;
BEGIN
  SELECT e.evaluated_state, e.object_visual_reference_id, e.evaluated_at
  INTO v_state, v_bridge, v_evaluated_at
  FROM rights.provider_policy_evaluation e
  WHERE e.provider_policy_evaluation_id = v_id;
  IF NOT FOUND THEN RETURN; END IF;
  IF v_evaluated_at > clock_timestamp() THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'FUTURE_PROVIDER_POLICY_EVALUATION_DENIED';
  END IF;

  SELECT po.provider_id INTO v_provider
  FROM rights.object_visual_reference b
  JOIN rights.external_visual_reference vr
    ON vr.external_visual_reference_id = b.external_visual_reference_id
  LEFT JOIN rights.provider_object po ON po.provider_object_id = vr.provider_object_id
  WHERE b.object_visual_reference_id = v_bridge;

  SELECT count(*) INTO v_count
  FROM rights.provider_policy_evaluation_version x
  WHERE x.provider_policy_evaluation_id = v_id;

  IF v_provider IS NULL THEN
    IF v_count <> 0 OR v_state NOT IN ('unknown', 'missing') THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'UNMAPPED_PROVIDER_POLICY_MUST_FAIL_CLOSED';
    END IF;
  ELSIF v_state IN ('unknown', 'missing') THEN
    IF v_count <> 0 THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'UNKNOWN_OR_MISSING_POLICY_MUST_NOT_CLAIM_VERSION';
    END IF;
  ELSIF v_count = 0 OR EXISTS (
    SELECT 1
    FROM rights.provider_policy_evaluation_version x
    JOIN rights.provider_policy_version pv
      ON pv.provider_policy_version_id = x.provider_policy_version_id
    WHERE x.provider_policy_evaluation_id = v_id
      AND (
        pv.provider_id IS DISTINCT FROM v_provider
        OR rights.policy_rank(v_state) > rights.policy_rank(pv.policy_state)
        OR (v_state = 'remote_display_allowed'
          AND pv.source_evidence_item_id IS NULL)
        OR (v_state NOT IN ('stale', 'conflict') AND (
          pv.effective_from > v_evaluated_at
          OR (pv.effective_until IS NOT NULL
            AND pv.effective_until <= v_evaluated_at)
          OR pv.review_due <= v_evaluated_at
        ))
      )
  ) OR EXISTS (
    SELECT 1
    FROM rights.provider_policy_version pv
    WHERE pv.provider_id = v_provider
      AND pv.effective_from <= v_evaluated_at
      AND (pv.effective_until IS NULL OR pv.effective_until > v_evaluated_at)
      AND NOT EXISTS (
        SELECT 1 FROM rights.provider_policy_evaluation_version x
        WHERE x.provider_policy_evaluation_id = v_id
          AND x.provider_policy_version_id = pv.provider_policy_version_id
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'PROVIDER_POLICY_EVALUATION_PROVIDER_CAP_OR_COMPLETENESS_VIOLATION';
  END IF;
  RETURN;
END
$$;


--
-- Name: claim_review_case(uuid); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.claim_review_case(p_review_case_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM rights.require_reviewer();
  UPDATE workflow.review_case
  SET queue_state = 'claimed', claimed_by = session_user::text,
    claimed_at = clock_timestamp()
  WHERE review_case_id = p_review_case_id AND queue_state = 'queued';
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '55000',
      MESSAGE = 'REVIEW_CASE_NOT_CLAIMABLE';
  END IF;
END
$$;


--
-- Name: enforce_review_case_subtype(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.enforce_review_case_subtype() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_new_id uuid; v_old_id uuid;
BEGIN
  IF TG_OP <> 'DELETE' THEN
    v_new_id := (to_jsonb(NEW) ->> 'review_case_id')::uuid;
    PERFORM workflow.validate_one_review_case(v_new_id);
  END IF;
  IF TG_OP <> 'INSERT' THEN
    v_old_id := (to_jsonb(OLD) ->> 'review_case_id')::uuid;
    IF v_old_id IS DISTINCT FROM v_new_id THEN
      PERFORM workflow.validate_one_review_case(v_old_id);
    END IF;
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: validate_one_review_case(uuid); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.validate_one_review_case(p_case_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_kind workflow.case_kind;
  v_total integer;
  v_expected integer;
BEGIN
  SELECT case_kind INTO v_kind FROM workflow.review_case
  WHERE review_case_id = p_case_id;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT
    (SELECT count(*) FROM workflow.review_case_assertion x WHERE x.review_case_id = p_case_id) +
    (SELECT count(*) FROM workflow.review_case_assignment x WHERE x.review_case_id = p_case_id) +
    (SELECT count(*) FROM workflow.review_case_claim x WHERE x.review_case_id = p_case_id) +
    (SELECT count(*) FROM workflow.review_case_relation x WHERE x.review_case_id = p_case_id) +
    (SELECT count(*) FROM workflow.review_case_relation_type_literal x WHERE x.review_case_id = p_case_id) +
    (SELECT count(*) FROM workflow.review_case_rights_assessment x WHERE x.review_case_id = p_case_id)
  INTO v_total;
  v_expected := CASE v_kind
    WHEN 'assertion' THEN (SELECT count(*) FROM workflow.review_case_assertion x WHERE x.review_case_id = p_case_id)
    WHEN 'canonical_assignment' THEN (SELECT count(*) FROM workflow.review_case_assignment x WHERE x.review_case_id = p_case_id)
    WHEN 'claim_revision' THEN (SELECT count(*) FROM workflow.review_case_claim x WHERE x.review_case_id = p_case_id)
    WHEN 'semantic_relation' THEN (SELECT count(*) FROM workflow.review_case_relation x WHERE x.review_case_id = p_case_id)
    WHEN 'relation_type_literal' THEN (SELECT count(*) FROM workflow.review_case_relation_type_literal x WHERE x.review_case_id = p_case_id)
    WHEN 'rights_assessment' THEN (SELECT count(*) FROM workflow.review_case_rights_assessment x WHERE x.review_case_id = p_case_id)
  END;
  IF v_total <> 1 OR v_expected <> 1 THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'WORKFLOW_REVIEW_CASE_EXACT_SUBTYPE_VIOLATION';
  END IF;
END
$$;


--
-- Name: visual_health_sidecar_event; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.visual_health_sidecar_event (
    visual_health_sidecar_event_id uuid NOT NULL,
    visual_registry_release_id uuid NOT NULL,
    visual_registry_entry_id uuid NOT NULL,
    visual_locator_id uuid NOT NULL,
    endpoint_health_observation_id uuid NOT NULL,
    locator_role rights.locator_role NOT NULL,
    health_state rights.health_state NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    valid_until timestamp with time zone,
    observation_sha256 core.sha256_hex NOT NULL,
    CONSTRAINT visual_health_sidecar_event_check CHECK (((valid_until IS NULL) OR (valid_until > observed_at)))
);


--
-- Name: visual_takedown_sidecar_event; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.visual_takedown_sidecar_event (
    visual_takedown_sidecar_event_id uuid NOT NULL,
    visual_registry_release_id uuid NOT NULL,
    visual_registry_entry_id uuid NOT NULL,
    takedown_override_id uuid NOT NULL,
    restrictive_mode rights.delivery_mode NOT NULL,
    overlay_sha256 core.sha256_hex NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_until timestamp with time zone,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT visual_takedown_sidecar_event_check CHECK (((effective_until IS NULL) OR (effective_until > effective_from))),
    CONSTRAINT visual_takedown_sidecar_event_restrictive_mode_check CHECK ((restrictive_mode = ANY (ARRAY['blocked'::rights.delivery_mode, 'citation_only'::rights.delivery_mode])))
);


--
-- Name: effective_visual_entry; Type: VIEW; Schema: release; Owner: -
--

CREATE VIEW release.effective_visual_entry WITH (security_barrier='true') AS
 WITH selected_locator AS (
         SELECT l.visual_registry_release_id,
            l.visual_registry_entry_id,
            l.visual_locator_id,
            l.locator_role,
            l.public_locator,
            l.health_state AS sealed_health_state,
            l.health_observed_at AS sealed_observed_at,
            l.health_valid_until AS sealed_valid_until
           FROM release.visual_registry_public_locator l
        ), latest_health AS (
         SELECT DISTINCT ON (h.visual_registry_release_id, h.visual_registry_entry_id, h.visual_locator_id) h.visual_registry_release_id,
            h.visual_registry_entry_id,
            h.visual_locator_id,
            h.health_state,
            h.observed_at,
            h.valid_until
           FROM release.visual_health_sidecar_event h
          WHERE (h.observed_at <= clock_timestamp())
          ORDER BY h.visual_registry_release_id, h.visual_registry_entry_id, h.visual_locator_id, h.observed_at DESC, h.visual_health_sidecar_event_id DESC
        ), locator_effective AS (
         SELECT s.visual_registry_release_id,
            s.visual_registry_entry_id,
            s.visual_locator_id,
            s.locator_role,
            s.public_locator,
            s.sealed_health_state,
            s.sealed_observed_at,
            s.sealed_valid_until,
            COALESCE(h.health_state, s.sealed_health_state) AS effective_health_state,
            COALESCE(h.observed_at, s.sealed_observed_at) AS effective_observed_at,
                CASE
                    WHEN (h.visual_locator_id IS NULL) THEN s.sealed_valid_until
                    ELSE h.valid_until
                END AS effective_valid_until,
            ((COALESCE(h.health_state, s.sealed_health_state) = 'healthy_fresh'::rights.health_state) AND (COALESCE(h.observed_at, s.sealed_observed_at) <= clock_timestamp()) AND (
                CASE
                    WHEN (h.visual_locator_id IS NULL) THEN s.sealed_valid_until
                    ELSE h.valid_until
                END > clock_timestamp())) AS is_healthy_fresh
           FROM (selected_locator s
             LEFT JOIN latest_health h USING (visual_registry_release_id, visual_registry_entry_id, visual_locator_id))
        ), locator_rollup AS (
         SELECT l.visual_registry_release_id,
            l.visual_registry_entry_id,
            max(l.public_locator) FILTER (WHERE ((l.locator_role = 'canonical_record'::rights.locator_role) AND l.is_healthy_fresh)) AS canonical_record_url,
            max(l.public_locator) FILTER (WHERE ((l.locator_role = 'source_viewer'::rights.locator_role) AND l.is_healthy_fresh)) AS source_viewer_url,
            max(l.public_locator) FILTER (WHERE ((l.locator_role = 'direct_image'::rights.locator_role) AND l.is_healthy_fresh)) AS remote_image_url,
            max((l.effective_health_state)::text) FILTER (WHERE (l.locator_role = 'direct_image'::rights.locator_role)) AS pixel_health_state
           FROM locator_effective l
          GROUP BY l.visual_registry_release_id, l.visual_registry_entry_id
        ), attribution_rollup AS (
         SELECT a.visual_registry_release_id,
            a.visual_registry_entry_id,
            jsonb_agg(jsonb_build_object('ordinal', a.value_ordinal, 'language', a.language_tag, 'value', a.value_text) ORDER BY a.value_ordinal) FILTER (WHERE (a.value_kind = 'attribution'::text)) AS attribution_values,
            jsonb_agg(jsonb_build_object('ordinal', a.value_ordinal, 'language', a.language_tag, 'value', a.value_text) ORDER BY a.value_ordinal) FILTER (WHERE (a.value_kind = 'required_statement'::text)) AS required_statement_values
           FROM release.visual_registry_attribution_value a
          GROUP BY a.visual_registry_release_id, a.visual_registry_entry_id
        ), policy_cap AS (
         SELECT e.visual_registry_release_id,
            e.visual_registry_entry_id,
            COALESCE(min(
                CASE
                    WHEN ((p.effective_from > clock_timestamp()) OR (p.review_due <= clock_timestamp()) OR ((p.effective_until IS NOT NULL) AND (p.effective_until <= clock_timestamp()))) THEN 1
                    WHEN (p.policy_state = 'remote_display_allowed'::rights.policy_state) THEN 4
                    WHEN (p.policy_state = 'source_viewer_only'::rights.policy_state) THEN 3
                    WHEN (p.policy_state = 'link_only'::rights.policy_state) THEN 2
                    WHEN (p.policy_state = 'citation_only'::rights.policy_state) THEN 1
                    WHEN (p.policy_state = 'disallowed'::rights.policy_state) THEN 0
                    ELSE 1
                END), 1) AS delivery_cap
           FROM (((release.visual_registry_entry e
             LEFT JOIN release.visual_registry_delivery_policy_snapshot dp ON (((dp.visual_registry_release_id = e.visual_registry_release_id) AND (dp.delivery_assessment_id = e.delivery_assessment_id))))
             LEFT JOIN release.visual_registry_policy_evaluation_version_snapshot ev ON (((ev.visual_registry_release_id = dp.visual_registry_release_id) AND (ev.provider_policy_evaluation_id = dp.provider_policy_evaluation_id))))
             LEFT JOIN release.visual_registry_policy_version_snapshot p ON (((p.visual_registry_release_id = ev.visual_registry_release_id) AND (p.provider_policy_version_id = ev.provider_policy_version_id))))
          GROUP BY e.visual_registry_release_id, e.visual_registry_entry_id
        ), sidecar_takedown AS (
         SELECT t.visual_registry_release_id,
            t.visual_registry_entry_id,
            t.restrictive_mode,
            t.overlay_sha256,
            t.effective_from
           FROM release.visual_takedown_sidecar_event t
          WHERE (t.effective_from <= clock_timestamp())
        ), sealed_takedown AS (
         SELECT t.visual_registry_release_id,
            t.visual_registry_entry_id,
            t.restrictive_mode,
            t.overlay_sha256,
            t.effective_from
           FROM release.visual_registry_takedown_snapshot t
          WHERE (t.effective_from <= clock_timestamp())
        ), all_takedowns AS (
         SELECT sidecar_takedown.visual_registry_release_id,
            sidecar_takedown.visual_registry_entry_id,
            sidecar_takedown.restrictive_mode,
            sidecar_takedown.overlay_sha256,
            sidecar_takedown.effective_from
           FROM sidecar_takedown
        UNION ALL
         SELECT sealed_takedown.visual_registry_release_id,
            sealed_takedown.visual_registry_entry_id,
            sealed_takedown.restrictive_mode,
            sealed_takedown.overlay_sha256,
            sealed_takedown.effective_from
           FROM sealed_takedown
        ), latched_takedown AS (
         SELECT DISTINCT ON (t.visual_registry_release_id, t.visual_registry_entry_id) t.visual_registry_release_id,
            t.visual_registry_entry_id,
            t.restrictive_mode,
            t.overlay_sha256
           FROM all_takedowns t
          ORDER BY t.visual_registry_release_id, t.visual_registry_entry_id,
                CASE t.restrictive_mode
                    WHEN 'blocked'::rights.delivery_mode THEN 0
                    ELSE 1
                END, t.effective_from DESC, t.overlay_sha256
        ), reduced AS (
         SELECT e.visual_registry_release_id,
            e.visual_registry_entry_id,
            e.compatible_research_release_id,
            e.compatible_research_manifest_sha256,
            e.object_visual_reference_id,
            e.archive_object_id,
            e.external_visual_reference_id,
            e.reference_role,
            e.delivery_assessment_id,
            e.object_urn,
            e.visual_reference_urn,
            e.provider_code,
            e.rights_outcome_sha256,
            e.policy_outcome_sha256,
            e.attribution_bundle_sha256,
            e.base_delivery_mode,
            e.reason_code,
            e.machine_reason_code,
            l.canonical_record_url,
            l.source_viewer_url,
            l.remote_image_url,
            l.pixel_health_state,
            a.attribution_values,
            a.required_statement_values,
            t.overlay_sha256,
            t.restrictive_mode,
            p.delivery_cap,
                CASE
                    WHEN (t.restrictive_mode = 'blocked'::rights.delivery_mode) THEN 'blocked'::rights.delivery_mode
                    WHEN (t.restrictive_mode = 'citation_only'::rights.delivery_mode) THEN 'citation_only'::rights.delivery_mode
                    WHEN (e.base_delivery_mode = ANY (ARRAY['blocked'::rights.delivery_mode, 'citation_only'::rights.delivery_mode])) THEN e.base_delivery_mode
                    WHEN (p.delivery_cap < 2) THEN 'citation_only'::rights.delivery_mode
                    WHEN (e.base_delivery_mode = 'link_only'::rights.delivery_mode) THEN
                    CASE
                        WHEN (l.canonical_record_url IS NOT NULL) THEN 'link_only'::rights.delivery_mode
                        ELSE 'citation_only'::rights.delivery_mode
                    END
                    WHEN (e.base_delivery_mode = 'source_viewer'::rights.delivery_mode) THEN
                    CASE
                        WHEN ((p.delivery_cap >= 3) AND (l.source_viewer_url IS NOT NULL)) THEN 'source_viewer'::rights.delivery_mode
                        WHEN (l.canonical_record_url IS NOT NULL) THEN 'link_only'::rights.delivery_mode
                        ELSE 'citation_only'::rights.delivery_mode
                    END
                    WHEN (e.base_delivery_mode = 'remote_image'::rights.delivery_mode) THEN
                    CASE
                        WHEN ((p.delivery_cap >= 4) AND (l.remote_image_url IS NOT NULL)) THEN 'remote_image'::rights.delivery_mode
                        WHEN (l.canonical_record_url IS NOT NULL) THEN 'link_only'::rights.delivery_mode
                        ELSE 'citation_only'::rights.delivery_mode
                    END
                    ELSE 'citation_only'::rights.delivery_mode
                END AS effective_delivery_mode
           FROM ((((release.visual_registry_entry e
             LEFT JOIN locator_rollup l USING (visual_registry_release_id, visual_registry_entry_id))
             LEFT JOIN attribution_rollup a USING (visual_registry_release_id, visual_registry_entry_id))
             LEFT JOIN latched_takedown t USING (visual_registry_release_id, visual_registry_entry_id))
             LEFT JOIN policy_cap p USING (visual_registry_release_id, visual_registry_entry_id))
        ), reasoned AS (
         SELECT r_1.visual_registry_release_id,
            r_1.visual_registry_entry_id,
            r_1.compatible_research_release_id,
            r_1.compatible_research_manifest_sha256,
            r_1.object_visual_reference_id,
            r_1.archive_object_id,
            r_1.external_visual_reference_id,
            r_1.reference_role,
            r_1.delivery_assessment_id,
            r_1.object_urn,
            r_1.visual_reference_urn,
            r_1.provider_code,
            r_1.rights_outcome_sha256,
            r_1.policy_outcome_sha256,
            r_1.attribution_bundle_sha256,
            r_1.base_delivery_mode,
            r_1.reason_code,
            r_1.machine_reason_code,
            r_1.canonical_record_url,
            r_1.source_viewer_url,
            r_1.remote_image_url,
            r_1.pixel_health_state,
            r_1.attribution_values,
            r_1.required_statement_values,
            r_1.overlay_sha256,
            r_1.restrictive_mode,
            r_1.delivery_cap,
            r_1.effective_delivery_mode,
                CASE
                    WHEN (r_1.restrictive_mode = 'blocked'::rights.delivery_mode) THEN 'RD-001'::rights.delivery_rule_id
                    WHEN (r_1.restrictive_mode = 'citation_only'::rights.delivery_mode) THEN 'RD-002'::rights.delivery_rule_id
                    WHEN ((r_1.base_delivery_mode <> ALL (ARRAY['blocked'::rights.delivery_mode, 'citation_only'::rights.delivery_mode])) AND (r_1.delivery_cap < 2)) THEN 'RD-030'::rights.delivery_rule_id
                    WHEN ((r_1.base_delivery_mode = 'link_only'::rights.delivery_mode) AND (r_1.effective_delivery_mode = 'citation_only'::rights.delivery_mode)) THEN 'RD-041'::rights.delivery_rule_id
                    WHEN ((r_1.base_delivery_mode = 'source_viewer'::rights.delivery_mode) AND (r_1.effective_delivery_mode = 'link_only'::rights.delivery_mode)) THEN 'RD-051'::rights.delivery_rule_id
                    WHEN ((r_1.base_delivery_mode = 'source_viewer'::rights.delivery_mode) AND (r_1.effective_delivery_mode = 'citation_only'::rights.delivery_mode)) THEN 'RD-052'::rights.delivery_rule_id
                    WHEN ((r_1.base_delivery_mode = 'remote_image'::rights.delivery_mode) AND (r_1.effective_delivery_mode = 'link_only'::rights.delivery_mode)) THEN 'RD-081'::rights.delivery_rule_id
                    WHEN ((r_1.base_delivery_mode = 'remote_image'::rights.delivery_mode) AND (r_1.effective_delivery_mode = 'citation_only'::rights.delivery_mode)) THEN 'RD-082'::rights.delivery_rule_id
                    ELSE r_1.reason_code
                END AS effective_reason_code
           FROM reduced r_1
        )
 SELECT visual_registry_release_id,
    visual_registry_entry_id,
    archive_object_id,
    external_visual_reference_id,
    object_urn,
    visual_reference_urn,
    provider_code,
    base_delivery_mode,
    effective_delivery_mode,
    effective_reason_code AS reason_code,
    rights.machine_reason_for_rule(effective_reason_code) AS machine_reason_code,
    attribution_values,
    required_statement_values,
    pixel_health_state,
    overlay_sha256,
        CASE
            WHEN (effective_delivery_mode = ANY (ARRAY['link_only'::rights.delivery_mode, 'source_viewer'::rights.delivery_mode, 'remote_image'::rights.delivery_mode])) THEN canonical_record_url
            ELSE NULL::text
        END AS canonical_record_url,
        CASE
            WHEN (effective_delivery_mode = 'source_viewer'::rights.delivery_mode) THEN source_viewer_url
            ELSE NULL::text
        END AS source_viewer_url,
        CASE
            WHEN (effective_delivery_mode = 'remote_image'::rights.delivery_mode) THEN remote_image_url
            ELSE NULL::text
        END AS remote_image_url
   FROM reasoned r;


--
-- Name: public_channel; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.public_channel (
    channel core.release_token NOT NULL,
    public_contract_version core.release_token NOT NULL,
    created_at timestamp with time zone NOT NULL
);


--
-- Name: research_current_pointer; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.research_current_pointer (
    channel core.release_token NOT NULL,
    generation bigint NOT NULL,
    research_release_id uuid,
    manifest_sha256 core.sha256_hex,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT research_current_pointer_check CHECK (((research_release_id IS NULL) = (manifest_sha256 IS NULL))),
    CONSTRAINT research_current_pointer_generation_check CHECK ((generation >= 0))
);


--
-- Name: research_release_verification; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.research_release_verification (
    research_release_verification_id uuid NOT NULL,
    research_release_id uuid NOT NULL,
    manifest_sha256 core.sha256_hex NOT NULL,
    verifier_version core.release_token NOT NULL,
    sidecar_sha256 core.sha256_hex NOT NULL,
    verified boolean NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    seal_transaction_id bigint NOT NULL,
    candidate_fingerprint core.sha256_hex NOT NULL,
    seal_function_version core.release_token NOT NULL,
    attestation_sha256 core.sha256_hex
);


--
-- Name: visual_current_pointer; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.visual_current_pointer (
    channel core.release_token NOT NULL,
    generation bigint NOT NULL,
    visual_registry_release_id uuid,
    manifest_sha256 core.sha256_hex,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT visual_current_pointer_check CHECK (((visual_registry_release_id IS NULL) = (manifest_sha256 IS NULL))),
    CONSTRAINT visual_current_pointer_generation_check CHECK ((generation >= 0))
);


--
-- Name: visual_registry_verification; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.visual_registry_verification (
    visual_registry_verification_id uuid NOT NULL,
    visual_registry_release_id uuid NOT NULL,
    manifest_sha256 core.sha256_hex NOT NULL,
    verifier_version core.release_token NOT NULL,
    sidecar_sha256 core.sha256_hex NOT NULL,
    verified boolean NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    seal_transaction_id bigint NOT NULL,
    candidate_fingerprint core.sha256_hex NOT NULL,
    seal_function_version core.release_token NOT NULL,
    attestation_sha256 core.sha256_hex
);


--
-- Name: current_object; Type: VIEW; Schema: api_v1; Owner: -
--

CREATE VIEW api_v1.current_object WITH (security_barrier='true') AS
 SELECT rr.release_token AS research_release_id,
    rp.manifest_sha256 AS research_manifest_sha256,
        CASE
            WHEN ((vr.compatible_research_release_id = rp.research_release_id) AND ((vr.compatible_research_manifest_sha256)::text = (rp.manifest_sha256)::text)) THEN (vr.registry_version)::text
            ELSE NULL::text
        END AS visual_registry_version,
        CASE
            WHEN ((vr.compatible_research_release_id = rp.research_release_id) AND ((vr.compatible_research_manifest_sha256)::text = (rp.manifest_sha256)::text)) THEN (vp.manifest_sha256)::text
            ELSE NULL::text
        END AS visual_registry_sha256,
        CASE
            WHEN (vp.visual_registry_release_id IS NULL) THEN 'not_selected'::text
            WHEN ((vr.compatible_research_release_id = rp.research_release_id) AND ((vr.compatible_research_manifest_sha256)::text = (rp.manifest_sha256)::text)) THEN 'compatible'::text
            ELSE 'release_version_mismatch'::text
        END AS visual_registry_state,
    ro.archive_object_id AS object_id,
    ro.object_urn,
    ro.legacy_surface_id AS surface_id,
    ro.title,
    ro.publication_layer,
    ro.acceptance_state,
    ev.external_visual_reference_id AS visual_reference_id,
    ev.visual_reference_urn,
    ev.effective_delivery_mode,
    ev.reason_code AS visual_reason_code,
    ev.machine_reason_code AS visual_machine_reason_code,
    ev.pixel_health_state,
    ev.attribution_values,
    ev.required_statement_values,
    ev.overlay_sha256 AS takedown_overlay_sha256,
    ev.canonical_record_url,
    ev.source_viewer_url,
    ev.remote_image_url
   FROM ((((((release.public_channel pc
     JOIN release.research_current_pointer rp ON (((rp.channel)::text = (pc.channel)::text)))
     JOIN release.research_release rr ON (((rr.research_release_id = rp.research_release_id) AND (rr.release_state = 'sealed'::release.release_state) AND (EXISTS ( SELECT 1
           FROM release.research_release_verification verified
          WHERE ((verified.research_release_id = rr.research_release_id) AND ((verified.manifest_sha256)::text = (rr.manifest_sha256)::text) AND verified.verified))))))
     JOIN release.research_release_object ro ON (((ro.research_release_id = rr.research_release_id) AND (ro.acceptance_state = 'accepted'::provenance.assertion_status) AND (ro.publication_layer = 'active'::release.publication_layer))))
     LEFT JOIN release.visual_current_pointer vp ON (((vp.channel)::text = (rp.channel)::text)))
     LEFT JOIN release.visual_registry_release vr ON (((vr.visual_registry_release_id = vp.visual_registry_release_id) AND (vr.release_state = 'sealed'::release.release_state) AND (EXISTS ( SELECT 1
           FROM release.visual_registry_verification verified
          WHERE ((verified.visual_registry_release_id = vr.visual_registry_release_id) AND ((verified.manifest_sha256)::text = (vr.manifest_sha256)::text) AND verified.verified))))))
     LEFT JOIN release.effective_visual_entry ev ON (((ev.visual_registry_release_id = vr.visual_registry_release_id) AND (ev.archive_object_id = ro.archive_object_id) AND (vr.compatible_research_release_id = rp.research_release_id) AND ((vr.compatible_research_manifest_sha256)::text = (rp.manifest_sha256)::text))));


--
-- Name: current_version_status; Type: VIEW; Schema: api_v1; Owner: -
--

CREATE VIEW api_v1.current_version_status WITH (security_barrier='true') AS
 SELECT rp.channel,
    rp.generation AS research_generation,
    rr.release_token AS research_release_id,
    rp.manifest_sha256 AS research_manifest_sha256,
    vp.generation AS visual_generation,
    vr.registry_version AS visual_registry_version,
    vp.manifest_sha256 AS visual_registry_sha256,
        CASE
            WHEN (rp.research_release_id IS NULL) THEN 'research_unavailable'::text
            WHEN (vp.visual_registry_release_id IS NULL) THEN 'not_selected'::text
            WHEN ((vr.compatible_research_release_id = rp.research_release_id) AND ((vr.compatible_research_manifest_sha256)::text = (rp.manifest_sha256)::text)) THEN 'compatible'::text
            ELSE 'release_version_mismatch'::text
        END AS visual_registry_state
   FROM ((((release.public_channel pc
     JOIN release.research_current_pointer rp ON (((rp.channel)::text = (pc.channel)::text)))
     LEFT JOIN release.research_release rr ON ((rr.research_release_id = rp.research_release_id)))
     LEFT JOIN release.visual_current_pointer vp ON (((vp.channel)::text = (rp.channel)::text)))
     LEFT JOIN release.visual_registry_release vr ON ((vr.visual_registry_release_id = vp.visual_registry_release_id)));


--
-- Name: research_publication_history; Type: TABLE; Schema: release; Owner: -
--

CREATE TABLE release.research_publication_history (
    channel core.release_token NOT NULL,
    research_release_id uuid NOT NULL,
    manifest_sha256 core.sha256_hex NOT NULL,
    promoted_generation bigint NOT NULL,
    published_at timestamp with time zone NOT NULL,
    CONSTRAINT research_publication_history_promoted_generation_check CHECK ((promoted_generation > 0))
);


--
-- Name: research_release_descriptor; Type: VIEW; Schema: api_v1; Owner: -
--

CREATE VIEW api_v1.research_release_descriptor WITH (security_barrier='true') AS
 SELECT DISTINCT r.release_token AS research_release_id,
    r.manifest_sha256 AS research_manifest_sha256,
    r.schema_version,
    r.model_version,
    r.sealed_at,
    ( SELECT count(*) AS count
           FROM release.research_release_object o
          WHERE ((o.research_release_id = r.research_release_id) AND (o.acceptance_state = 'accepted'::provenance.assertion_status) AND (o.publication_layer = 'active'::release.publication_layer))) AS object_count,
    ( SELECT count(*) AS count
           FROM release.research_release_relation rel
          WHERE (rel.research_release_id = r.research_release_id)) AS accepted_relation_projection_count,
    ( SELECT count(*) AS count
           FROM release.trace_projection_edge edge
          WHERE (edge.research_release_id = r.research_release_id)) AS trace_projection_edge_count
   FROM ((release.research_publication_history published
     JOIN release.research_release r ON (((r.research_release_id = published.research_release_id) AND ((r.manifest_sha256)::text = (published.manifest_sha256)::text))))
     JOIN release.research_release_verification verified ON (((verified.research_release_id = r.research_release_id) AND ((verified.manifest_sha256)::text = (r.manifest_sha256)::text) AND verified.verified)))
  WHERE (r.release_state = 'sealed'::release.release_state);


--
-- Name: sealed_research_release_descriptor; Type: VIEW; Schema: api_v1; Owner: -
--

CREATE VIEW api_v1.sealed_research_release_descriptor WITH (security_barrier='true') AS
 SELECT (r.research_release_id)::text AS research_release_key,
    r.release_token AS research_release_id,
    r.manifest_sha256 AS research_manifest_sha256,
    r.schema_version,
    r.model_version,
    r.sealed_at,
    ( SELECT count(*) AS count
           FROM release.research_release_object o
          WHERE ((o.research_release_id = r.research_release_id) AND (o.acceptance_state = 'accepted'::provenance.assertion_status) AND (o.publication_layer = 'active'::release.publication_layer))) AS object_count,
    ( SELECT count(*) AS count
           FROM release.research_release_relation rel
          WHERE (rel.research_release_id = r.research_release_id)) AS relation_count,
    ( SELECT count(*) AS count
           FROM release.trace_projection_node n
          WHERE ((n.research_release_id = r.research_release_id) AND (n.archive_object_id IS NOT NULL))) AS trace_eligible_object_count
   FROM (release.research_release r
     JOIN release.research_release_verification verified ON (((verified.research_release_id = r.research_release_id) AND ((verified.manifest_sha256)::text = (r.manifest_sha256)::text) AND verified.verified)))
  WHERE (r.release_state = 'sealed'::release.release_state);


--
-- Name: sealed_surface; Type: VIEW; Schema: api_v1; Owner: -
--

CREATE VIEW api_v1.sealed_surface WITH (security_barrier='true') AS
 SELECT d.research_release_id,
    d.research_manifest_sha256,
    o.legacy_surface_id AS surface_id,
    o.title,
    (o.publication_layer)::text AS publication_layer,
    (o.object_urn)::text AS object_urn
   FROM (api_v1.sealed_research_release_descriptor d
     JOIN release.research_release_object o ON (((o.research_release_id)::text = d.research_release_key)))
  WHERE ((o.acceptance_state = 'accepted'::provenance.assertion_status) AND (o.publication_layer = 'active'::release.publication_layer) AND (o.legacy_surface_id IS NOT NULL));


