-- Name: source_asset; Type: TABLE; Schema: raw; Owner: -
--

CREATE TABLE raw.source_asset (
    source_asset_id uuid NOT NULL,
    authority raw.asset_authority NOT NULL,
    logical_name text NOT NULL,
    sha256 core.sha256_hex NOT NULL,
    byte_length bigint NOT NULL,
    raw_bytes bytea NOT NULL,
    media_type text,
    received_at timestamp with time zone NOT NULL,
    CONSTRAINT source_asset_byte_length_check CHECK ((byte_length >= 0)),
    CONSTRAINT source_asset_byte_length_matches CHECK ((octet_length(raw_bytes) = byte_length)),
    CONSTRAINT source_asset_logical_name_check CHECK ((btrim(logical_name) <> ''::text)),
    CONSTRAINT source_asset_sha256_matches CHECK ((encode(sha256(raw_bytes), 'hex'::text) = (sha256)::text))
);


--
-- Name: source_record; Type: TABLE; Schema: raw; Owner: -
