    legacy_source_record_id text,
    raw_value bytea NOT NULL,
    raw_fingerprint core.sha256_hex NOT NULL,
    parsed_projection jsonb,
    parse_error_code text,
    CONSTRAINT source_record_fingerprint_matches CHECK ((encode(sha256(raw_value), 'hex'::text) = (raw_fingerprint)::text)),
    CONSTRAINT source_record_record_ordinal_check CHECK ((record_ordinal >= 0)),
    CONSTRAINT source_record_value_nonempty CHECK ((octet_length(raw_value) > 0))
);


--
-- Name: raw_hash_inventory; Type: VIEW; Schema: audit; Owner: -
--

CREATE VIEW audit.raw_hash_inventory WITH (security_barrier='true') AS
 SELECT a.source_asset_id,
    a.authority,
    a.logical_name,
    a.sha256,
    a.byte_length,
    a.media_type,
    a.received_at,
    count(r.source_record_id) AS source_record_count
   FROM (raw.source_asset a
     LEFT JOIN raw.source_record r ON ((r.source_asset_id = a.source_asset_id)))
  GROUP BY a.source_asset_id, a.authority, a.logical_name, a.sha256, a.byte_length, a.media_type, a.received_at;


