--
-- Name: release_history_inventory; Type: VIEW; Schema: audit; Owner: -
--

CREATE VIEW audit.release_history_inventory WITH (security_barrier='true') AS
 SELECT 'research'::text AS boundary,
    h.channel,
    h.promoted_generation,
    h.research_release_id AS release_id,
    h.manifest_sha256,
    h.published_at
   FROM release.research_publication_history h
UNION ALL
 SELECT 'visual'::text AS boundary,
    h.channel,
    h.promoted_generation,
    h.visual_registry_release_id AS release_id,
    h.manifest_sha256,
    h.published_at
   FROM release.visual_publication_history h;


