    CONSTRAINT legacy_identity_namespace_check CHECK ((btrim(namespace) <> ''::text))
);


--
-- Name: legacy_identity_resolution; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.legacy_identity_resolution (
    legacy_identity_resolution_id uuid NOT NULL,
    legacy_identity_id uuid NOT NULL,
    resolution_state core.identity_resolution_state NOT NULL,
    target_archive_object_id uuid,
    target_source_record_id uuid,
    target_trace_node_id uuid,
    target_trace_edge_release_id uuid,
    target_trace_edge_corpus_version_id uuid,
    target_trace_edge_subject_node_id uuid,
    target_trace_edge_relation_id uuid,
    target_trace_edge_object_node_id uuid,
    target_trace_edge_projection_role text,
    target_folder_id uuid,
    decision_evidence_item_id uuid,
    effective_release_id uuid,
    supersedes_resolution_id uuid,
    effective_from timestamp with time zone NOT NULL,
    reason_code text NOT NULL,
    CONSTRAINT legacy_identity_resolution_reason_code_check CHECK ((btrim(reason_code) <> ''::text)),
    CONSTRAINT legacy_identity_resolution_target_shape CHECK ((((num_nonnulls(target_trace_edge_release_id, target_trace_edge_corpus_version_id, target_trace_edge_subject_node_id, target_trace_edge_relation_id, target_trace_edge_object_node_id, target_trace_edge_projection_role) = ANY (ARRAY[0, 6])) AND ((resolution_state = ANY (ARRAY['primary'::core.identity_resolution_state, 'alias'::core.identity_resolution_state, 'redirect'::core.identity_resolution_state, 'merged'::core.identity_resolution_state])) AND ((num_nonnulls(target_archive_object_id, target_source_record_id, target_trace_node_id, target_folder_id) +
CASE
    WHEN (target_trace_edge_release_id IS NULL) THEN 0
    ELSE 1
END) = 1))) OR ((resolution_state = ANY (ARRAY['split'::core.identity_resolution_state, 'withdrawn'::core.identity_resolution_state, 'unresolved'::core.identity_resolution_state])) AND (num_nonnulls(target_archive_object_id, target_source_record_id, target_trace_node_id, target_folder_id, target_trace_edge_release_id, target_trace_edge_corpus_version_id, target_trace_edge_subject_node_id, target_trace_edge_relation_id, target_trace_edge_object_node_id, target_trace_edge_projection_role) = 0))))
);


