--
-- Name: publisher_artifact_inventory; Type: VIEW; Schema: release; Owner: -
--

CREATE VIEW release.publisher_artifact_inventory WITH (security_barrier='true') AS
 SELECT 'research'::text AS boundary,
    r.research_release_id AS release_id,
    r.release_token AS version_token,
    r.release_state,
    r.candidate_fingerprint,
    r.manifest_sha256,
    ( SELECT count(*) AS count
           FROM release.research_validation_receipt v
          WHERE ((v.research_release_id = r.research_release_id) AND (v.validation_result = 'pass'::release.validation_result))) AS passing_receipt_count,
    ( SELECT count(*) AS count
           FROM release.research_release_verification v
          WHERE ((v.research_release_id = r.research_release_id) AND v.verified)) AS verification_count
   FROM release.research_release r
UNION ALL
 SELECT 'visual'::text AS boundary,
    r.visual_registry_release_id AS release_id,
    r.registry_version AS version_token,
    r.release_state,
    r.candidate_fingerprint,
    r.manifest_sha256,
    ( SELECT count(*) AS count
           FROM release.visual_validation_receipt v
          WHERE ((v.visual_registry_release_id = r.visual_registry_release_id) AND (v.validation_result = 'pass'::release.validation_result))) AS passing_receipt_count,
    ( SELECT count(*) AS count
           FROM release.visual_registry_verification v
          WHERE ((v.visual_registry_release_id = r.visual_registry_release_id) AND v.verified)) AS verification_count
   FROM release.visual_registry_release r;


