);


--
-- Name: publisher_research_source; Type: VIEW; Schema: release; Owner: -
--

CREATE VIEW release.publisher_research_source WITH (security_barrier='true') AS
 SELECT m.corpus_version_id,
    m.archive_object_id,
    m.disposition,
    m.reason_code,
    o.object_urn,
    o.preferred_label,
    l.surface_id AS legacy_surface_id
   FROM ((research.corpus_membership m
     JOIN core.archive_object o ON ((o.archive_object_id = m.archive_object_id)))
     LEFT JOIN raw.legacy_surface_ledger l ON ((l.archive_object_id = m.archive_object_id)))
  WHERE (m.disposition = ANY (ARRAY['eligible'::research.membership_disposition, 'held'::research.membership_disposition, 'rejected'::research.membership_disposition]));


