    CONSTRAINT visual_locator_fingerprint_matches CHECK ((encode(sha256(convert_to(raw_locator, 'UTF8'::name)), 'hex'::text) = (locator_fingerprint)::text)),
    CONSTRAINT visual_locator_occurrence_ordinal_check CHECK ((occurrence_ordinal >= 0)),
    CONSTRAINT visual_locator_raw_locator_check CHECK ((btrim(raw_locator) <> ''::text)),
    CONSTRAINT visual_locator_source_field_or_json_pointer_check CHECK ((source_field_or_json_pointer ~ '^/'::text))
);


--
-- Name: publisher_visual_source; Type: VIEW; Schema: release; Owner: -
--

CREATE VIEW release.publisher_visual_source WITH (security_barrier='true') AS
 SELECT d.delivery_assessment_id,
    d.object_visual_reference_id,
    d.delivery_mode,
    d.reason_code,
    d.assessed_at,
    b.archive_object_id,
    b.external_visual_reference_id,
    b.reference_role,
    r.visual_reference_urn,
    p.provider_id,
    p.provider_code,
    q.visual_locator_id,
    q.allowlisted_role,
    l.raw_locator,
    h.endpoint_health_observation_id,
    h.health_state,
    h.checked_at,
    h.valid_until,
    rights.compute_delivery_rights_sha(d.delivery_assessment_id) AS rights_outcome_sha256,
    rights.compute_delivery_policy_sha(d.delivery_assessment_id) AS policy_outcome_sha256,
    rights.compute_attribution_bundle_sha(d.attribution_bundle_id) AS attribution_bundle_sha256
   FROM (((((((rights.delivery_assessment d
     JOIN rights.object_visual_reference b ON ((b.object_visual_reference_id = d.object_visual_reference_id)))
     JOIN rights.external_visual_reference r ON ((r.external_visual_reference_id = b.external_visual_reference_id)))
     LEFT JOIN rights.provider_object po ON ((po.provider_object_id = r.provider_object_id)))
     LEFT JOIN rights.provider p ON ((p.provider_id = po.provider_id)))
     LEFT JOIN rights.delivery_locator_qualification q ON ((q.delivery_assessment_id = d.delivery_assessment_id)))
     LEFT JOIN rights.visual_locator l ON ((l.visual_locator_id = q.visual_locator_id)))
     LEFT JOIN rights.endpoint_health_observation h ON ((h.endpoint_health_observation_id = q.endpoint_health_observation_id)))
  WHERE (NOT (EXISTS ( SELECT 1
           FROM rights.delivery_assessment newer
          WHERE (newer.supersedes_delivery_assessment_id = d.delivery_assessment_id))));


