--
-- Name: ingest_metadata_context; Type: VIEW; Schema: workflow; Owner: -
--

CREATE VIEW workflow.ingest_metadata_context WITH (security_barrier='true') AS
 SELECT a.source_asset_id,
    a.logical_name,
    a.sha256 AS asset_sha256,
    r.source_record_id,
    r.record_ordinal,
    r.raw_fingerprint,
    f.field_literal_id,
    f.json_pointer,
    f.occurrence_ordinal
   FROM ((raw.source_asset a
     LEFT JOIN raw.source_record r ON ((r.source_asset_id = a.source_asset_id)))
     LEFT JOIN raw.field_literal f ON ((f.source_record_id = r.source_record_id)))
  WHERE (a.authority = 'governed_source'::raw.asset_authority);


