    reason_code text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT relation_type_review_queue_queue_state_check CHECK ((queue_state = ANY (ARRAY['queued'::workflow.queue_state, 'claimed'::workflow.queue_state, 'in_review'::workflow.queue_state, 'superseded'::workflow.queue_state]))),
    CONSTRAINT relation_type_review_queue_reason_code_check CHECK ((btrim(reason_code) <> ''::text)),
    CONSTRAINT relation_type_review_queue_source_label_literal_check CHECK ((btrim(source_label_literal) <> ''::text))
);


