    queue_state workflow.queue_state NOT NULL,
    priority smallint DEFAULT 0 NOT NULL,
    reason_code text NOT NULL,
    claimed_by text,
    claimed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    resolved_at timestamp with time zone,
    CONSTRAINT review_case_check CHECK (((queue_state = ANY (ARRAY['claimed'::workflow.queue_state, 'in_review'::workflow.queue_state])) = ((claimed_by IS NOT NULL) AND (claimed_at IS NOT NULL)))),
    CONSTRAINT review_case_check1 CHECK (((queue_state = 'resolved'::workflow.queue_state) = (resolved_at IS NOT NULL))),
    CONSTRAINT review_case_priority_check CHECK (((priority >= 0) AND (priority <= 100))),
    CONSTRAINT review_case_reason_code_check CHECK ((reason_code ~ '^[A-Z][A-Z0-9_]*$'::text))
);


