--
-- Name: reviewer_provenance_context; Type: VIEW; Schema: workflow; Owner: -
--

CREATE VIEW workflow.reviewer_provenance_context WITH (security_barrier='true') AS
 SELECT c.review_case_id,
    c.case_kind,
    p.assertion_id,
    p.assertion_predicate_id,
    p.subject_kind,
    p.value_kind,
    p.status AS assertion_status,
    x.canonical_assignment_id,
    x.assignment_kind,
    x.status AS assignment_status,
    q.claim_revision_id,
    q.status AS claim_status,
    r.semantic_relation_id,
    r.status AS relation_status
   FROM ((((((((workflow.review_case c
     LEFT JOIN workflow.review_case_assertion ca USING (review_case_id))
     LEFT JOIN provenance.assertion p ON ((p.assertion_id = ca.assertion_id)))
     LEFT JOIN workflow.review_case_assignment cx USING (review_case_id))
     LEFT JOIN provenance.canonical_assignment x ON ((x.canonical_assignment_id = cx.canonical_assignment_id)))
     LEFT JOIN workflow.review_case_claim cq USING (review_case_id))
     LEFT JOIN research.claim_revision q ON ((q.claim_revision_id = cq.claim_revision_id)))
     LEFT JOIN workflow.review_case_relation cr USING (review_case_id))
     LEFT JOIN research.semantic_relation r ON ((r.semantic_relation_id = cr.semantic_relation_id)))
  WHERE ((c.queue_state = 'queued'::workflow.queue_state) OR (c.claimed_by = (SESSION_USER)::text));


--
-- Name: reviewer_queue; Type: VIEW; Schema: workflow; Owner: -
--

CREATE VIEW workflow.reviewer_queue WITH (security_barrier='true') AS
 SELECT c.review_case_id,
    c.case_kind,
    c.queue_state,
    c.priority,
    c.reason_code,
    c.claimed_by,
    c.claimed_at,
    c.created_at,
    a.assertion_id,
    x.canonical_assignment_id,
    q.claim_revision_id,
    r.semantic_relation_id,
    t.relation_type_review_queue_id,
    z.rights_assessment_id
   FROM ((((((workflow.review_case c
     LEFT JOIN workflow.review_case_assertion a USING (review_case_id))
     LEFT JOIN workflow.review_case_assignment x USING (review_case_id))
     LEFT JOIN workflow.review_case_claim q USING (review_case_id))
     LEFT JOIN workflow.review_case_relation r USING (review_case_id))
     LEFT JOIN workflow.review_case_relation_type_literal t USING (review_case_id))
     LEFT JOIN workflow.review_case_rights_assessment z USING (review_case_id))
  WHERE ((c.queue_state = 'queued'::workflow.queue_state) OR (c.claimed_by = (SESSION_USER)::text));


--
-- Name: reviewer_source_context; Type: VIEW; Schema: workflow; Owner: -
--

CREATE VIEW workflow.reviewer_source_context WITH (security_barrier='true') AS
 SELECT c.review_case_id,
    f.field_literal_id,
    f.json_pointer,
    f.occurrence_ordinal,
    f.raw_text,
    f.raw_bytes,
    r.source_record_id,
    r.raw_fingerprint,
    r.parse_error_code,
    a.source_asset_id,
    a.authority,
    a.logical_name,
    a.sha256 AS asset_sha256
   FROM (((((workflow.review_case c
     JOIN workflow.review_case_assertion ca USING (review_case_id))
     JOIN provenance.assertion_value_literal av ON ((av.assertion_id = ca.assertion_id)))
     JOIN raw.field_literal f ON ((f.field_literal_id = av.field_literal_id)))
     JOIN raw.source_record r ON ((r.source_record_id = f.source_record_id)))
     JOIN raw.source_asset a ON ((a.source_asset_id = r.source_asset_id)))
  WHERE ((c.queue_state = 'queued'::workflow.queue_state) OR (c.claimed_by = (SESSION_USER)::text));


